#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct EvidenceIr {
    pub schema_version: u32,
    pub stage: IrStage,
    pub source_ir_path: PathBuf,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_path_origin: Option<PersistedPathOrigin>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub prior_memory_path: Option<PathBuf>,
    pub artifact_layout: EvidenceArtifactLayout,
    pub document_identity: EvidenceDocumentIdentity,
    pub section_anchors: Vec<SectionAnchor>,
    pub evidence_spans: Vec<EvidenceSpan>,
    pub visual_evidence: Vec<VisualEvidenceItem>,
    pub evidence_links: Vec<EvidenceLink>,
    pub extracted_statements: Vec<ExtractedStatement>,
    /// Register records synthesized from `register_map` tables in `SourceIR`.
    #[serde(default)]
    pub register_records: Vec<RegisterRecord>,
    /// Timing constraint records synthesized from `timing_parameter` tables in `SourceIR`.
    #[serde(default)]
    pub timing_constraints: Vec<TimingConstraintRecord>,
    /// Level 2 NLP: structured records extracted from `SignalValueConstraint` sentences.
    #[serde(default)]
    pub signal_constraints: Vec<SignalConstraintRecord>,
    /// Level 2 NLP: structured records extracted from `ConditionalRule` sentences.
    #[serde(default)]
    pub conditional_rules: Vec<ConditionalRuleRecord>,
    /// CVE-PROSE-EXTRACTION: `ActorContract`s extracted from prose by the
    /// `extract-contracts` command (Qwen via Ollama), each fails-closed parsed
    /// (`parse_constrained_contract`) + entailment-gated
    /// (`apply_entailment_to_contract`). Additive + serde-skip-if-empty ⇒ zero
    /// artifact churn until the producer runs; `SemanticIr::build` folds these
    /// into `actor_contracts` before fusion/fidelity.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub extracted_contracts: Vec<crate::ir::contract::ActorContract>,
    /// CVE-PROSE-EXTRACTION: producer-time extraction stats (the
    /// `schema_rejects` count cannot be derived from survivors). Carried
    /// `EvidenceIR → SemanticIR → IntentIR` for the `validate` `constrained:`
    /// block. `None` until the producer runs.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub constrained_extraction_stats: Option<crate::ir::cve::ConstrainedExtractionStats>,
    /// Provenance links from table-synthesized signal declarations back to SourceIR tables.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub table_signal_declaration_provenance: Vec<TableSignalDeclarationProvenanceRecord>,
    /// KG-ISF-TRANSACTIONS.2m: each declared signal's document-grounded CHANNEL, recovered
    /// from the table that declared it when that table's caption is of the universal
    /// `<role> channel signals` form. Carried forward so the IntentIR
    /// transaction recognizer can group a transaction's signal-set membership by channel.
    /// Empty (serde-skipped) on any document without `<role> channel signals` captions.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub signal_channel_memberships: Vec<SignalChannelMembershipRecord>,
    /// Resolved signal polarity facts recovered from prose/table evidence.
    /// These remain explicit so downstream layers can interpret asserted/deasserted
    /// semantics without blindly collapsing them to HIGH/LOW.
    #[serde(default)]
    pub signal_polarities: Vec<SignalPolarityRecord>,
    /// Explicit conflicts where polarity evidence disagrees across prose/table sources.
    /// These conflicts stay visible instead of silently collapsing into a neutral fallback.
    #[serde(default)]
    pub signal_polarity_conflicts: Vec<SignalPolarityConflictRecord>,
    /// Typed semantic hints mined from tables, prose, and alias-grounded prose descriptions,
    /// kept explicit so later semantic stages can use meaning-based roles instead of literal
    /// signal spelling alone.
    #[serde(default)]
    pub signal_semantic_hints: Vec<SignalSemanticHintRecord>,
    /// Explicit conflicts where semantic-role evidence assigns incompatible roles to the same
    /// signal. These conflicts stay visible instead of silently collapsing into an ambiguous
    /// dual-tag fallback.
    #[serde(default)]
    pub signal_semantic_conflicts: Vec<SignalSemanticConflictRecord>,
    /// Tier 2 Knowledge Graph: actor–signal relation triples extracted from prose verb phrases.
    /// Each record encodes (actor, drives|reads, signal) derived from sentences like
    /// "PREADY is driven by the slave" or "The Manager drives HTRANS".
    /// Together these form the structural knowledge graph of the specification.
    #[serde(default)]
    pub actor_signal_relations: Vec<ActorSignalRelation>,
    /// Form 2 signal alias map
    /// extracts a constraint from a sentence where the signal name doesn't appear
    /// literally (e.g. "address bus" → "HADDR").  Persisted across runs so the
    /// alias vocabulary accumulates.  Applied at the start of each enrichment pass
    /// to reclassify remaining NormativeStatements without LLM calls.
    #[serde(default)]
    pub signal_alias_map: BTreeMap<String, String>,
    #[serde(default)]
    pub validation_reports: Vec<ValidationReportRecord>,
    /// EXTRACTION-QUALITY-GAUGE.0: the persisted NLI-oracle extraction-quality gauge for the
    /// current `signal_constraints` surface — back-annotated by `nli-verify` and re-measured by
    /// `converge` after stabilization. `None` until measured; a rebuild drops it (a new surface
    /// requires a fresh measurement). Measurement metadata, never extraction truth.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub extraction_quality_gauge: Option<ExtractionQualityGaugeRecord>,
    /// R15c: report of the monotone anchored-rescan loop that built this
    /// EvidenceIR. Makes the convergent extraction first-class — how many passes
    /// ran, how many *genuinely new* (deduplicated) facts each pass recovered,
    /// and whether the loop stabilized (`converged`) or stopped at its pass cap.
    /// `None` only for artifacts built before this field existed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub convergence_report: Option<EvidenceConvergenceReport>,
    /// PER-EXTRACTOR-FACT-TAGGING: per-extractor fact observations (which tier
    /// found each fact, under a canonical key) — the capture–recapture recall
    /// gauge precondition. Pattern finds are tagged at `build`; Nlp finds at
    /// `nlp-enrich` (pre-dedup, so overlaps are recorded). Empty for artifacts
    /// built before this field existed.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub fact_provenance: Vec<FactProvenanceRecord>,
    /// Typed fields recovered from an explicitly described serial frame. Names, phases, participant
    /// directions, and values are carried from the current document rather than interpreted from a
    /// stored protocol or signal vocabulary.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub serial_frame_fields: Vec<SerialFrameField>,
    /// EXTRACTION-QUALITY-GAUGE.FIELD.2: typed MESSAGE FIELDS of packet/flit protocols (CHI-class),
    /// recovered from container-captioned field-titled tables ("Request channel fields" with a
    /// `Field` name column). A field is flit/message content, not a wire — keeping this inventory
    /// first-class is what lets signal surfaces reject field subjects instead of mis-typing them.
    /// Empty (serde-skipped) for documents that declare no message-field tables.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub message_field_records: Vec<MessageFieldRecord>,
    /// PDF-VARIANT-DIGESTION.12b: typed SIGNAL-PRESENCE rows from presence matrices — tables that
    /// state, per interface class / protocol version / agent side, whether each signal exists
    /// (`Y`/`N`/`O`/`C`/… codes), optionally conditioned on a configuration property
    /// (`SUBSYSID_WIDTH > 0`). Presence is CONFIGURATION intent, not a declaration: these records
    /// never mint signals, and every name/condition/code is document-literal, never interpreted.
    /// Empty (serde-skipped) for documents without presence matrices.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub signal_presence_records: Vec<SignalPresenceRecord>,
    /// EXTRACTION-QUALITY-GAUGE.FIELD.4: typed obligations on declared MESSAGE FIELDS ("the TagOp
    /// field is inapplicable and must be 0b00"). A field obligation is protocol intent on flit/
    /// message CONTENT, not on a wire — so it lives in its own surface instead of either polluting
    /// `signal_constraints` (the CHI mis-typing class) or being silently dropped by the
    /// signal-subject gate. Populated by `extract-constraints-llm` when a grounded subject types
    /// as `EntityType::Field` against the `message_field_records` catalog.
    /// Empty (serde-skipped) for documents without field-subject obligations.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub message_field_constraints: Vec<MessageFieldConstraintRecord>,
    /// Named protocol states recovered through document-structure grammars. The records preserve
    /// stated names/actions without inventing transitions, encodings, or a machine identity.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub protocol_states: Vec<ProtocolStateRecord>,
    /// PDF-VARIANT-DIGESTION.3b: protocol ACTORS/AGENTS a spec defines in prose (controller, target, …).
    /// Empty (serde-skipped) for documents that do not define agents in prose.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub protocol_actors: Vec<ProtocolActorRecord>,
    /// Document-stated operation/response branches and phase counts. Branch, operation, and phase
    /// names remain opaque input-derived strings.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub protocol_operations: Vec<ProtocolOperationRecord>,
    /// Protocol/interface clocking recovered from prose that explicitly binds an actor's sampling
    /// and/or drive-state changes on one declared signal to an edge of a declared clock signal. The
    /// grammar and names are document-derived and the surface remains empty without complete evidence.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub interface_edge_timings: Vec<InterfaceEdgeTimingRecord>,
    /// EXTRACTOR-ARCHITECTURE.8: the per-surface extraction run manifest — which extractors were eligible /
    /// fired / produced / kept, for each surface that runs through the unified `run_surface(_concat)` driver
    /// (FSM, semantic-hints, registers, actors). A per-document **behavioral fingerprint** (the substrate
    /// `CORPUS-PATTERN-REUSE` clusters on), and the inspectable "which extractors fired" view the `.1` audit
    /// found missing. Additive + serde-default for backward compatibility with older persisted artifacts.
    #[serde(default)]
    pub extraction_manifest: ExtractionManifest,
    /// Verifier-owned replay policy. It intentionally contains no extracted value: current
    /// EvidenceIR is reconstructed from verified SourceIR, the exact normalized source, and any
    /// independently validated prior/model mutation inputs before this artifact receives authority.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    proof_context: Option<EvidenceProofContext>,
    /// Cumulative SourceIR-prefix plus EvidenceIR proof ledger. Deserialization alone never grants
    /// authority; canonical load and write recover the local suffix and execute every rule again.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    proof_ledger: Option<ProofLedger>,
}

/// In-memory evidence derived from an explicitly synthetic SourceIR fixture.
///
/// The wrapper deliberately exposes no serializer or canonical writer. Keeping the authority
/// distinction in the type system prevents a conformance fixture from being mistaken for a
/// production EvidenceIR artifact merely because both exercise the same generic transformations.
#[cfg(any(test, feature = "test-support", feature = "conformance-support"))]
#[derive(Debug)]
pub struct NonCanonicalEvidenceOverlay {
    artifact: EvidenceIr,
}

#[cfg(any(test, feature = "test-support", feature = "conformance-support"))]
impl NonCanonicalEvidenceOverlay {
    pub fn artifact(&self) -> &EvidenceIr {
        &self.artifact
    }

    pub fn artifact_mut(&mut self) -> &mut EvidenceIr {
        &mut self.artifact
    }

    pub fn refresh_signal_semantic_hints(
        &mut self,
        source: &crate::ir::source::NonCanonicalSourceOverlay,
    ) -> Result<()> {
        self.artifact
            .refresh_signal_semantic_hints_from_source(source.source_ir())
    }
}

/// One document-stated operation or response branch with an explicit phase cardinality.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ProtocolOperationRecord {
    /// Stable schema-local identifier.
    pub operation_id: String,
    /// Qualifier or response value that selects this branch, exactly as stated.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub branch_label: Option<String>,
    /// Operation name or operation phrase, exactly as stated.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub operation_name: Option<String>,
    /// Explicit number of phases.
    pub phase_count: u32,
    /// Ordered phase names only when the same source statement states them explicitly.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub phase_names: Vec<String>,
    /// Statements that evidenced this operation.
    #[serde(default)]
    pub supporting_statement_ids: Vec<String>,
}

/// An explicitly stated clock-edge contract for an interface signal. One record joins the actor,
/// data signal, clock signal, edge, and operations that the source binds to that edge.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct InterfaceEdgeTimingRecord {
    /// Stable id, e.g. `interface_edge_timing_0001`.
    pub timing_id: String,
    /// Actor named by the source clause (`target`, `controller`, ...).
    pub actor_name: String,
    /// Interface data/signal whose sampling or drive state is clocked.
    pub signal_name: String,
    /// Clock signal whose edge defines the operation timing.
    pub clock_signal: String,
    /// Explicit edge stated by the source.
    pub edge: InterfaceClockEdge,
    /// The actor samples `signal_name` on this edge.
    pub samples_on_edge: bool,
    /// The actor changes whether it drives `signal_name` on this edge (start or stop driving).
    pub drive_changes_on_edge: bool,
    /// Statements that evidenced this timing contract.
    #[serde(default)]
    pub supporting_statement_ids: Vec<String>,
}

/// A document-stated interface clock edge. Unknown is deliberately absent: no record is emitted
/// unless the prose says rising/posedge or falling/negedge explicitly.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "snake_case")]
pub enum InterfaceClockEdge {
    Rising,
    Falling,
}

/// One source-declared field in a serial frame sequence.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct SerialFrameField {
    /// Stable id, e.g. `serial_field_0003`.
    pub field_id: String,
    /// The field name exactly as written.
    pub name: String,
    /// Bit-width in the frame (from `NAME[hi:lo]` ⇒ |hi-lo|+1, or a stated count). `None` if unstated.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bit_width: Option<u32>,
    /// The literal bit range `[high, low]` when the field was written as `NAME[hi:lo]`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bit_range: Option<(u32, u32)>,
    /// The frame phase name exactly as stated by the document.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub phase_name: Option<String>,
    /// Document-stated source and destination participants for this field.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub participant_drive: Option<ParticipantDriveRecord>,
    /// Order of this field within the frame sequence when source structure establishes one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub order: Option<u32>,
    /// Response values explicitly bound to this field by the source.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub response_values: Vec<String>,
    /// Statements that evidenced this field.
    #[serde(default)]
    pub supporting_statement_ids: Vec<String>,
}

/// EXTRACTION-QUALITY-GAUGE.FIELD.2 — one declared MESSAGE FIELD: a named portion of a protocol
/// message/packet/flit payload, declared by a container-captioned, field-titled structured table
/// ("Table B2.2: Request channel fields" with a `Field` name column). Fields are protocol intent,
/// but they are NOT signals — no wire, no direction — so they get their own typed home instead of
/// polluting the signal surfaces (the CHI `DBID`/`TxnID` mis-typing class).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct MessageFieldRecord {
    /// Stable id, e.g. `message_field_0003`.
    pub field_id: String,
    /// The field name exactly as declared (`TxnID`, `Opcode`, `Addr[51:6]`) — including the
    /// document's own MULTI-WORD phrase name when the declaring family states names that way
    /// (`Validation Bits`, `FRU ID` in byte-location placement tables;
    /// PDF-VARIANT-DIGESTION.10e).
    pub name: String,
    /// The message/packet container named by the declaring table's caption, with a trailing
    /// "fields" word stripped (`Request channel fields` → `Request channel`). The same field name
    /// legitimately recurs across containers (`QoS` in every channel), so identity is
    /// (container, name).
    pub container: String,
    /// Width in bits when the declaring table carries exactly one unqualified width column
    /// (`Width (bits)` / `Bits`) and the cell is a plain count or `[hi:lo]` range, or when a
    /// byte-quantified size column states a plain count (`Size (Bytes)` `4` → `32`;
    /// PDF-VARIANT-DIGESTION.10e — exact unit arithmetic on a document-stated value, the same
    /// class as `high - low + 1`). `None` when unstated, variant-dependent, or symbolic
    /// (`(indicated by VenLen)`) — honest absence, never guessed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bit_width: Option<u32>,
    /// PDF-VARIANT-DIGESTION.10b: the field's literal bit position `(high, low)` within its
    /// container, when declared by a bit-position layout table (`255:248` → `(255, 248)`, a
    /// single `247` → `(247, 247)`). `None` for fields declared by width-column tables — a
    /// position is never derived from a width (honest absence). When `byte_offset` is set the
    /// range is DWORD-RELATIVE, exactly as the document wrote it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bit_range: Option<(u32, u32)>,
    /// PDF-VARIANT-DIGESTION.10d: the literal byte-offset suffix of a dword-relative
    /// bit-position cell (`31:28 +04` → `bit_range` `(31, 28)`, `byte_offset` `4`): the bit
    /// range is relative to the dword at this byte offset within the containing structure —
    /// the document's own statement, verbatim (offsets are decimal in the measured family).
    /// `None` when the cell carried no offset. An ABSOLUTE position is never derived here:
    /// the description's `Name[hi:lo]` slices are field-VALUE slices, not positions
    /// (measured: 54 of 66 mismatch `offset*8 + bit`), so the IR stays evidence-literal and
    /// consumers may compute `byte_offset * 8 + bit` themselves where they need an absolute
    /// ordering. PDF-VARIANT-DIGESTION.10e: with `bit_range: None` the offset is instead the
    /// FIELD's own literal starting byte offset within its container, as stated by a
    /// byte-location placement table (`Byte Location` `4` → `4`) — the two readings are
    /// disjoint by construction (`bit_range` is always `Some` on the dword-relative family).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub byte_offset: Option<u32>,
    /// The declared description text, when the table carries a description column.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    /// The structured tables that declared this field (a caption-continuation table merges into
    /// the record its first declaration created).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub supporting_table_ids: Vec<String>,
}

/// EXTRACTION-QUALITY-GAUGE.FIELD.4 — one typed obligation on a declared MESSAGE FIELD
/// ("For all other REQ channel messages, the TagOp field is inapplicable and must be 0b00").
/// Structurally the field-scoped sibling of [`SignalConstraintRecord`]: the constraint-kind
/// vocabulary (`must_be_value`, `must_not_change`, …) is shared — what a requirement can SAY is
/// the same; what it is ABOUT differs — and the subject is a catalog-declared field, never a
/// wire. Grounded through the exact same gates as signal constraints (entity typing,
/// condition-only-subject, permissive-frame, source-grounded value/condition).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct MessageFieldConstraintRecord {
    /// Stable id, e.g. `llm_fieldcon_0003`.
    pub constraint_id: String,
    /// The declared message field being constrained (`TagOp`, `DBID`), as the source wrote it.
    pub subject_field: String,
    /// The containers the `message_field_records` catalog declares this field in (a field name
    /// legitimately recurs across containers — `QoS` in every channel). Catalog provenance, in
    /// catalog encounter order; empty only when the subject was field-typed without a catalog
    /// declaration.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub containers: Vec<String>,
    /// What the field must do or be (the shared constraint-kind vocabulary).
    pub constraint_kind: SignalConstraintKind,
    /// The specific target value/state, if applicable (e.g. `0b00`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target_value: Option<String>,
    /// The condition clause, if present (e.g. "For all other REQ channel messages").
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub condition_text: Option<String>,
    /// Whether the constraint was negated (`must not`, `shall not`).
    pub negated: bool,
    /// The original sentence this record was extracted from.
    pub source_text: String,
    pub supporting_statement_ids: Vec<String>,
    pub automation_confidence: AutomationConfidence,
}

/// PDF-VARIANT-DIGESTION.12b — one cell of a signal-presence matrix's variant axis: the literal
/// column label (an interface class, a protocol version, an agent side — whatever the document's
/// own matrix header says) and the literal presence code the document states for it (`Y`, `N`,
/// `O`, `C`, `OC`, …). Codes are kept as literal strings and NEVER interpreted: each document
/// defines its own code legend in nearby prose, so assigning meaning here would fabricate.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
pub struct VariantPresenceEntry {
    /// The variant column's label, exactly as the matrix header wrote it — including a literal
    /// fused sub-header (`A A.b`) and the split halves of a measured fused-pair header.
    pub variant_label: String,
    /// The literal 1–2-uppercase-letter presence code stated for this variant. A `-` cell states
    /// no code and yields no entry.
    pub code: String,
}

/// PDF-VARIANT-DIGESTION.12b — one row of a SIGNAL-PRESENCE MATRIX: a table whose first header
/// cell is signal-worded and whose variant columns carry only short uppercase presence codes
/// (`Y`/`N`/`O`/`C`/`OC`/…) per signal (for example, a summary by interface class or version).
/// The row states CONFIGURATION intent no other surface
/// types: per-variant signal presence plus an optional property-conditioned existence expression
/// (`SUBSYSID_WIDTH > 0`). Everything is captured document-LITERALLY — the signal name keeps its
/// case (a generic `Ax*` row stays generic, never expanded), the condition expression and the
/// codes are verbatim strings — because interpreting any of them would fabricate semantics the
/// document defines only in its own prose legend.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct SignalPresenceRecord {
    /// Stable id, e.g. `presence_0003`.
    pub presence_id: String,
    /// The signal name exactly as the row wrote it (literal case — `ARESETn`, generic `AxVALID`).
    pub signal_name: String,
    /// The literal presence-condition expression from the matrix's Presence/Property column
    /// (`SUBSYSID_WIDTH > 0`, `Check_Type`). `None` when the cell is `-`/empty or the matrix has
    /// no such column — honest absence, never inferred.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub presence_condition: Option<String>,
    /// One entry per variant column that states a code for this signal (a `-` cell is omitted).
    pub variant_presence: Vec<VariantPresenceEntry>,
    /// The structured table (page fragment) that carried this row.
    pub table_id: String,
}

/// EXTRACTION-QUALITY-GAUGE.0 — the persisted per-document extraction-quality gauge: the result of
/// one NLI-oracle pass over `signal_constraints` ("does the source sentence entail this constraint
/// as a claim?"). The not-entailed fraction is a cheap, automatic production-readiness signal that
/// discriminates sharply across documents (a simple peripheral bus vs. a dense conditional
/// interconnect spec). It is a **measurement record about** the extraction, not extraction truth:
/// the NLI oracle is noisy (some not-entailed verdicts are NLI false-negatives on complex claims),
/// so consumers treat it as an estimate and `validate` reports it as findings/metrics, never as a
/// reason to mutate the constraint surface. Re-building the EvidenceIR drops the gauge by
/// construction (a new surface honestly requires a fresh measurement); `converge` re-measures
/// after stabilization, which keeps the standing report fresh.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ExtractionQualityGaugeRecord {
    /// The text model that judged entailment (e.g. `qwen2.5:14b-instruct`).
    pub model: String,
    /// Size of the `signal_constraints` surface when the gauge was measured. A mismatch with the
    /// current surface marks the gauge stale (see `gauge_is_stale`).
    pub constraints_total: usize,
    /// Constraints whose claim the source sentence entails (NLI-verified).
    pub entailed: usize,
    /// Constraints whose claim the source sentence does NOT entail — likely extraction errors
    /// (spurious subject, dropped condition, permission read as obligation, …).
    pub not_entailed: usize,
    /// Constraints the oracle could not label (provider error / unclear answer). Honest
    /// no-label — never counted as entailed or not-entailed.
    pub abstained: usize,
    /// The `constraint_id`s judged not entailed, in constraint encounter order — the per-item
    /// review-routing list behind the aggregate.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub not_entailed_constraint_ids: Vec<String>,
}

/// A document-stated participant-to-participant drive direction.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ParticipantDriveRecord {
    pub source_actor: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_actor: Option<String>,
}

/// One source-declared protocol state. A record does not imply a transition or encoding.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ProtocolStateRecord {
    /// Stable id, e.g. `protocol_state_0003`.
    pub state_id: String,
    /// The state machine this state belongs to, when explicitly named.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub machine_name: Option<String>,
    /// The state name as written (e.g. `Shift-DR`, `Run-Test/Idle`, `Test-Logic-Reset`).
    pub state_name: String,
    /// What happens in this state ("data is transferred from DBGTDI to DBGTDO …"), when stated.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action: Option<String>,
    /// Statements that evidenced this state.
    #[serde(default)]
    pub supporting_statement_ids: Vec<String>,
}

/// PDF-VARIANT-DIGESTION.3b — a protocol ACTOR/AGENT a spec DEFINES in prose ("A controller is the device
/// which initiates a data transfer …", "any device addressed is considered a target"). Grounds the agent
/// model from prose, not only as the inferred subject of a relation. General agent-definition grammar; no
/// chip-spec names (ADR 0006).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ProtocolActorRecord {
    /// Stable id, e.g. `protocol_actor_0001`.
    pub actor_id: String,
    /// The agent / role name as written (e.g. `controller`, `target`, `host`).
    pub name: String,
    /// The defining clause, when captured ("the device which initiates a data transfer …").
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub definition: Option<String>,
    /// Statements that evidenced this actor.
    #[serde(default)]
    pub supporting_statement_ids: Vec<String>,
}

/// R15c: typed accounting for the EvidenceIR convergent anchored-rescan loop.
///
/// The loop seeds from one-shot extraction, then repeatedly uses known signals /
/// values as anchors to rescan tables (and prose-derived relations) for more
/// facts, stopping when a pass discovers no new *deduplicated* statement texts.
/// This record exposes that behavior instead of leaving it implicit, so users
/// can see genuine knowledge growth (not duplicate vector growth) and whether
/// convergence was actually reached.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct EvidenceConvergenceReport {
    /// Number of loop passes actually executed (includes the terminal pass that
    /// discovered nothing new, when the loop converged).
    pub passes_run: usize,
    /// The pass cap for this document (`structured_tables.len().max(1) + 4`).
    pub max_passes: usize,
    /// Genuinely-new (deduplicated) statements discovered per pass, in order.
    #[serde(default)]
    pub new_facts_per_pass: Vec<usize>,
    /// Sum of `new_facts_per_pass` — total anchored facts recovered beyond the seed.
    pub total_new_facts: usize,
    /// `true` if the loop stopped because a pass found nothing new (stabilized);
    /// `false` if it exhausted `max_passes` while still discovering facts
    /// (convergence not proven — the anchored rescan may be incomplete).
    pub converged: bool,
}

/// The independent extractor families a fact can come from. Recorded per fact so
/// the capture–recapture recall gauge (`INTENT-COMPLETENESS-RESEARCH.5`) can
/// estimate the unseen population from the overlap of what each found.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ExtractorTier {
    /// Tier-1/2 structural pattern extraction (prose patterns + table synthesis)
    /// run during `EvidenceIR` build.
    Pattern,
    /// Tier-3 NLP via a local LLM (`nlp-enrich`).
    Nlp,
    /// Tier-3 visual via a VLM (`enrich`).
    Vlm,
}

/// The kind of fact a [`FactProvenanceRecord`] refers to (extensible; the first
/// tagged type is `SignalConstraint`, which two independent tiers both produce).
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum FactKind {
    SignalConstraint,
    ActorSignalRelation,
}

/// One per-extractor fact observation: "extractor `producer` found a fact of
/// `fact_kind` whose canonical identity is `canonical_key`." Recorded *before*
/// merge/dedup so a fact found by two tiers appears once per tier (the overlap
/// capture–recapture needs). The canonical key is normalized so the SAME fact
/// found by different tiers yields the SAME key.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct FactProvenanceRecord {
    pub producer: ExtractorTier,
    pub fact_kind: FactKind,
    pub canonical_key: String,
}

/// Canonical identity of a signal constraint for cross-extractor overlap
/// detection: normalized subject signal + constraint kind + target value, so the
/// same constraint extracted by the pattern tier and the NLP tier produces the
/// same key regardless of id / source-text differences.
pub fn signal_constraint_fact_key(constraint: &SignalConstraintRecord) -> String {
    format!(
        "{}|{:?}|{}",
        constraint.subject_signal.trim(),
        constraint.constraint_kind,
        constraint.target_value.as_deref().unwrap_or("").trim(),
    )
}

/// Canonical identity of an actor-signal relation for cross-extractor overlap
/// detection: normalized actor + relation kind + signal, so the same edge
/// extracted by the pattern tier and the `signal-resolve` LLM produces the same
/// key regardless of id / source differences.
pub fn actor_signal_relation_fact_key(relation: &ActorSignalRelation) -> String {
    format!(
        "{}|{:?}|{}",
        relation.actor_name.trim(),
        relation.relation,
        relation.signal_name.trim(),
    )
}

/// Count the DISTINCT extractor tiers (`Pattern`/`Nlp`/`Vlm`) that recorded each fact, keyed by
/// its provenance `canonical_key` — the agreement-confidence signal (a fact two tiers independently
/// found is more trustworthy than one). A key absent from the map was seen by a single tier.
pub fn tier_count_by_fact_key(
    provenance: &[FactProvenanceRecord],
) -> std::collections::HashMap<String, usize> {
    let idx = |t: &ExtractorTier| match t {
        ExtractorTier::Pattern => 0,
        ExtractorTier::Nlp => 1,
        ExtractorTier::Vlm => 2,
    };
    let mut seen: std::collections::HashMap<String, [bool; 3]> = std::collections::HashMap::new();
    for p in provenance {
        seen.entry(p.canonical_key.clone()).or_default()[idx(&p.producer)] = true;
    }
    seen.into_iter()
        .map(|(k, flags)| (k, flags.iter().filter(|f| **f).count().max(1)))
        .collect()
}

#[derive(Debug, Clone)]
struct EvidencePriorGuidance {
    prior_memory_path: PathBuf,
    corpus_memory: CorpusMemory,
    prior_scope: PriorScope,
}

