fn evidence_derivation_error(error: impl std::fmt::Display) -> AppError {
    AppError::InvalidStageArtifact(format!("EvidenceIR proof verification failed: {error}"))
}

fn evidence_rule_registry() -> DerivationResult<RuleRegistry> {
    let implementation_sha256 = production_semantic_implementation_digest(IrStage::EvidenceIr)?;
    let registrations = EVIDENCE_RULE_FIELDS
        .iter()
        .map(|(field, family)| {
            let (capability, alpha) = match *family {
                "evidence.envelope" | "evidence.quality" => (
                    SymbolCapabilityClass::ExactIdentityOnly,
                    AlphaObligation::IdentityGraphInvariant,
                ),
                "evidence.signal_semantics" => (
                    SymbolCapabilityClass::MergeOrConflict,
                    AlphaObligation::MergeConflictTopologyInvariant,
                ),
                _ => (
                    SymbolCapabilityClass::GrammarIntroduces,
                    AlphaObligation::IntroducedSymbolsPreserveOrigins,
                ),
            };
            let rule_id =
                RuleId::try_from(format!("{family}.{field}.v1")).map_err(DerivationError::new)?;
            let descriptor = RuleDescriptor::new(
                rule_id,
                1,
                "crate::ir::evidence",
                implementation_sha256.clone(),
                [
                    PremiseKind::RegisteredDerivation,
                    PremiseKind::SourceSpan,
                    PremiseKind::GroundedModelProposal,
                    PremiseKind::ValidatedPrior,
                ],
                IrStage::EvidenceIr,
                *field,
                capability,
                alpha,
                RuleCompatibility::CurrentOnly,
            )?;
            Ok(RuleRegistration::new(
                descriptor,
                verify_evidence_rule_relation,
            ))
        })
        .collect::<DerivationResult<Vec<_>>>()?;
    RuleRegistry::new(registrations, [])
}

#[cfg(test)]
pub(super) fn rule_registry_for_qualification() -> DerivationResult<RuleRegistry> {
    evidence_rule_registry()
}

fn verify_evidence_rule_relation(context: RuleVerificationContext<'_>) -> DerivationResult<()> {
    let expected_bytes = context
        .premise_bytes(0)?
        .ok_or_else(|| DerivationError::new("EvidenceIR rule lacks claim replay bytes"))?;
    if expected_bytes == context.conclusion_json() {
        Ok(())
    } else {
        Err(DerivationError::new(format!(
            "EvidenceIR field '{}' is not the current registered replay",
            context.proof().address().surface()
        )))
    }
}

fn apply_evidence_mutations(
    artifact: &mut EvidenceIr,
    mutations: &[EvidenceMutationEvent],
) -> DerivationResult<()> {
    let mut seen = BTreeSet::new();
    for mutation in mutations {
        if !seen.insert(mutation.mutation_id.as_str()) {
            return Err(DerivationError::new(format!(
                "duplicate EvidenceIR mutation id '{}'",
                mutation.mutation_id
            )));
        }
        let allowed = mutation
            .kind
            .allowed_fields()
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        let present = mutation
            .fields
            .keys()
            .map(String::as_str)
            .collect::<BTreeSet<_>>();
        if present != allowed {
            return Err(DerivationError::new(format!(
                "EvidenceIR {:?} mutation field set is not exact",
                mutation.kind
            )));
        }
        let statement_ids = artifact
            .extracted_statements
            .iter()
            .map(|statement| statement.statement_id.as_str())
            .collect::<BTreeSet<_>>();
        #[cfg(any(test, feature = "test-support"))]
        let test_fixture = mutation.kind == EvidenceMutationKind::TestFixture;
        #[cfg(not(any(test, feature = "test-support")))]
        let test_fixture = false;
        if !test_fixture
            && mutation
                .supporting_statement_ids
                .iter()
                .any(|statement_id| !statement_ids.contains(statement_id.as_str()))
        {
            return Err(DerivationError::new(format!(
                "EvidenceIR mutation '{}' cites an absent statement",
                mutation.mutation_id
            )));
        }
        let mut value = serde_json::to_value(&*artifact).map_err(|error| {
            DerivationError::new(format!(
                "cannot serialize EvidenceIR mutation base: {error}"
            ))
        })?;
        let object = value.as_object_mut().ok_or_else(|| {
            DerivationError::new("serialized EvidenceIR mutation base is not an object")
        })?;
        for (field, replacement) in &mutation.fields {
            object.insert(field.clone(), replacement.clone());
        }
        object.remove("proof_context");
        object.remove("proof_ledger");
        *artifact = serde_json::from_value(value).map_err(|error| {
            DerivationError::new(format!(
                "invalid typed EvidenceIR mutation payload: {error}"
            ))
        })?;
    }
    Ok(())
}

fn collect_supporting_statement_ids(value: &serde_json::Value, output: &mut BTreeSet<String>) {
    match value {
        serde_json::Value::Array(values) => {
            for value in values {
                collect_supporting_statement_ids(value, output);
            }
        }
        serde_json::Value::Object(object) => {
            for (key, value) in object {
                if matches!(
                    key.as_str(),
                    "supporting_statement_ids" | "source_statement_ids"
                ) {
                    if let Some(ids) = value.as_array() {
                        output.extend(
                            ids.iter()
                                .filter_map(serde_json::Value::as_str)
                                .map(str::to_string),
                        );
                    }
                } else {
                    collect_supporting_statement_ids(value, output);
                }
            }
        }
        _ => {}
    }
}

/// Schema 1 carried protocol observations produced by vocabulary-bound extractors. Remove those
/// surfaces from the untyped JSON before deserialization so obsolete field encodings cannot regain
/// authority or prevent a safe load. All other evidence remains intact and can drive a neutral
/// downstream rebuild; re-extraction from SourceIR is required to repopulate these surfaces.
fn neutralize_legacy_protocol_json(artifact: &mut serde_json::Value) -> Result<()> {
    let object = artifact.as_object_mut().ok_or_else(|| {
        AppError::InvalidStageArtifact("EvidenceIR root must be a JSON object".to_string())
    })?;
    for surface in [
        "serial_frame_fields",
        "protocol_states",
        "protocol_operations",
    ] {
        object.insert(surface.to_string(), serde_json::Value::Array(Vec::new()));
    }
    object.insert(
        "extraction_manifest".to_string(),
        serde_json::to_value(ExtractionManifest::default())?,
    );
    Ok(())
}

impl EvidenceIr {
    pub fn load_from_path(path: &Path) -> Result<Self> {
        Self::load_with_verified_proof(path).map(|(evidence_ir, _)| evidence_ir)
    }

    pub(crate) fn load_with_verified_proof(path: &Path) -> Result<(Self, VerifiedProofLedger)> {
        let path = resolve_existing(path, PersistedPathOrigin::RepositoryOwned)?;
        let artifact = serde_json::from_str::<serde_json::Value>(&fs::read_to_string(path)?)?;
        let version = artifact
            .get("schema_version")
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| {
                AppError::InvalidStageArtifact(
                    "EvidenceIR is missing an integer schema_version".to_string(),
                )
            })?;
        if version != u64::from(EVIDENCE_IR_SCHEMA_VERSION) {
            let disposition = if version < u64::from(EVIDENCE_IR_SCHEMA_VERSION) {
                "is legacy/proofless and inspection-only; rebuild it from verified SourceIR"
            } else {
                "is newer than this binary"
            };
            return Err(AppError::InvalidStageArtifact(format!(
                "EvidenceIR schema version {version} {disposition}"
            )));
        }
        let evidence_ir = serde_json::from_value::<Self>(artifact)?;
        let verified = evidence_ir.verified_canonical_proof()?;
        Ok((evidence_ir.runtime_clone()?, verified))
    }

    /// Parse legacy evidence for diagnostics without granting it canonical or downstream
    /// authority. Schema 1's retired protocol-specific carriers are neutralized before exposure.
    pub fn load_for_inspection(path: &Path) -> Result<Self> {
        let path = resolve_existing(path, PersistedPathOrigin::RepositoryOwned)?;
        let mut artifact = serde_json::from_str::<serde_json::Value>(&fs::read_to_string(path)?)?;
        let version = artifact
            .get("schema_version")
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| {
                AppError::InvalidStageArtifact(
                    "EvidenceIR is missing an integer schema_version".to_string(),
                )
            })?;
        if version > u64::from(EVIDENCE_IR_SCHEMA_VERSION) {
            return Err(AppError::InvalidStageArtifact(format!(
                "EvidenceIR schema version {version} is newer than this binary"
            )));
        }
        if version == 1 {
            neutralize_legacy_protocol_json(&mut artifact)?;
        }
        let evidence_ir = serde_json::from_value::<Self>(artifact)?;
        if version == u64::from(EVIDENCE_IR_SCHEMA_VERSION) {
            evidence_ir.verify_canonical_proof()?;
        }
        evidence_ir.runtime_clone()
    }

    /// The current canonical EvidenceIR schema version. A persisted artifact below it is legacy:
    /// readable for inspection, never for canonical authority.
    pub const CURRENT_SCHEMA_VERSION: u32 = EVIDENCE_IR_SCHEMA_VERSION;

    /// `WIRE-BASED-100.8b` — the `schema_version` a persisted artifact records, read without
    /// granting it any authority.
    ///
    /// This exists so a caller can tell *why* a load was refused. A legacy artifact is a known,
    /// nameable disposition with a re-ingest route; any other refusal is a defect and must stay one.
    /// Reading the whole file is deliberate: the probe runs only on the failure path, and guessing
    /// the version from a prefix would be a second, weaker parser of the same bytes.
    pub fn persisted_schema_version(path: &Path) -> Result<u32> {
        let path = resolve_existing(path, PersistedPathOrigin::RepositoryOwned)?;
        let artifact = serde_json::from_str::<serde_json::Value>(&fs::read_to_string(path)?)?;
        artifact
            .get("schema_version")
            .and_then(serde_json::Value::as_u64)
            .and_then(|version| u32::try_from(version).ok())
            .ok_or_else(|| {
                AppError::InvalidStageArtifact(
                    "EvidenceIR is missing an integer schema_version".to_string(),
                )
            })
    }

    /// `WIRE-BASED-100.8a` — load a canonical EvidenceIR and re-prove it for a different
    /// repository-owned artifact base root.
    ///
    /// An EvidenceIR's proof is taken over its public field map, and that map includes the
    /// artifact's own `artifact_layout`, so every claim premise binds where the artifact is stored:
    /// a byte-identical copy at another path fails canonical verification with a stale registered
    /// replay topology. Read-only work — scoring the extraction commands without mutating the
    /// corpus, above all — has to relocate the artifact, so relocation needs a supported operation
    /// rather than an unsealed field rewrite that quietly voids the seal.
    ///
    /// The artifact is verified where it currently is, because a relocation must not launder
    /// authority onto something that never had it. It then moves to
    /// `<artifact_base_root>/<document_key>/evidence_ir.json` — the same layout convention the
    /// independent rebuild that verification performs replays, so the two still agree — and its
    /// proof is re-derived for that location from the same verified SourceIR prefix and the same
    /// sealed proof context, mutation chain included. Only the storage location changes;
    /// [`Self::write_to_disk`] re-verifies the result against a fresh rebuild, so this seam cannot
    /// persist content that no longer replays from its SourceIR.
    pub fn load_relocated_to_artifact_base_root(
        evidence_ir_path: &Path,
        artifact_base_root: &Path,
    ) -> Result<Self> {
        let (mut evidence_ir, _) = Self::load_with_verified_proof(evidence_ir_path)?;
        let context = evidence_ir
            .proof_context
            .clone()
            .ok_or_else(|| evidence_derivation_error("proofless EvidenceIR cannot be relocated"))?;
        let source_runtime_path = resolve_existing(
            &evidence_ir.source_ir_path,
            PersistedPathOrigin::RepositoryOwned,
        )?;
        let (_, source_proof) = SourceIr::load_with_verified_proof(&source_runtime_path)?;
        let prior_guidance = evidence_ir.prior_guidance_for_context(&context)?;
        let artifact_root = artifact_base_root.join(&evidence_ir.document_identity.document_key);
        let relocated_path = artifact_root.join("evidence_ir.json");
        evidence_ir.artifact_layout = EvidenceArtifactLayout {
            artifact_root,
            evidence_ir_path: relocated_path,
        }
        .runtime_layout()?;
        evidence_ir.refresh_proof_from_context(context, &source_proof, prior_guidance.as_ref())?;
        Ok(evidence_ir)
    }

    pub fn build(source_ir_path: &Path, artifact_base_root: &Path) -> Result<Self> {
        Self::build_with_prior_memory(source_ir_path, artifact_base_root, None)
    }

    pub fn build_with_prior_memory(
        source_ir_path: &Path,
        artifact_base_root: &Path,
        prior_memory_path: Option<&Path>,
    ) -> Result<Self> {
        let source_ir_runtime_path =
            resolve_existing(source_ir_path, PersistedPathOrigin::RepositoryOwned)?;
        let source_ir_path = source_ir_runtime_path.clone();
        let (source_ir, source_proof) =
            SourceIr::load_with_verified_proof(&source_ir_runtime_path)?;
        let prior_guidance = load_evidence_prior_guidance(prior_memory_path)?;
        let mut evidence_ir = Self::build_unproved_from_source_ir(
            &source_ir,
            source_ir_path,
            artifact_base_root,
            prior_guidance.clone(),
            None,
        )?;
        evidence_ir.refresh_canonical_proof(&source_ir, &source_proof, prior_guidance.as_ref())?;
        Ok(evidence_ir)
    }

    fn public_field_values(&self) -> DerivationResult<BTreeMap<String, serde_json::Value>> {
        let mut fields = BTreeMap::new();
        macro_rules! insert_field {
            ($field:ident) => {
                fields.insert(
                    stringify!($field).to_string(),
                    serde_json::to_value(&self.$field).map_err(|error| {
                        DerivationError::new(format!(
                            "cannot serialize EvidenceIR field '{}': {error}",
                            stringify!($field)
                        ))
                    })?,
                );
            };
        }
        insert_field!(schema_version);
        insert_field!(stage);
        insert_field!(source_ir_path);
        insert_field!(source_path_origin);
        insert_field!(prior_memory_path);
        insert_field!(artifact_layout);
        insert_field!(document_identity);
        insert_field!(section_anchors);
        insert_field!(evidence_spans);
        insert_field!(visual_evidence);
        insert_field!(evidence_links);
        insert_field!(extracted_statements);
        insert_field!(register_records);
        insert_field!(timing_constraints);
        insert_field!(signal_constraints);
        insert_field!(conditional_rules);
        insert_field!(extracted_contracts);
        insert_field!(constrained_extraction_stats);
        insert_field!(table_signal_declaration_provenance);
        insert_field!(signal_channel_memberships);
        insert_field!(signal_presence_records);
        insert_field!(signal_alias_map);
        insert_field!(signal_polarities);
        insert_field!(signal_polarity_conflicts);
        insert_field!(signal_semantic_hints);
        insert_field!(signal_semantic_conflicts);
        insert_field!(actor_signal_relations);
        insert_field!(serial_frame_fields);
        insert_field!(protocol_states);
        insert_field!(protocol_actors);
        insert_field!(protocol_operations);
        insert_field!(interface_edge_timings);
        insert_field!(message_field_records);
        insert_field!(message_field_constraints);
        insert_field!(validation_reports);
        insert_field!(extraction_quality_gauge);
        insert_field!(convergence_report);
        insert_field!(fact_provenance);
        insert_field!(extraction_manifest);
        if fields.len() != EVIDENCE_RULE_FIELDS.len() {
            return Err(DerivationError::new(
                "EvidenceIR proof field projection is incomplete",
            ));
        }
        Ok(fields)
    }

    fn claim_inputs(&self) -> DerivationResult<Vec<EvidenceClaimInput>> {
        let fields = self.public_field_values()?;
        let mut claims = Vec::new();
        for (field, family) in EVIDENCE_RULE_FIELDS {
            let value = fields.get(*field).cloned().ok_or_else(|| {
                DerivationError::new(format!("EvidenceIR claim field '{field}' is absent"))
            })?;
            let rule_id =
                RuleId::try_from(format!("{family}.{field}.v1")).map_err(DerivationError::new)?;
            claims.push(EvidenceClaimInput {
                address: ClaimAddress::new(IrStage::EvidenceIr, *field, "root", None)?,
                rule_id: rule_id.clone(),
                conclusion: value.clone(),
            });
            if let Some(records) = value.as_array() {
                for (index, record) in records.iter().enumerate() {
                    claims.push(EvidenceClaimInput {
                        address: ClaimAddress::new(
                            IrStage::EvidenceIr,
                            *field,
                            format!("record-{index:08}"),
                            Some(format!("[{index}]")),
                        )?,
                        rule_id: rule_id.clone(),
                        conclusion: record.clone(),
                    });
                }
            } else if *field == "signal_alias_map" {
                let aliases = value.as_object().ok_or_else(|| {
                    DerivationError::new("EvidenceIR signal_alias_map is not an object")
                })?;
                for (index, (key, alias)) in aliases.iter().enumerate() {
                    claims.push(EvidenceClaimInput {
                        address: ClaimAddress::new(
                            IrStage::EvidenceIr,
                            *field,
                            format!("entry-{index:08}"),
                            Some(format!("[{index}]")),
                        )?,
                        rule_id: rule_id.clone(),
                        conclusion: serde_json::json!({"key": key, "value": alias}),
                    });
                }
            }
        }
        Ok(claims)
    }

    fn proof_kernel(
        &self,
        context: &EvidenceProofContext,
        source_proof: &VerifiedProofLedger,
        prior_guidance: Option<&EvidencePriorGuidance>,
        replay_bytes: &[u8],
        claims: &[EvidenceClaimInput],
    ) -> DerivationResult<(
        crate::ir::derivation::PromotionKernel,
        EvidenceProofPremises,
    )> {
        if context.schema_version != EVIDENCE_PROOF_CONTEXT_SCHEMA_VERSION {
            return Err(DerivationError::new(format!(
                "unsupported EvidenceIR proof-context schema {}",
                context.schema_version
            )));
        }
        let markdown_bytes = context.normalized_markdown.as_bytes();
        let prior_bytes = prior_guidance
            .map(|guidance| Sha256Digest::of_serializable(&guidance.corpus_memory))
            .transpose()?;
        let capture_digest = Sha256Digest::of_serializable(&(
            context,
            source_proof.ruleset_sha256(),
            Sha256Digest::of_bytes(markdown_bytes),
            prior_bytes,
        ))?;
        let registry = evidence_rule_registry()?;
        let mut builder =
            PromotionKernelBuilder::with_verified_upstream(capture_digest, registry, source_proof)?;
        let proof_premises = {
            let mut capture = builder.capture();
            let normalized_source =
                capture.source_span("evidence-normalized-source", markdown_bytes)?;
            let mut inputs = source_proof
                .claims()
                .iter()
                .map(|proof| PremiseRef::UpstreamClaim {
                    address: proof.address().clone(),
                    conclusion_sha256: proof.conclusion_sha256().clone(),
                })
                .collect::<Vec<_>>();
            inputs.push(normalized_source.clone());
            let validated_prior = if let Some(guidance) = prior_guidance {
                let payload = serde_json::to_vec(&guidance.corpus_memory).map_err(|error| {
                    DerivationError::new(format!("cannot serialize EvidenceIR prior: {error}"))
                })?;
                let validation = serde_json::to_vec(&(
                    guidance.prior_scope,
                    guidance.corpus_memory.schema_version,
                ))
                .map_err(|error| {
                    DerivationError::new(format!("cannot serialize prior validation: {error}"))
                })?;
                let prior = capture.validated_prior(
                    "evidence-global-prior",
                    &payload,
                    &validation,
                    ValidatedPriorScope::GlobalIdentityIndependent,
                    vec![normalized_source.clone()],
                )?;
                inputs.push(prior.clone());
                Some(prior)
            } else {
                None
            };
            let mut mutation_premises = Vec::new();
            for mutation in &context.mutations {
                let payload = serde_json::to_vec(mutation).map_err(|error| {
                    DerivationError::new(format!(
                        "cannot serialize grounded EvidenceIR mutation: {error}"
                    ))
                })?;
                let proposal = capture.grounded_model_proposal(
                    mutation.mutation_id.clone(),
                    &payload,
                    vec![normalized_source.clone()],
                )?;
                inputs.push(proposal.clone());
                mutation_premises.push((mutation.kind, proposal));
            }
            let registered_replay =
                capture.registered_derivation("evidence.current-replay", replay_bytes, inputs)?;
            let mut claim_replays = BTreeMap::new();
            for claim in claims {
                let exact_conclusion = serde_json::to_vec(&claim.conclusion).map_err(|error| {
                    DerivationError::new(format!(
                        "cannot serialize EvidenceIR claim replay: {error}"
                    ))
                })?;
                let derivation_id = format!(
                    "evidence.claim.{}.{}",
                    claim.address.surface(),
                    claim.address.stable_record_key()
                );
                let premise = capture.registered_derivation(
                    derivation_id,
                    &exact_conclusion,
                    vec![registered_replay.clone()],
                )?;
                if claim_replays
                    .insert(claim.address.clone(), premise)
                    .is_some()
                {
                    return Err(DerivationError::new(
                        "duplicate EvidenceIR claim replay address",
                    ));
                }
            }
            EvidenceProofPremises {
                claim_replays,
                normalized_source,
                validated_prior,
                mutations: mutation_premises,
            }
        };
        Ok((builder.seal(), proof_premises))
    }

    /// The validated-prior guidance every proof operation over this artifact must reconstruct,
    /// from the artifact's own persisted prior path plus the prior payload captured in its sealed
    /// proof context. The two are one fact recorded twice, so a disagreement is a corrupt artifact
    /// rather than a defaultable state.
    fn prior_guidance_for_context(
        &self,
        context: &EvidenceProofContext,
    ) -> Result<Option<EvidencePriorGuidance>> {
        match (&self.prior_memory_path, &context.prior_memory) {
            (None, None) => Ok(None),
            (Some(path), Some(corpus_memory)) => Ok(Some(EvidencePriorGuidance {
                prior_memory_path: resolve_repository_output(path)?,
                corpus_memory: corpus_memory.clone(),
                prior_scope: PriorScope::Global,
            })),
            _ => Err(evidence_derivation_error(
                "EvidenceIR prior path and captured validated-prior payload disagree",
            )),
        }
    }

    fn refresh_canonical_proof(
        &mut self,
        source_ir: &SourceIr,
        source_proof: &VerifiedProofLedger,
        prior_guidance: Option<&EvidencePriorGuidance>,
    ) -> Result<()> {
        let context = EvidenceProofContext {
            schema_version: EVIDENCE_PROOF_CONTEXT_SCHEMA_VERSION,
            normalized_markdown: fs::read_to_string(
                source_ir
                    .normalization_plan
                    .promoted_markdown_path
                    .as_ref()
                    .ok_or_else(|| {
                        AppError::InvalidStageArtifact(
                            "SourceIR lacks promoted Markdown".to_string(),
                        )
                    })?,
            )?,
            prior_memory: prior_guidance.map(|guidance| guidance.corpus_memory.clone()),
            mutations: Vec::new(),
            #[cfg(any(test, feature = "test-support"))]
            test_fixture: source_ir.is_test_fixture(),
        };
        self.refresh_proof_from_context(context, source_proof, prior_guidance)
    }

    fn refresh_proof_from_context(
        &mut self,
        context: EvidenceProofContext,
        source_proof: &VerifiedProofLedger,
        prior_guidance: Option<&EvidencePriorGuidance>,
    ) -> Result<()> {
        let mut persisted = self.persisted_clone()?;
        persisted.proof_context = None;
        persisted.proof_ledger = None;
        let replay_bytes = serde_json::to_vec(
            &persisted
                .public_field_values()
                .map_err(evidence_derivation_error)?,
        )?;
        let claims = persisted
            .claim_inputs()
            .map_err(evidence_derivation_error)?;
        let (mut kernel, proof_premises) = persisted
            .proof_kernel(
                &context,
                source_proof,
                prior_guidance,
                &replay_bytes,
                &claims,
            )
            .map_err(evidence_derivation_error)?;
        for claim in claims {
            let (premises, confidence) = proof_premises
                .for_claim(&claim.address)
                .map_err(evidence_derivation_error)?;
            let proposal = kernel.grammar_capability().propose(
                claim.address,
                claim.rule_id,
                premises,
                Vec::new(),
                confidence,
                claim.conclusion,
            );
            kernel
                .promote(proposal)
                .map_err(evidence_derivation_error)?;
        }
        let local = kernel.finish().map_err(evidence_derivation_error)?;
        let cumulative =
            VerifiedProofLedger::compose(source_proof, local).map_err(evidence_derivation_error)?;
        self.proof_context = Some(context);
        self.proof_ledger = Some(cumulative.into_ledger());
        Ok(())
    }

    /// Authorize one closed-family post-build mutation and rebuild the cumulative proof. Fields
    /// outside the mutation kind's fixed set must remain byte-identical to the independently
    /// replayed predecessor; the exact typed patch becomes a current-source-grounded proposal.
    #[doc(hidden)]
    pub fn authorize_mutation(&mut self, kind: EvidenceMutationKind) -> Result<bool> {
        let mut context = self.proof_context.clone().ok_or_else(|| {
            evidence_derivation_error("proofless EvidenceIR cannot authorize a mutation")
        })?;
        #[cfg(any(test, feature = "test-support"))]
        if kind == EvidenceMutationKind::TestFixture {
            context.test_fixture = true;
        }
        let source_runtime_path =
            resolve_existing(&self.source_ir_path, PersistedPathOrigin::RepositoryOwned)?;
        let (source_ir, source_proof) = SourceIr::load_with_verified_proof(&source_runtime_path)?;
        let prior_guidance = self.prior_guidance_for_context(&context)?;
        let runtime_layout = self.artifact_layout.runtime_layout()?;
        let artifact_base_root = runtime_layout.artifact_root.parent().ok_or_else(|| {
            AppError::InvalidStageArtifact(
                "EvidenceIR artifact root has no repository-owned base".to_string(),
            )
        })?;
        let mut predecessor = Self::build_unproved_from_source_ir(
            &source_ir,
            source_runtime_path,
            artifact_base_root,
            prior_guidance.clone(),
            Some(&context.normalized_markdown),
        )?;
        apply_evidence_mutations(&mut predecessor, &context.mutations)
            .map_err(evidence_derivation_error)?;
        let predecessor_fields = predecessor
            .public_field_values()
            .map_err(evidence_derivation_error)?;
        let current_fields = self
            .public_field_values()
            .map_err(evidence_derivation_error)?;
        let allowed = kind
            .allowed_fields()
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        for (field, predecessor_value) in &predecessor_fields {
            if !allowed.contains(field.as_str())
                && current_fields.get(field) != Some(predecessor_value)
            {
                return Err(evidence_derivation_error(format!(
                    "{:?} mutation changed unauthorized EvidenceIR field '{field}'",
                    kind
                )));
            }
        }
        if kind
            .allowed_fields()
            .iter()
            .all(|field| current_fields.get(*field) == predecessor_fields.get(*field))
        {
            return Ok(false);
        }
        let fields = kind
            .allowed_fields()
            .iter()
            .map(|field| {
                current_fields
                    .get(*field)
                    .cloned()
                    .map(|value| ((*field).to_string(), value))
                    .ok_or_else(|| {
                        evidence_derivation_error(format!(
                            "EvidenceIR mutation field '{field}' is absent"
                        ))
                    })
            })
            .collect::<Result<BTreeMap<_, _>>>()?;
        let mut supporting_statement_ids = BTreeSet::new();
        for value in fields.values() {
            collect_supporting_statement_ids(value, &mut supporting_statement_ids);
        }
        let kind_name = serde_json::to_value(kind)?
            .as_str()
            .expect("EvidenceMutationKind serializes as a string")
            .to_string();
        let event = EvidenceMutationEvent {
            mutation_id: format!(
                "evidence-mutation-{index:08}-{kind_name}",
                index = context.mutations.len()
            ),
            kind,
            fields,
            supporting_statement_ids: supporting_statement_ids.into_iter().collect(),
        };
        apply_evidence_mutations(&mut predecessor, std::slice::from_ref(&event))
            .map_err(evidence_derivation_error)?;
        if predecessor
            .public_field_values()
            .map_err(evidence_derivation_error)?
            != current_fields
        {
            return Err(evidence_derivation_error(
                "typed EvidenceIR mutation replay does not reproduce the requested artifact",
            ));
        }
        context.mutations.push(event);
        self.refresh_proof_from_context(context, &source_proof, prior_guidance.as_ref())?;
        Ok(true)
    }

    fn verify_canonical_proof(&self) -> Result<()> {
        self.verified_canonical_proof().map(|_| ())
    }

    fn verified_canonical_proof(&self) -> Result<VerifiedProofLedger> {
        if self.schema_version != EVIDENCE_IR_SCHEMA_VERSION {
            return Err(AppError::InvalidStageArtifact(format!(
                "EvidenceIR schema {} cannot receive current canonical authority",
                self.schema_version
            )));
        }
        let context = self.proof_context.as_ref().ok_or_else(|| {
            AppError::InvalidStageArtifact(
                "current EvidenceIR is proofless; rebuild it from verified SourceIR".to_string(),
            )
        })?;
        let cumulative = self.proof_ledger.clone().ok_or_else(|| {
            AppError::InvalidStageArtifact(
                "current EvidenceIR is missing its cumulative proof ledger".to_string(),
            )
        })?;
        let source_runtime_path =
            resolve_existing(&self.source_ir_path, PersistedPathOrigin::RepositoryOwned)?;
        let (source_ir, source_proof) = SourceIr::load_with_verified_proof(&source_runtime_path)?;
        let prior_guidance = self.prior_guidance_for_context(context)?;
        let runtime_layout = self.artifact_layout.runtime_layout()?;
        let artifact_base_root = runtime_layout.artifact_root.parent().ok_or_else(|| {
            AppError::InvalidStageArtifact(
                "EvidenceIR artifact root has no repository-owned base".to_string(),
            )
        })?;
        let mut expected_runtime = Self::build_unproved_from_source_ir(
            &source_ir,
            source_runtime_path,
            artifact_base_root,
            prior_guidance.clone(),
            Some(&context.normalized_markdown),
        )?;
        apply_evidence_mutations(&mut expected_runtime, &context.mutations)
            .map_err(evidence_derivation_error)?;
        let expected = expected_runtime.persisted_clone()?;
        let replay_fields = expected
            .public_field_values()
            .map_err(evidence_derivation_error)?;
        let replay_bytes = serde_json::to_vec(&replay_fields)?;
        let actual_fields = self
            .public_field_values()
            .map_err(evidence_derivation_error)?;
        let claims = self.claim_inputs().map_err(evidence_derivation_error)?;
        let conclusions = claims
            .iter()
            .map(|claim| {
                serde_json::to_vec(&claim.conclusion)
                    .map(|bytes| (claim.address.clone(), bytes))
                    .map_err(AppError::from)
            })
            .collect::<Result<BTreeMap<_, _>>>()?;
        let (kernel, _) = self
            .proof_kernel(
                context,
                &source_proof,
                prior_guidance.as_ref(),
                &replay_bytes,
                &claims,
            )
            .map_err(evidence_derivation_error)?;
        let local_ruleset = evidence_rule_registry()
            .map_err(evidence_derivation_error)?
            .ruleset_sha256()
            .clone();
        let local_ledger = cumulative
            .local_suffix_after(&source_proof, &local_ruleset)
            .map_err(evidence_derivation_error)?;
        let verified_local = kernel
            .verify_persisted(local_ledger, &conclusions)
            .map_err(evidence_derivation_error)?;
        let verified = VerifiedProofLedger::compose(&source_proof, verified_local)
            .map_err(evidence_derivation_error)?;
        if verified.ledger() != &cumulative {
            return Err(evidence_derivation_error(
                "cumulative EvidenceIR proof differs from verified SourceIR prefix plus local replay",
            ));
        }
        if actual_fields != replay_fields {
            return Err(evidence_derivation_error(
                "EvidenceIR public fields differ from current registered replay",
            ));
        }
        Ok(verified)
    }

    fn build_unproved_from_source_ir(
        source_ir: &SourceIr,
        source_ir_path: PathBuf,
        artifact_base_root: &Path,
        prior_guidance: Option<EvidencePriorGuidance>,
        normalized_markdown: Option<&str>,
    ) -> Result<Self> {
        if !matches!(
            source_ir.normalization_plan.status,
            NormalizationStatus::Ready
        ) {
            return Err(AppError::InvalidStageArtifact(format!(
                "SourceIR at {} must have normalization status `ready` before building EvidenceIR",
                source_ir_path.display()
            )));
        }

        let promoted_markdown_path = source_ir
            .normalization_plan
            .promoted_markdown_path
            .as_ref()
            .ok_or_else(|| {
                AppError::InvalidStageArtifact(format!(
                    "SourceIR at {} is missing a promoted_markdown_path",
                    source_ir_path.display()
                ))
            })?;
        let source_path_origin = source_ir.promoted_markdown_origin()?;
        let promoted_markdown_runtime_path = if normalized_markdown.is_some() {
            resolve_reference(promoted_markdown_path, source_path_origin)?
        } else {
            resolve_existing(promoted_markdown_path, source_path_origin)?
        };
        let promoted_markdown_path = promoted_markdown_runtime_path.clone();
        let parsed_markdown = match normalized_markdown {
            Some(markdown) => parse_markdown_text(markdown),
            None => parse_markdown(&promoted_markdown_runtime_path)?,
        };

        let artifact_root = artifact_base_root.join(&source_ir.document_identity.document_key);
        let evidence_ir_path = artifact_root.join("evidence_ir.json");
        let artifact_layout = EvidenceArtifactLayout {
            artifact_root,
            evidence_ir_path,
        }
        .runtime_layout()?;
        let document_identity = EvidenceDocumentIdentity {
            document_key: source_ir.document_identity.document_key.clone(),
            display_name: source_ir.document_identity.display_name.clone(),
        };

        let mut section_anchors = build_section_anchors(
            &parsed_markdown.headings,
            parsed_markdown.total_lines,
            &document_identity.display_name,
        );
        for anchor in &mut section_anchors {
            anchor.source_path = promoted_markdown_path.clone();
        }
        // EXTRACTOR-ARCHITECTURE.10a — the statement/visual ASSEMBLY phase (visual-evidence items +
        // VLM-note injection, the markdown-block span/statement/link loop, caption/reference observation
        // back-annotation, section page ranges) is one cohesive named orchestrator instead of ~230 inline
        // lines. Pure code motion; `statement_counter` continues into the seed/contract synthesizers below.
        let mut statement_counter = 1usize;
        let AssembledEvidenceStatements {
            visual_evidence,
            evidence_spans,
            evidence_links,
            extracted_statements,
        } = assemble_evidence_statements(
            source_ir,
            &parsed_markdown,
            &promoted_markdown_path,
            &mut section_anchors,
            &mut statement_counter,
            prior_guidance.as_ref(),
        )
        .map_err(|error| {
            AppError::InvalidStageArtifact(format!(
                "EvidenceIR statement assembly failed for {}: {error}",
                source_ir.document_identity.document_key
            ))
        })?;

        // Synthesize typed declarations from structured table data in SourceIR.
        // This provides the first seed set for the convergent loop:
        //   1. direct signal declarations from signal-description tables
        //   2. direct enum facts from tables already classified as encodings
        // EXTRACTOR-ARCHITECTURE.5 — the signal-declaration SEED (table-declaration strategy + a
        // sparse-catalog prose fallback) is now one cohesive assembly-phase function instead of inline
        // orchestration in this ~500-line builder. It produces seed statements for the convergence loop plus
        // the table-declaration provenance side-output. This is the statement-ASSEMBLY phase, not the typed
        // surface-extraction phase, so it keeps its own orchestrator rather than the `run_surface` merge
        // driver (see the two-phase / two-category note in `ir/extractor.rs`).
        let (
            synthesized,
            table_signal_declaration_provenance,
            table_declaration_catalog,
            table_declaration_row_accounting,
        ) = synthesize_signal_declaration_seed(
            source_ir,
            &extracted_statements,
            &mut statement_counter,
            prior_guidance.as_ref(),
        );

        // KG-ISF-TRANSACTIONS.2m: recover each declared signal's document-grounded CHANNEL
        // from the `<role> channel signals` table captions (joined with the provenance just
        // built). Document-level fact; empty on docs without channel captions. This is the
        // only stage with both the provenance and the SourceIR table captions.
        let signal_channel_memberships = build_signal_channel_memberships(
            &source_ir.structured_tables,
            &table_signal_declaration_provenance,
        );

        // Extract system contract (clock + reset) from signal-description prose in tables.
        let mut declared_signal_names = collect_known_signal_names(&extracted_statements);
        declared_signal_names.extend(collect_known_signal_names(&synthesized));
        let contract_stmts = synthesize_system_contract_from_table_descriptions(
            source_ir,
            &declared_signal_names,
            &mut statement_counter,
            prior_guidance.as_ref(),
        );

        // EXTRACTOR-ARCHITECTURE.8 — collect each framework surface's run manifest into a per-document
        // extraction fingerprint (which extractors fired / produced / kept), surfaced on `EvidenceIr`.
        let mut extraction_manifest = ExtractionManifest {
            // SIGNAL-DECLARATION-ROW-DROP.1 — publish the reader's own denominator on the
            // extraction manifest, so the 18.3% row loss it used to discard silently becomes a
            // number a check can bound without replaying the build.
            declaration_row_accounting: table_declaration_row_accounting,
            ..ExtractionManifest::default()
        };

        // EXTRACTOR-ARCHITECTURE.6 — the register-record surface (register-map + `unknown` field-table
        // strategies, concatenated via `run_surface_concat`, then the width / bit-layout-grid / fragment
        // post-passes) is now one cohesive surface function instead of inline orchestration. Behavior-identical.
        let register_records =
            register_record_surface(source_ir, prior_guidance.as_ref(), &mut extraction_manifest);
        // EXTRACTION-QUALITY-GAUGE.FIELD.2 — the message-field surface: packet/flit protocols
        // declare flit/message FIELDS (CHI's `TxnID`/`DBID` class) in container-captioned
        // field-titled tables. Fields are typed intent but NOT signals; this inventory is their
        // first-class home, and the register surface keeps priority over shared `Field` columns.
        let message_field_records =
            message_field_surface(source_ir, prior_guidance.as_ref(), &mut extraction_manifest);
        // PDF-VARIANT-DIGESTION.12b — the signal-presence surface: presence matrices state which
        // signals exist per interface class / protocol version / agent side, with literal codes
        // and property-conditioned existence. Configuration intent, not declarations — these
        // records never mint signals (the `.12a` gap-fill owns declaration content).
        let signal_presence_records = signal_presence_surface(source_ir, &mut extraction_manifest);
        let timing_constraints = synthesize_timing_constraints(source_ir, prior_guidance.as_ref());

        // Replace the previous one-shot extraction with a monotone convergent loop:
        // discovered signals unlock anchored encoding tables, which unlock new value atoms,
        // which unlock additional prose-derived constraints.
        let (
            extracted_statements,
            signal_constraints,
            conditional_rules,
            signal_polarities,
            signal_polarity_conflicts,
            actor_signal_relations,
            convergence_report,
        ) = converge_evidence_extractions(
            source_ir,
            extracted_statements,
            synthesized,
            contract_stmts,
            &mut statement_counter,
            prior_guidance.as_ref(),
            &table_declaration_catalog,
            &mut extraction_manifest,
        );

        // Recover document-stated frame fields through two structural strategies: explicit phase-bound
        // bit ranges and explicit prose composition lists. Both read names and ordering from the current
        // document; neither strategy contains a protocol, vendor, signal, or response vocabulary.
        let serial_frame_fields =
            serial_frame_field_surface(&extracted_statements, &mut extraction_manifest);

        // Recover document-stated protocol/FSM states through complementary structural grammars. The
        // surface merges by source-derived state name and does not invent a machine identity.
        let protocol_states =
            protocol_state_surface(&extracted_statements, &mut extraction_manifest);
        // PDF-VARIANT-DIGESTION.3b — protocol actors/agents defined in prose.
        // EXTRACTOR-ARCHITECTURE.7 — protocol actors via the unified framework (single-strategy surface, run
        // through the concat driver for a uniform manifest entry; output byte-identical).
        let protocol_actors_run = run_surface_concat(
            "protocol_actors",
            &ExtractionContext {
                statements: &extracted_statements,
            },
            &[&ProtocolActorExtractor],
        );
        extraction_manifest.record(&protocol_actors_run);
        let protocol_actors = protocol_actors_run.records;

        // Recover operations and response branches only when the current document explicitly supplies a
        // phase cardinality. Labels remain opaque source vocabulary.
        let protocol_operations =
            protocol_operation_surface(&extracted_statements, &mut extraction_manifest);

        // Recover explicit interface edge timing from timing-class prose.
        // Names come from the document's declared-signal inventory and actor clause; no protocol or
        // signal vocabulary is embedded. The registered surface is empty when the complete grammar
        // (operation + declared data signal + explicit edge + declared clock) is not present.
        let interface_edge_timings =
            interface_edge_timing_surface(&extracted_statements, &mut extraction_manifest);

        // PER-EXTRACTOR-FACT-TAGGING: tag every fact produced by the structural
        // pattern tier (the convergent build loop above) as `Pattern`, computed
        // before the move into the struct literal. The LLM tiers tag their finds
        // later (`nlp-enrich` for constraints, `signal-resolve` for relations).
        let fact_provenance: Vec<FactProvenanceRecord> = signal_constraints
            .iter()
            .map(|c| FactProvenanceRecord {
                producer: ExtractorTier::Pattern,
                fact_kind: FactKind::SignalConstraint,
                canonical_key: signal_constraint_fact_key(c),
            })
            .chain(actor_signal_relations.iter().map(|r| FactProvenanceRecord {
                producer: ExtractorTier::Pattern,
                fact_kind: FactKind::ActorSignalRelation,
                canonical_key: actor_signal_relation_fact_key(r),
            }))
            .collect();

        let mut evidence_ir = Self {
            schema_version: EVIDENCE_IR_SCHEMA_VERSION,
            stage: IrStage::EvidenceIr,
            source_ir_path,
            source_path_origin: Some(source_path_origin),
            prior_memory_path: prior_guidance
                .as_ref()
                .map(|guidance| guidance.prior_memory_path.clone()),
            artifact_layout,
            document_identity,
            section_anchors,
            evidence_spans,
            visual_evidence,
            evidence_links,
            extracted_statements,
            register_records,
            timing_constraints,
            signal_constraints,
            conditional_rules,
            extracted_contracts: Vec::new(),
            constrained_extraction_stats: None,
            table_signal_declaration_provenance,
            signal_channel_memberships,
            signal_polarities,
            signal_polarity_conflicts,
            signal_semantic_hints: Vec::new(),
            signal_semantic_conflicts: Vec::new(),
            actor_signal_relations,
            signal_alias_map: BTreeMap::new(),
            validation_reports: Vec::new(),
            // A fresh build is a fresh constraint surface — any prior gauge no longer
            // describes it, so the measurement honestly starts absent.
            extraction_quality_gauge: None,
            convergence_report: Some(convergence_report),
            fact_provenance,
            serial_frame_fields,
            message_field_records,
            signal_presence_records,
            message_field_constraints: Vec::new(),
            protocol_states,
            protocol_actors,
            protocol_operations,
            interface_edge_timings,
            extraction_manifest,
            proof_context: None,
            proof_ledger: None,
        };
        // refresh_signal_semantic_hints records the `signal_semantic_hints` surface into the manifest too.
        evidence_ir
            .refresh_signal_semantic_hints_from_source(source_ir)
            .map_err(|error| {
                AppError::InvalidStageArtifact(format!(
                    "EvidenceIR semantic-hint refresh failed for {}: {error}",
                    source_ir.document_identity.document_key
                ))
            })?;

        Ok(evidence_ir)
    }

    /// Conformance-only build over an explicitly noncanonical SourceIR overlay. This path never
    /// writes or reloads a canonical SourceIR and its output must remain inside the harness.
    #[cfg(any(test, feature = "test-support", feature = "conformance-support"))]
    #[doc(hidden)]
    pub fn build_from_noncanonical_overlay(
        overlay: &crate::ir::source::NonCanonicalSourceOverlay,
        artifact_base_root: &Path,
        prior_memory_path: Option<&Path>,
    ) -> Result<NonCanonicalEvidenceOverlay> {
        let source_ir = overlay.source_ir();
        // A noncanonical overlay has no SourceIR artifact by design. Retain the existing source
        // file only as an inspectable conformance-lineage anchor; no production loader consumes
        // this branch as a canonical SourceIR chain.
        let source_ir_path = source_ir.source.canonical_path.clone();
        let prior_guidance = load_evidence_prior_guidance(prior_memory_path)?;
        let artifact = Self::build_unproved_from_source_ir(
            source_ir,
            source_ir_path,
            artifact_base_root,
            prior_guidance,
            None,
        )?;
        Ok(NonCanonicalEvidenceOverlay { artifact })
    }

    /// Form 2: Signal alias learning feedback loop.
    ///
    /// Applies the accumulated `signal_alias_map` to re-classify remaining
    /// `NormativeStatement` sentences WITHOUT an LLM call.  For each sentence
    /// containing a known prose alias (e.g. "address bus"), the alias is substituted
    /// by the canonical signal name (e.g. "HADDR") and `is_signal_value_constraint()`
    /// is re-run on the substituted text.  If it now qualifies, the statement is
    /// reclassified to `SignalValueConstraint` and a `SignalConstraintRecord` is
    /// synthesised at `AutomationConfidence::Low` (alias-derived).
    ///
    /// Returns `(reclassified_count, new_records)`.  The caller is responsible for
    /// extending `self.signal_constraints` with `new_records` and writing to disk.
    pub fn apply_alias_reclassification(
        &mut self,
        constraint_counter: &mut usize,
    ) -> (usize, Vec<SignalConstraintRecord>) {
        if self.signal_alias_map.is_empty() {
            return (0, Vec::new());
        }

        // Build a quick-lookup set of texts already covered by existing records.
        let existing_texts: HashSet<&str> = self
            .signal_constraints
            .iter()
            .map(|r| r.source_text.as_str())
            .collect();

        let alias_map = self.signal_alias_map.clone();
        let mut reclassified = 0usize;
        let mut new_records = Vec::new();

        for stmt in &mut self.extracted_statements {
            if !matches!(stmt.class, StatementClass::NormativeStatement) {
                continue;
            }
            if existing_texts.contains(stmt.text.as_str()) {
                continue;
            }

            let lowered = stmt.text.to_ascii_lowercase();

            for (alias_phrase, signal_name) in &alias_map {
                if !lowered.contains(alias_phrase.as_str()) {
                    continue;
                }

                // Substitute the alias phrase with the uppercase signal name.
                // Result is mixed-case, e.g. "the HADDR shall remain stable when hready is low".
                // `is_signal_value_constraint()` handles this correctly:
                //   • lowercases for phrase-binding check  ("shall remain stable" found)
                //   • scans original-case for uppercase tokens  ("HADDR" found)
                let substituted = lowered.replace(alias_phrase.as_str(), signal_name.as_str());

                if !is_signal_value_constraint(&substituted) {
                    continue;
                }

                // Reclassify the statement (Form 2 backannotation).
                stmt.class = StatementClass::SignalValueConstraint;
                reclassified += 1;

                // Synthesise a constraint record for the reclassified statement.
                let constraint_kind = detect_constraint_kind_from_substituted(&substituted);
                let condition_text = extract_condition_clause(&stmt.text);
                let negated = lowered.contains(" not ") || lowered.contains("cannot");

                *constraint_counter += 1;
                new_records.push(SignalConstraintRecord {
                    constraint_id: format!("alias2_sigcon_{constraint_counter:04}"),
                    subject_signal: signal_name.clone(),
                    constraint_kind,
                    target_value: None,
                    condition_text,
                    negated,
                    source_text: stmt.text.clone(),
                    supporting_statement_ids: vec![stmt.statement_id.clone()],
                    automation_confidence: AutomationConfidence::Low,
                });

                break; // Apply at most one alias per statement.
            }
        }

        (reclassified, new_records)
    }

    pub fn to_pretty_json(&self) -> Result<String> {
        let persisted = self.persisted_clone()?;
        persisted.verify_canonical_proof()?;
        Ok(serde_json::to_string_pretty(&persisted)?)
    }

    pub fn refresh_signal_semantic_hints(&mut self) -> Result<()> {
        let source_ir = SourceIr::load_from_path(&self.source_ir_path)?;
        self.refresh_signal_semantic_hints_from_source(&source_ir)
    }

    fn refresh_signal_semantic_hints_from_source(&mut self, source_ir: &SourceIr) -> Result<()> {
        let prior_guidance = load_evidence_prior_guidance(self.prior_memory_path.as_deref())?;
        // EXTRACTOR-ARCHITECTURE.8 — record the semantic-hints surface manifest into the per-document
        // fingerprint. Disjoint self-field borrows: the inputs are `&self.<field>` (shared) and the manifest
        // is `&mut self.extraction_manifest` (a distinct field) — allowed. `record` is idempotent per surface
        // name, so re-running a refresh replaces (not duplicates) the `signal_semantic_hints` entry.
        let (signal_semantic_hints, signal_semantic_conflicts) = synthesize_signal_semantic_hints(
            source_ir,
            &self.extracted_statements,
            &self.actor_signal_relations,
            &self.signal_alias_map,
            &self.visual_evidence,
            prior_guidance.as_ref(),
            &mut self.extraction_manifest,
        );
        self.signal_semantic_hints = signal_semantic_hints;
        self.signal_semantic_conflicts = signal_semantic_conflicts;
        Ok(())
    }

    #[allow(
        clippy::question_mark,
        reason = "the explicit error branch preserves the test-fixture mutation fallback"
    )]
    pub fn write_to_disk(&self) -> Result<()> {
        // Canonical persistence is a seam, not a generic serializer. Requiring a currently
        // verified SourceIR makes the noncanonical overlay non-persistable even if a conformance
        // caller obtains a read reference to its inner diagnostic value.
        SourceIr::load_from_path(&self.source_ir_path).map_err(|error| {
            AppError::InvalidStageArtifact(format!(
                "EvidenceIR cannot be persisted without a verified canonical SourceIR: {error}"
            ))
        })?;
        let persisted = self.persisted_clone()?;
        if let Err(error) = persisted.verify_canonical_proof() {
            #[cfg(any(test, feature = "test-support"))]
            if persisted
                .proof_context
                .as_ref()
                .is_some_and(|context| context.test_fixture)
            {
                let mut fixture = self.clone();
                fixture.authorize_mutation(EvidenceMutationKind::TestFixture)?;
                return fixture.write_to_disk();
            }
            return Err(error);
        }
        let runtime_layout = persisted.artifact_layout.runtime_layout()?;
        fs::create_dir_all(&runtime_layout.artifact_root)?;
        fs::write(
            &runtime_layout.evidence_ir_path,
            serde_json::to_string_pretty(&persisted)?,
        )?;
        Ok(())
    }

    /// Persist an explicitly synthetic EvidenceIR fixture under a test-only proof-context variant
    /// that production decoders reject. This cannot grant production authority or cross the
    /// noncanonical overlay seam.
    #[cfg(any(test, feature = "test-support"))]
    #[doc(hidden)]
    pub fn write_test_fixture_to_disk(&self) -> Result<()> {
        if self.persisted_clone()?.verify_canonical_proof().is_ok() {
            return self.write_to_disk();
        }
        let mut fixture = self.clone();
        fixture.authorize_mutation(EvidenceMutationKind::TestFixture)?;
        fixture.write_to_disk()
    }

    pub fn dedup_loopback_records(&mut self) -> bool {
        let mut changed = false;
        changed |= dedup_signal_constraints_in_place(&mut self.signal_constraints);
        changed |= dedup_conditional_rules_in_place(&mut self.conditional_rules);
        changed
    }

    fn persisted_clone(&self) -> Result<Self> {
        let mut persisted = self.clone();
        persisted.source_ir_path = normalize_for_storage(
            &persisted.source_ir_path,
            PersistedPathOrigin::RepositoryOwned,
        )?;
        normalize_optional_repository_path(&mut persisted.prior_memory_path)?;
        persisted.artifact_layout.normalize_for_storage()?;

        let source_path_origin = match persisted.source_path_origin {
            Some(origin) => origin,
            None => {
                SourceIr::load_from_path(&persisted.source_ir_path)?.promoted_markdown_origin()?
            }
        };
        persisted.source_path_origin = Some(source_path_origin);
        for anchor in &mut persisted.section_anchors {
            anchor.source_path = normalize_for_storage(&anchor.source_path, source_path_origin)?;
        }
        for span in &mut persisted.evidence_spans {
            span.source_path = normalize_for_storage(&span.source_path, source_path_origin)?;
        }
        for visual in &mut persisted.visual_evidence {
            if let Some(path) = &mut visual.source_path {
                *path = normalize_for_storage(path, PersistedPathOrigin::RepositoryOwned)?;
            }
        }
        Ok(persisted)
    }

    fn runtime_clone(&self) -> Result<Self> {
        let mut runtime = self.clone();
        runtime.source_ir_path = resolve_existing(
            &runtime.source_ir_path,
            PersistedPathOrigin::RepositoryOwned,
        )?;
        if let Some(path) = &mut runtime.prior_memory_path {
            *path = resolve_repository_output(path)?;
        }
        runtime.artifact_layout = runtime.artifact_layout.runtime_layout()?;

        let source_path_origin = match runtime.source_path_origin {
            Some(origin) => origin,
            None => {
                SourceIr::load_from_path(&runtime.source_ir_path)?.promoted_markdown_origin()?
            }
        };
        runtime.source_path_origin = Some(source_path_origin);
        for anchor in &mut runtime.section_anchors {
            anchor.source_path = resolve_reference(&anchor.source_path, source_path_origin)?;
        }
        for span in &mut runtime.evidence_spans {
            span.source_path = resolve_reference(&span.source_path, source_path_origin)?;
        }
        for visual in &mut runtime.visual_evidence {
            if let Some(path) = &mut visual.source_path {
                *path = resolve_reference(path, PersistedPathOrigin::RepositoryOwned)?;
            }
        }
        Ok(runtime)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct EvidenceArtifactLayout {
    pub artifact_root: PathBuf,
    pub evidence_ir_path: PathBuf,
}

impl EvidenceArtifactLayout {
    fn normalize_for_storage(&mut self) -> Result<()> {
        self.artifact_root =
            normalize_for_storage(&self.artifact_root, PersistedPathOrigin::RepositoryOwned)?;
        self.evidence_ir_path =
            normalize_for_storage(&self.evidence_ir_path, PersistedPathOrigin::RepositoryOwned)?;
        Ok(())
    }

    fn runtime_layout(&self) -> Result<Self> {
        Ok(Self {
            artifact_root: resolve_repository_output(&self.artifact_root)?,
            evidence_ir_path: resolve_repository_output(&self.evidence_ir_path)?,
        })
    }
}

fn normalize_optional_repository_path(path: &mut Option<PathBuf>) -> Result<()> {
    if let Some(value) = path {
        *value = normalize_for_storage(value, PersistedPathOrigin::RepositoryOwned)?;
    }
    Ok(())
}

