    fn make_table_cell(text: &str, is_header: bool) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header,
        }
    }

    fn signal_authority_table(
        table_id: &str,
        caption: Option<&str>,
        headers: &[&str],
    ) -> StructuredTableRecord {
        StructuredTableRecord {
            table_id: table_id.to_string(),
            asset_id: format!("asset_{table_id}"),
            page_id: None,
            caption_text: caption.map(str::to_string),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: if headers.is_empty() {
                vec![]
            } else {
                vec![
                    headers
                        .iter()
                        .map(|header| make_table_cell(header, true))
                        .collect(),
                ]
            },
            body_rows: vec![vec![
                make_table_cell("PREADY", false),
                make_table_cell("1", false),
                make_table_cell("Requester", false),
                make_table_cell("Transfer completion", false),
            ]],
            row_count: if headers.is_empty() { 1 } else { 2 },
            col_count: headers.len().max(4) as u32,
        }
    }

    #[test]
    fn signal_table_authority_requires_inventory_structure() -> Result<()> {
        let tempdir = tempdir()?;
        let source = tempdir.path().join("spec.md");
        let source_artifact_base = tempdir.path().join("generated").join("source_ir");
        fs::write(&source, "# Interface\n")?;
        let source_ir = SourceIr::build(&source, &source_artifact_base)?;

        let explicit_signal_caption = signal_authority_table(
            "signal_caption",
            Some("Table 1 Signal descriptions"),
            &["Description", "Width", "Source"],
        );
        let rotated_name_inventory = signal_authority_table(
            "rotated",
            None,
            &["Name", "Destination", "Width", "Description"],
        );
        let swj_pin_routing = signal_authority_table(
            "swj",
            Some("Table B5-1 Routing of SWJ-DP pins"),
            &["SWJ-DP pin", "SW-DP pin", "JTAG-DP pin"],
        );
        let headerless_connector = signal_authority_table(
            "mipi",
            Some("Table 17. MIPI 10-pin JTAG + nRESET Connector Diagram"),
            &[],
        );
        for table in [
            &explicit_signal_caption,
            &rotated_name_inventory,
            &swj_pin_routing,
            &headerless_connector,
        ] {
            assert!(
                super::should_treat_table_as_top_level_signal_description(&source_ir, table, None),
                "genuine inventory structure was rejected: {}",
                table.table_id
            );
        }

        let state_legend = signal_authority_table(
            "usb_state_legend",
            Some("Table 10-1. Downstream Facing Hub Port State Machine Diagram Legend"),
            &["Key", "Description"],
        );
        let vbus_requirements = signal_authority_table(
            "usb_vbus",
            Some("Table 10-2. Downstream USB Standard-A Port VBUS Requirements"),
            &[
                "Hub Upstream Port Connection Status",
                "Downstream Port Enhanced SuperSpeed Port Power Off",
                "Downstream Port Enhanced SuperSpeed Port Power On",
            ],
        );
        let port_status_codes = signal_authority_table(
            "usb_port_status",
            Some("Table 10-12. Port Status Type Codes"),
            &[
                "Port Status Type",
                "Value",
                "Port Status Length",
                "Description",
            ],
        );
        for table in [&state_legend, &vbus_requirements, &port_status_codes] {
            assert!(
                !super::should_treat_table_as_top_level_signal_description(&source_ir, table, None),
                "ordinary port vocabulary received inventory authority: {}",
                table.table_id
            );
        }

        Ok(())
    }

    #[test]
    fn weak_dense_prose_names_cannot_reenter_through_relations() -> Result<()> {
        let tempdir = tempdir()?;
        let source = tempdir.path().join("usb_dense_prose.md");
        let source_artifact_base = tempdir.path().join("generated").join("source_ir");
        let evidence_artifact_base = tempdir.path().join("generated").join("evidence_ir");
        fs::write(
            &source,
            concat!(
                "# Hub behavior\n",
                "Signal at its upstream port is repeated by the hub.\n",
                "The Universal Serial Bus (USB) connects the host and downstream devices.\n",
                "The hub drives AT, USB, ENHANCED, and NO toward the downstream port.\n",
            ),
        )?;

        let mut source_ir = SourceIr::build(&source, &source_artifact_base)?;
        source_ir.structured_tables.push(StructuredTableRecord {
            table_id: "table_0210".to_string(),
            asset_id: "asset_0210".to_string(),
            page_id: None,
            caption_text: Some(
                "Table 10-2. Downstream USB Standard-A Port VBUS Requirements".to_string(),
            ),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![vec![
                make_table_cell("Hub Upstream Port Connection Status", true),
                make_table_cell(
                    "Downstream Port Enhanced SuperSpeed Port Power Off (PORT_POWER = 0)",
                    true,
                ),
                make_table_cell(
                    "Downstream Port Enhanced SuperSpeed Port Power On (PORT_POWER = 1)",
                    true,
                ),
            ]],
            body_rows: vec![
                vec![
                    make_table_cell("Enhanced SuperSpeed", false),
                    make_table_cell("On", false),
                    make_table_cell("May be off", false),
                ],
                vec![
                    make_table_cell("USB 2.0", false),
                    make_table_cell("On", false),
                    make_table_cell("May be off", false),
                ],
                vec![
                    make_table_cell("No VBUS", false),
                    make_table_cell("May be off", false),
                    make_table_cell("May be off", false),
                ],
            ],
            row_count: 4,
            col_count: 3,
        });
        source_ir.write_test_fixture_to_disk()?;

        let evidence_ir = EvidenceIr::build(
            &source_ir.artifact_layout.source_ir_path,
            &evidence_artifact_base,
        )?;
        let known_signals = super::collect_known_signal_names(&evidence_ir.extracted_statements);
        for rejected in ["AT", "USB", "ENHANCED", "NO"] {
            assert!(
                !known_signals.contains(rejected),
                "weak name re-entered the declaration catalog: {rejected} in {known_signals:?}"
            );
            assert!(
                evidence_ir
                    .actor_signal_relations
                    .iter()
                    .all(|relation| relation.signal_name != rejected),
                "weak name re-entered through a relation: {rejected}"
            );
            assert!(
                evidence_ir
                    .extracted_statements
                    .iter()
                    .all(|statement| statement.text != format!("Signal {rejected} is output.")),
                "weak name re-entered through direction synthesis: {rejected}"
            );
        }
        assert!(
            evidence_ir.table_signal_declaration_provenance.is_empty(),
            "the requirements matrix must not receive signal-inventory provenance: {:?}",
            evidence_ir.table_signal_declaration_provenance
        );

        Ok(())
    }

    // --- derive_encoding_enum_name fallback gate (KG-ISF-COMPLETENESS.5.i) ---

    fn encoding_table(caption: &str, headers: &[&str]) -> StructuredTableRecord {
        StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: Some(caption.to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::Encoding,
            header_rows: vec![headers.iter().map(|h| make_table_cell(h, true)).collect()],
            body_rows: vec![vec![
                make_table_cell("IDLE", false),
                make_table_cell("0", false),
            ]],
            row_count: 2,
            col_count: headers.len() as u32,
        }
    }

    #[test]
    fn encoding_enum_name_fallback_drops_document_structure_keyword() {
        // The defect: a caption leading with a structure keyword (`Table N - …`) makes the fallback
        // pick `TABLE` (it passes is_hardware_signal_token), which — merged by name across tables —
        // produced the generic-`TABLE` mega-enum conflation. With no declared signal and no matching
        // column header, the gate returns None (no enum minted → honest residual).
        let table = encoding_table("Table 12 - Mode Definition", &["Function", "Notes"]);
        assert_eq!(
            super::derive_encoding_enum_name(&table, "Chapter 3 Behavior", None),
            None
        );
        // The structure-word also-class stray caption words (`AMBA`/`Byte`/`Read`) are dropped too.
        let table2 = encoding_table("AMBA cache attribute summary", &["Attribute", "Meaning"]);
        assert_eq!(super::derive_encoding_enum_name(&table2, "", None), None);
    }

    #[test]
    fn encoding_enum_name_fallback_keeps_column_header_candidate() {
        // A genuinely-named encoding table whose FIRST caption token is a column header of the table
        // (the enum's subject) is independently evidenced → kept. `TKEEP encoding` with a `TKEEP`
        // column header survives even without a declared-signal set (the `None` call site).
        let table = encoding_table("TKEEP encoding", &["TKEEP", "Description"]);
        assert_eq!(
            super::derive_encoding_enum_name(&table, "", None),
            Some("TKEEP".to_string())
        );
        // Bracketed header form (`HTRANS[1:0]`) is matched too.
        let table2 = encoding_table("HTRANS transfer type encoding", &["HTRANS[1:0]", "Type"]);
        assert_eq!(
            super::derive_encoding_enum_name(&table2, "", None),
            Some("HTRANS".to_string())
        );
    }

    #[test]
    fn encoding_enum_name_keeps_declared_signal_but_drops_unevidenced_caption_word() {
        // Contract over the whole function: a declared signal named in the caption is kept (here via
        // the signal-match loop, which pre-empts the fallback); the SAME caption with no declared-signal
        // set and no matching column header is a bare caption word → the gated fallback returns None.
        let table = encoding_table("PPROT protection encoding", &["Value", "Meaning"]);
        let mut declared = std::collections::HashSet::new();
        declared.insert("PPROT".to_string());
        assert_eq!(
            super::derive_encoding_enum_name(&table, "", Some(&declared)),
            Some("PPROT".to_string())
        );
        assert_eq!(super::derive_encoding_enum_name(&table, "", None), None);
    }

    #[test]
    fn encoding_enum_name_uses_exact_first_unique_only_signal_identity() {
        let exact_table = encoding_table("sig encoding", &["Meaning", "Value"]);
        let ambiguous_table = encoding_table("Sig encoding", &["Meaning", "Value"]);
        let declared = ["sig".to_string(), "SIG".to_string()]
            .into_iter()
            .collect::<std::collections::HashSet<_>>();

        assert_eq!(
            super::derive_encoding_enum_name(&exact_table, "", Some(&declared)),
            Some("sig".to_string())
        );
        assert_eq!(
            super::derive_encoding_enum_name(&ambiguous_table, "", Some(&declared)),
            None
        );
    }

    // --- header-SOURCED enum naming (KG-ISF-COMPLETENESS.5.iv.a) ---

    /// A two-column encoding table with an explicit header and body. Rows are `(value, meaning)`,
    /// matching the `<FIELD> value | Description` shape the `.5.iv` census measured. Every fixture
    /// below is copied from a real persisted table so the tests exercise document shapes rather than
    /// invented ones (ADR 0006 permits real names in fixtures; they are data, not logic).
    fn header_encoding_table(
        headers: [&str; 2],
        rows: &[(&str, &str)],
        caption: Option<&str>,
    ) -> StructuredTableRecord {
        StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: caption.map(str::to_string),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::Encoding,
            header_rows: vec![headers.iter().map(|h| make_table_cell(h, true)).collect()],
            body_rows: rows
                .iter()
                .map(|(value, meaning)| {
                    vec![
                        make_table_cell(value, false),
                        make_table_cell(meaning, false),
                    ]
                })
                .collect(),
            row_count: rows.len() as u32 + 1,
            col_count: 2,
        }
    }

    #[test]
    fn header_sourced_enum_name_recovers_the_field_the_caption_never_names() {
        // The asymmetry `.5.iv` measured: the header names the field outright, but it was read only as
        // a veto, so a caption without a field token minted nothing. The header now sources the name.
        let table = header_encoding_table(
            ["SEC_SID value", "Description"],
            &[("0b0", "Non-secure Stream"), ("0b1", "Secure Stream")],
            None,
        );
        assert_eq!(
            super::derive_encoding_enum_name(&table, "Stream Security determination", None),
            Some("SEC_SID".to_string())
        );

        // A bare field header (no `value` qualifier) is the same shape.
        let bare = header_encoding_table(
            ["ContFormat", "Description"],
            &[("0b1011", "Format 11"), ("Others", "Reserved")],
            None,
        );
        assert_eq!(
            super::derive_encoding_enum_name(&bare, "", None),
            Some("ContFormat".to_string())
        );
    }

    #[test]
    fn header_sourced_enum_name_declines_positional_layout_tables() {
        // A POSITIONAL header declares the left column to hold a position or an address, so the table
        // says WHERE a field sits and not what its values mean. NVMe `Bytes | Description` structure
        // tables (85 corpus candidates) and the AXI `AxADDR bits` table `.5.iv` recorded as garbled.
        let bytes = header_encoding_table(
            ["Bytes", "Description"],
            &[("01", "Opcode"), ("15", "Reserved")],
            None,
        );
        assert_eq!(super::derive_encoding_enum_name(&bytes, "", None), None);

        let bit_layout = header_encoding_table(
            ["AxADDR bits", "Description"],
            &[("[3]", "VA[40]"), ("[2:0]", "num[2:0] = A")],
            None,
        );
        assert_eq!(
            super::derive_encoding_enum_name(&bit_layout, "", None),
            None
        );

        // A register-offset table: `Offset` names a column concept, never a field.
        let offsets = header_encoding_table(
            ["Offset", "Description"],
            &[("0x000", "ROMENTRY0"), ("0xFFC - 0xFB8", "Reserved")],
            None,
        );
        assert_eq!(super::derive_encoding_enum_name(&offsets, "", None), None);
    }

    #[test]
    fn header_sourced_enum_name_declines_a_positional_range_value_column() {
        // Even without a positional header word, a value cell spanning `high:low` is the extent of a
        // field, not one encoded value — the table is a layout table.
        let table = header_encoding_table(
            ["Descriptor", "Description"],
            &[("03:02", "Namespace Identifier"), ("00", "Opcode")],
            None,
        );
        assert_eq!(super::derive_encoding_enum_name(&table, "", None), None);
    }

    #[test]
    fn header_sourced_enum_name_declines_tables_that_encode_nothing() {
        // Clause 5 — no value cell parses as an encoding literal, so the table presents no encoded
        // value. This is the class a name-shape rule cannot see, and it is the majority of the junk:
        // glossaries, notation legends, and width-PARAMETER tables whose sole member is a range.
        let glossary = header_encoding_table(
            ["Acronym", "Description"],
            &[("LSB", "Least significant bit"), ("MCU", "Microcontroller")],
            Some("Table 16. Abbreviations"),
        );
        assert_eq!(super::derive_encoding_enum_name(&glossary, "", None), None);

        let legend = header_encoding_table(
            ["Notation", "Meaning"],
            &[("+", "Two's complement addition")],
            None,
        );
        assert_eq!(super::derive_encoding_enum_name(&legend, "", None), None);

        // The `.5.iii` width-parameter residual, re-entering from the header side.
        let parameter = header_encoding_table(
            ["NodeID_Width value", "Description"],
            &[("7 to 11", "Legal values")],
            None,
        );
        assert_eq!(super::derive_encoding_enum_name(&parameter, "", None), None);
    }

    #[test]
    fn header_sourced_enum_name_declines_an_ambiguous_field_header() {
        // Two field-like tokens leave no single field to name; the shape is not the measured one.
        let table = header_encoding_table(
            ["Stream security state", "Description"],
            &[("0b0", "Non-secure")],
            None,
        );
        assert_eq!(super::derive_encoding_enum_name(&table, "", None), None);
    }

    #[test]
    fn header_sourced_enum_name_is_strictly_additive() {
        // The header path runs only after both earlier paths decline, so a name that is minted today
        // is unchanged: the caption's column-header candidate still wins over the header token, and a
        // declared signal still wins over both.
        let table = header_encoding_table(
            ["HTRANS[1:0]", "Description"],
            &[("0b00", "IDLE"), ("0b10", "NONSEQ")],
            Some("HTRANS transfer type encoding"),
        );
        assert_eq!(
            super::derive_encoding_enum_name(&table, "", None),
            Some("HTRANS".to_string())
        );

        let declared = ["HBURST".to_string()]
            .into_iter()
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(
            super::derive_encoding_enum_name(&table, "HBURST encodings", Some(&declared)),
            Some("HBURST".to_string())
        );
    }

    #[test]
    fn header_sourced_enum_name_mints_the_document_grounded_members() {
        // End to end through the member seam: the recovered name reaches
        // `synthesize_encoding_declarations_for_enum`, whose `.5.ii`/`.5.iii` gates still apply, and the
        // values are the document's own literals rather than row indices.
        let table = header_encoding_table(
            ["AWATOP value", "Description"],
            &[
                ("0b000000", "NonAtomic"),
                ("0b010000", "AtomicStore"),
                ("0b100000", "AtomicLoad"),
            ],
            None,
        );
        let name =
            super::derive_encoding_enum_name(&table, "", None).expect("header sources a name");
        let mut counter = 0usize;
        let statements =
            super::synthesize_encoding_declarations_for_enum(&table, &name, None, &mut counter);
        let texts: Vec<&str> = statements.iter().map(|s| s.text.as_str()).collect();
        assert_eq!(
            texts,
            vec![
                "Enum AWATOP NONATOMIC = 0.",
                "Enum AWATOP ATOMICSTORE = 16.",
                "Enum AWATOP ATOMICLOAD = 32.",
            ]
        );
    }

    #[test]
    fn header_column_word_classes_stay_disjoint_and_positional() {
        // Drift guard. The POSITIONAL class is load-bearing (it removes 99 of 134 junk candidates), so
        // a word may not drift into the merely-stripped role class, where it would stop vetoing.
        for positional in super::HEADER_POSITIONAL_COLUMN_WORDS {
            assert!(
                !super::HEADER_COLUMN_ROLE_WORDS.contains(positional),
                "`{positional}` must veto the header path, not be stripped from it"
            );
            assert!(
                !super::HEADER_DOCUMENT_STRUCTURE_WORDS.contains(positional),
                "`{positional}` must veto the header path, not be stripped from it"
            );
        }
        // A description role must also be a strippable column role, so `<FIELD> description` cannot be
        // read as a two-token header.
        for description in super::HEADER_DESCRIPTION_COLUMN_WORDS {
            assert!(
                super::HEADER_COLUMN_ROLE_WORDS.contains(description),
                "`{description}` names a column role and must be strippable"
            );
        }
    }

    // --- per-member sentence-spine fragment gate (KG-ISF-COMPLETENESS.5.ii) ---

    #[test]
    fn prose_sentence_spine_words_excludes_identifier_collisions() {
        // Drift guard for the `.1a`-style collision exclusions: the six spine-shaped tokens that double
        // as real hardware identifiers must NOT be in the lexicon, or the gate would drop real members
        // (`MASKLANE_A`, the GIC `ITS_*`, a CAN-bus value, the month `May`).
        for collision in ["a", "i", "its", "can", "may", "am"] {
            assert!(
                !super::PROSE_SENTENCE_SPINE_WORDS.contains(&collision),
                "spine lexicon must exclude the identifier-collision token `{collision}`"
            );
        }
        // The lexicon is lowercase (the predicate lowercases each token before comparing).
        assert!(
            super::PROSE_SENTENCE_SPINE_WORDS
                .iter()
                .all(|w| w.chars().all(|c| c.is_ascii_lowercase()))
        );
    }

    #[test]
    fn prose_fragment_member_predicate() {
        // Captured sentences (any spine token) are fragments …
        for frag in [
            "THE_TRANSACTION_WAS_SUCCESSFUL",
            "ATS_IS_SUPPORTED",
            "ESM16GTSUPPORT__MUST_BE_SET",
            "IGNORED_WHEN_PR_0",
            "WRITE_WAS_UNSUCCESSFUL_BECAUSE_IT_CANNOT_BE_SERVICED",
        ] {
            assert!(
                super::is_prose_fragment_member_name(frag),
                "`{frag}` should be a prose fragment"
            );
        }
        // … while real identifiers — including legitimate multi-word names and the collision-excluded
        // forms (`_A` suffix, GIC `ITS`, a `_WIDTH` leak) — are kept.
        for keep in [
            "OKAY",
            "EXOKAY",
            "REPAIR_LANE_0",
            "WRITE_BACK__SHAREABLE",
            "NORMAL_NON_CACHEABLE__NON_SHAREABLE",
            "MASKLANE_A",
            "ITS_COMMAND_QUEUE",
            "BRESP_WIDTH",
        ] {
            assert!(
                !super::is_prose_fragment_member_name(keep),
                "`{keep}` should be kept (not a prose fragment)"
            );
        }
    }

    fn encoding_table_with_rows(
        caption: &str,
        headers: &[&str],
        rows: &[(&str, &str)],
    ) -> StructuredTableRecord {
        StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: Some(caption.to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::Encoding,
            header_rows: vec![headers.iter().map(|h| make_table_cell(h, true)).collect()],
            body_rows: rows
                .iter()
                .map(|(name, value)| {
                    vec![make_table_cell(name, false), make_table_cell(value, false)]
                })
                .collect(),
            row_count: rows.len() as u32 + 1,
            col_count: headers.len() as u32,
        }
    }

    #[test]
    fn encoding_member_synthesis_drops_prose_fragments_keeps_codes() {
        // A conflated `BRESP` table fuses the genuine codes with prose-description rows. The per-member
        // gate keeps the codes and drops the captured sentences (the `.5.ii` BRESP 16→codes recovery).
        let table = encoding_table_with_rows(
            "BRESP encoding",
            &["Response", "Value"],
            &[
                ("OKAY", "0"),
                (
                    "THE REQUEST HAS REACHED AN END POINT BUT HAS NOT COMPLETED",
                    "1",
                ),
                ("EXOKAY", "1"),
                ("SLVERR", "2"),
                (
                    "EXCLUSIVE WRITE SUCCEEDED THIS RESPONSE IS ONLY PERMITTED",
                    "3",
                ),
            ],
        );
        let mut counter = 0usize;
        let statements =
            super::synthesize_encoding_declarations_for_enum(&table, "BRESP", None, &mut counter);
        assert_eq!(statements.len(), 3, "only the three real codes survive");
        let joined = statements
            .iter()
            .map(|s| s.text.as_str())
            .collect::<Vec<_>>()
            .join(" | ");
        assert!(joined.contains("OKAY") && joined.contains("EXOKAY") && joined.contains("SLVERR"));
        assert!(
            !joined.contains("REQUEST") && !joined.contains("PERMITTED"),
            "no prose-fragment member survives: {joined}"
        );
    }

    #[test]
    fn encoding_member_synthesis_all_prose_yields_no_statements() {
        // A pure prose-description table (every name-cell a sentence) emits no member statements, so
        // `build_symbol_definitions` mints no enum — an honest residual, not a junk enum.
        let table = encoding_table_with_rows(
            "PPROT protection encoding",
            &["Meaning", "Value"],
            &[
                (
                    "PPROT[0] is used by requesters to indicate processing mode",
                    "0",
                ),
                (
                    "PPROT[1] is used in systems where greater differentiation is required",
                    "1",
                ),
            ],
        );
        let mut counter = 0usize;
        let statements =
            super::synthesize_encoding_declarations_for_enum(&table, "PPROT", None, &mut counter);
        assert!(statements.is_empty(), "all-prose table yields no members");
        assert_eq!(
            counter, 0,
            "no statement counter advance for dropped members"
        );
    }

    #[test]
    fn width_parameter_leak_member_predicate() {
        use std::collections::HashSet;
        let signals: HashSet<String> = ["AWSNOOP", "ARSNOOP", "BRESP"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        // enum-self-name leak (needs no signal set)
        assert!(super::is_width_parameter_leak_member(
            "BRESP_WIDTH",
            "BRESP",
            None
        ));
        // declared-signal leak in a differently-named enum (AXSNOOP fuses AWSNOOP/ARSNOOP widths)
        assert!(super::is_width_parameter_leak_member(
            "AWSNOOP_WIDTH",
            "AXSNOOP",
            Some(&signals)
        ));
        // FALSE-POSITIVE guard: a genuine width-VALUE is kept (FULL is neither enum nor signal)
        assert!(!super::is_width_parameter_leak_member(
            "FULL_WIDTH",
            "LINKWIDTH",
            Some(&signals)
        ));
        // a bare `WIDTH` member (no `<prefix>_WIDTH` shape) is not a leak
        assert!(!super::is_width_parameter_leak_member(
            "WIDTH",
            "BIT",
            Some(&signals)
        ));
        // a real code is never caught
        assert!(!super::is_width_parameter_leak_member(
            "OKAY",
            "BRESP",
            Some(&signals)
        ));
        // declared-signal arm is case-insensitive against the document's casing
        assert!(super::is_width_parameter_leak_member(
            "ARSNOOP_WIDTH",
            "AXSNOOP",
            Some(&signals)
        ));
    }

    #[test]
    fn encoding_member_synthesis_drops_width_parameter_leak_keeps_codes() {
        use std::collections::HashSet;
        // A conflated `BRESP` table where a width-parameter row (`BRESP_WIDTH = 0`) leaked into the
        // value enum (the `.5.iii` AXI-gold defect). The enum-self leak drops; the real codes survive.
        let table = encoding_table_with_rows(
            "BRESP encoding",
            &["Response", "Value"],
            &[
                ("BRESP_WIDTH", "0"),
                ("OKAY", "0"),
                ("EXOKAY", "1"),
                ("SLVERR", "2"),
            ],
        );
        let mut counter = 0usize;
        let statements =
            super::synthesize_encoding_declarations_for_enum(&table, "BRESP", None, &mut counter);
        let joined = statements
            .iter()
            .map(|s| s.text.as_str())
            .collect::<Vec<_>>()
            .join(" | ");
        assert_eq!(
            statements.len(),
            3,
            "the BRESP_WIDTH parameter row is dropped: {joined}"
        );
        assert!(
            !joined.contains("BRESP_WIDTH"),
            "no width-parameter leak survives: {joined}"
        );
        assert!(joined.contains("OKAY") && joined.contains("EXOKAY") && joined.contains("SLVERR"));

        // A declared-signal leak in a differently-named enum (`AXSNOOP` fusing `AWSNOOP_WIDTH`/
        // `ARSNOOP_WIDTH`) empties to no statements when `known_signals` grounds the prefixes.
        let signals: HashSet<String> = ["AWSNOOP", "ARSNOOP"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let axsnoop = encoding_table_with_rows(
            "AXSNOOP encoding",
            &["Name", "Value"],
            &[("AWSNOOP_WIDTH", "0"), ("ARSNOOP_WIDTH", "1")],
        );
        let mut counter2 = 0usize;
        let statements2 = super::synthesize_encoding_declarations_for_enum(
            &axsnoop,
            "AXSNOOP",
            Some(&signals),
            &mut counter2,
        );
        assert!(
            statements2.is_empty(),
            "a pure declared-signal width-parameter enum empties to an honest residual"
        );
    }

