    /// The same rule against the rows that produced it, carried verbatim from the persisted
    /// corpus (`683091…avalon…/source_ir.json`, `table_0031`) — a conformance fixture, which is
    /// where document-specific text is allowed to live (ADR 0006).
    ///
    /// The document states the template in its own description column: *"The input signal of a
    /// logical tristate signal"*. Two of these three rows are dropped today for an unrelated
    /// reason — the width `1 - 1024` parses as neither a number nor an expression — so the
    /// phantom only became visible once the width was readable. The third already declares it.
    #[test]
    fn the_corpus_template_rows_declare_no_signal() {
        // Before this leaf, the row reached the declaration path with an ordinary-looking name:
        // the leading token is trimmed of its non-identifier characters before being judged, and
        // that trim is what turns the metavariable into an identifier. Both halves still hold —
        // the defect was never in the trim, it was in judging the trimmed token.
        let trimmed = signal_names_in_name_cell("<name> _outen")
            .first()
            .cloned()
            .unwrap_or_default();
        assert_eq!(
            trimmed, "name",
            "the wrapper is trimmed away before judgement"
        );
        assert!(
            is_hardware_signal_token(&trimmed),
            "which is why the identifier test used to admit it"
        );

        let table = StructuredTableRecord {
            table_id: "table_0031".to_string(),
            asset_id: "asset_0031".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&[
                "Signal Role",
                "Width",
                "Direction",
                "Required",
                "Description",
            ])],
            body_rows: vec![
                row(&[
                    "<name> _in",
                    "1 - 1024",
                    "Slave → Master",
                    "No",
                    "The input signal of a logical tristate signal.",
                ]),
                row(&[
                    "<name> _out",
                    "1 - 1024",
                    "Master → Slave",
                    "No",
                    "The output signal of a logical tristate signal.",
                ]),
                row(&[
                    "<name> _outen",
                    "1",
                    "Master → Slave",
                    "No",
                    "The output enable for a logical tristate signal.",
                ]),
            ],
            row_count: 3,
            col_count: 5,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let mut accounting = Vec::new();
        let stmts = synthesize_signal_declarations(
            &table,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut accounting,
        );

        assert!(
            stmts.is_empty() && prov.is_empty(),
            "a template table declares nothing: {prov:?}"
        );
        let reasons: Vec<DeclarationRowDropReason> = accounting[0]
            .dropped_rows
            .iter()
            .map(|r| r.reason)
            .collect();
        assert_eq!(
            reasons,
            vec![DeclarationRowDropReason::NameIsPlaceholder; 3],
            "all three template rows are recorded as metavariables: {reasons:?}"
        );

        // The same document's conduit table (`table_0030`) writes the whole row as a template:
        // the name is a metavariable and so is the width. The width being parametric is what
        // used to carry it past the `(direction, width)` match.
        let conduit = StructuredTableRecord {
            table_id: "table_0030".to_string(),
            asset_id: "asset_0030".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&["Signal Role", "Width", "Direction", "Description"])],
            body_rows: vec![row(&[
                "<any>",
                "<n>",
                "In, out, or bidirectional",
                "A conduit interface consists of one or more input, output, or bidirectional signals.",
            ])],
            row_count: 1,
            col_count: 4,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let mut accounting = Vec::new();
        let stmts = synthesize_signal_declarations(
            &conduit,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut accounting,
        );
        assert!(
            stmts.is_empty() && prov.is_empty(),
            "a conduit template declares nothing: {prov:?}"
        );
        assert_eq!(
            accounting[0]
                .dropped_rows
                .iter()
                .map(|r| r.reason)
                .collect::<Vec<_>>(),
            vec![DeclarationRowDropReason::NameIsPlaceholder],
        );
    }

    /// SIGNAL-DECLARATION-ROW-DROP.2b — the flow-arrow grammar against **every distinct cell form
    /// the corpus contains**. `python3 scripts/measure_declaration_row_notations.py` finds 83 arrow
    /// cells in direction-bearing columns of signal-description tables across all 78 persisted
    /// SourceIR artifacts, in 13 distinct forms — so this table is the population, not a sample.
    #[test]
    fn the_corpus_flow_arrow_forms_admit_only_the_mirrored_ones() {
        // The 18 admitted cells, both forms, from one interface specification's Direction column.
        for (cell, expected) in [("Master → Slave", "output"), ("Slave → Master", "input")] {
            assert_eq!(
                infer_signal_direction_from_flow_arrow(cell, None),
                Some(expected),
                "{cell} states a flow between two roles the taxonomy knows"
            );
        }
        // The 65 that fail closed, every distinct form. Two flows in one cell (16 rows) describe a
        // bidirectional group; the rest name an actor the builtin taxonomy does not know, which is
        // a taxonomy question (`.2d`), not an arrow question.
        for cell in [
            "Redistributor→ Distributor Distributor→ Redistributor",
            "ITS →Distributor Distributor →ITS",
            "Distributor→ Remote chip",
            "Source → Sink",
            "Distributor →SPI Collator",
            "ITS →Distributor",
            "Redistributor→ Distributor",
            "SPI Collator→ Distributor",
            "Remote chip→ Distributor",
            "Distributor →Wake Request",
            "Wake Request→ Distributor",
            "Interconnect → Slave",
            "Sink → Source",
        ] {
            assert_eq!(
                infer_signal_direction_from_flow_arrow(cell, None),
                None,
                "{cell} must fail closed"
            );
        }
    }

    /// The mirror is the rule's second condition, so it gets its own controls: one side alone is
    /// never enough, and two sides that disagree contradict each other.
    #[test]
    fn a_flow_arrow_needs_both_sides_to_resolve_and_agree() {
        // Both sides resolve and agree — the only shape that admits.
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Manager -> Subordinate", None),
            Some("output")
        );
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Completer --> Requester", None),
            Some("input")
        );
        // One side unknown: the flow is stated relative to an actor whose role is not.
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Manager → Zetaalpha", None),
            None
        );
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Zetaalpha → Subordinate", None),
            None
        );
        // Two sides of the same role: source-like and destination-like disagree, so it is refused.
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Manager → Requester", None),
            None
        );
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Slave → Subordinate", None),
            None
        );
    }

    #[test]
    fn a_flow_arrow_must_be_single_forward_and_unambiguous() {
        // Every accepted spelling, longest-first so a longer form is one arrow and not two.
        for cell in [
            "Master ⟶ Slave",
            "Master ⇒ Slave",
            "Master → Slave",
            "Master ==> Slave",
            "Master --> Slave",
            "Master => Slave",
            "Master -> Slave",
        ] {
            assert_eq!(
                infer_signal_direction_from_flow_arrow(cell, None),
                Some("output"),
                "{cell}"
            );
        }
        // No arrow at all, and a cell that merely names both roles, stay with the existing paths.
        assert_eq!(
            infer_signal_direction_from_flow_arrow("Master Slave", None),
            None
        );
        assert_eq!(infer_signal_direction_from_flow_arrow("", None), None);
        // Reverse and bidirectional markers fail closed rather than being read as a forward flow.
        for cell in [
            "Slave ← Master",
            "Slave <- Master",
            "Master ↔ Slave",
            "Master <-> Slave",
            "Master ⇔ Slave",
            "Master <= Slave",
        ] {
            assert_eq!(
                infer_signal_direction_from_flow_arrow(cell, None),
                None,
                "{cell} must fail closed"
            );
        }
        // The splitter itself: exactly one arrow, or nothing.
        assert_eq!(
            split_on_single_flow_arrow("Master → Slave"),
            Some(("Master ", " Slave"))
        );
        assert_eq!(split_on_single_flow_arrow("A → B → C"), None);
        assert_eq!(split_on_single_flow_arrow("A -> B --> C"), None);
    }

    /// The rows the notation was opened for, carried verbatim from the persisted corpus
    /// (`683091…avalon…/source_ir.json`, `table_0012`) — a conformance fixture (ADR 0006).
    ///
    /// `readdata` and `writedata` are plainly listed in a table SpecForge itself typed
    /// `signal_description`, and produced nothing at all: the document writes direction as a flow
    /// and `readdata`'s width as the set of legal widths, and the reader read neither.
    #[test]
    fn the_corpus_arrow_direction_rows_declare_their_signals() {
        let table = StructuredTableRecord {
            table_id: "table_0012".to_string(),
            asset_id: "asset_0012".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&[
                "Signal Role",
                "Width",
                "Direction",
                "Required",
                "Description",
            ])],
            body_rows: vec![
                row(&[
                    "readdata",
                    "8, 16, 32, 64, 128, 256, 512, 1024",
                    "Slave → Master",
                    "No",
                    "The readdata driven from the slave to the master in response to a read transfer.",
                ]),
                row(&[
                    "writedata",
                    "8, 16, 32, 64, 128, 256, 512, 1024",
                    "Master → Slave",
                    "No",
                    "Data for write transfers.",
                ]),
                row(&[
                    "debugaccess",
                    "1",
                    "Master → Slave",
                    "No",
                    "When asserted, allows the processor to write on-chip memories configured as ROMs.",
                ]),
            ],
            row_count: 3,
            col_count: 5,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let mut accounting = Vec::new();
        let stmts = synthesize_signal_declarations(
            &table,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut accounting,
        );

        let texts: Vec<&str> = stmts.iter().map(|s| s.text.as_str()).collect();
        assert_eq!(
            texts,
            vec![
                // Direction recovered; the width is still the enumerated set `.2c` owns.
                "Signal readdata is input.",
                "Signal writedata is output.",
                // Already declared before this leaf, but width-only: it gains its direction.
                "Signal debugaccess is output width 1.",
            ],
            "the arrow column now decides direction: {texts:?}"
        );
        assert!(
            accounting[0].dropped_rows.is_empty(),
            "no row is dropped any more: {:?}",
            accounting[0]
        );
        assert_eq!(accounting[0].rows_considered, 3);
        assert_eq!(accounting[0].declarations_emitted, 3);
    }

    #[test]
    fn a_metavariable_needs_a_matched_pair_around_a_non_empty_body() {
        for placeholder in ["<n>", "<basename>", "(varies)", "[index]", "{width}"] {
            assert!(
                leading_name_token_is_placeholder(placeholder),
                "{placeholder} wraps a body in a matched pair"
            );
        }
        for plain in [
            "",
            " ",
            "<",
            "<>",
            "()",
            "ZETAALPHA",
            "ZETAALPHA,",
            "ZETA[3:0]",
            "<ZETAALPHA",
            "ZETAALPHA>",
            "(ZETAALPHA]",
        ] {
            assert!(
                !leading_name_token_is_placeholder(plain),
                "{plain:?} is not a metavariable"
            );
        }
        // Only the LEADING token decides: the rest of the cell is the row's own description.
        assert!(leading_name_token_is_placeholder("<basename> _outen"));
        assert!(!leading_name_token_is_placeholder("ZETAALPHA <wrapped>"));
    }

    #[test]
    fn rotated_signal_table_extracts_name_from_last_column() {
        // header says Name|Destination|Width|Description, but the body is rotated so the name
        // is in the LAST column (the AHB table_0009 pattern).
        let table = StructuredTableRecord {
            table_id: "table_0009".to_string(),
            asset_id: "asset_0009".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&["Name", "Destination", "Width", "Description"])],
            body_rows: vec![
                row(&[
                    "Manager",
                    "1",
                    "When HIGH, the HREADY signal indicates",
                    "HREADY",
                ]),
                row(&["Manager", "1", "Transfer response", "HRESP"]),
                row(&["Manager", "DATA_WIDTH", "Read data bus", "HRDATA"]),
            ],
            row_count: 3,
            col_count: 4,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let stmts = synthesize_signal_declarations(
            &table,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut Vec::new(),
        );
        let names: Vec<&str> = stmts
            .iter()
            .filter_map(|s| s.text.strip_prefix("Signal "))
            .filter_map(|s| s.split_whitespace().next())
            .collect();
        assert!(
            names.contains(&"HREADY"),
            "rotated table must yield HREADY, got {names:?}"
        );
        assert!(names.contains(&"HRESP") && names.contains(&"HRDATA"));
        assert!(
            !names.iter().any(|n| n.eq_ignore_ascii_case("MANAGER")),
            "the Destination actor must not become a signal, got {names:?}"
        );
    }

    #[test]
    fn a_name_cell_listing_a_signal_family_declares_every_member() {
        let table = StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&["Name", "Width", "Description"])],
            body_rows: vec![
                // A family written once: both members share a suffix.
                row(&["ZETA_ALPHA, OMEGA_ALPHA", "4", "An item"]),
                // Four members, sharing a suffix.
                row(&[
                    "ZETA_BETA, OMEGA_BETA, PSI_BETA, CHI_BETA",
                    "1",
                    "Another item",
                ]),
                // A shared prefix counts too, which is how a lowercase `reset, reset_n` pair reads.
                row(&["gamma, gamma_n", "1", "A third item"]),
            ],
            row_count: 4,
            col_count: 3,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let stmts = synthesize_signal_declarations(
            &table,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut Vec::new(),
        );
        let names: Vec<&str> = stmts
            .iter()
            .filter_map(|s| s.text.strip_prefix("Signal "))
            .filter_map(|s| s.split_whitespace().next())
            .collect();
        for expected in [
            "ZETA_ALPHA",
            "OMEGA_ALPHA",
            "ZETA_BETA",
            "OMEGA_BETA",
            "PSI_BETA",
            "CHI_BETA",
            "gamma",
            "gamma_n",
        ] {
            assert!(
                names.contains(&expected),
                "missing {expected}, got {names:?}"
            );
        }
        // Each member keeps its own declaration, and the family's width travels with it.
        assert!(
            stmts
                .iter()
                .any(|s| s.text == "Signal OMEGA_ALPHA is width 4.")
        );
        assert_eq!(prov.len(), stmts.len());
    }

    fn state_statements(texts: &[&str]) -> Vec<ExtractedStatement> {
        texts
            .iter()
            .enumerate()
            .map(|(index, text)| ExtractedStatement {
                statement_id: format!("statement_{index:04}"),
                class: StatementClass::SourceFact,
                modality: EvidenceModality::Text,
                text: (*text).to_string(),
                evidence_span_ids: vec![],
                related_visual_evidence_ids: vec![],
            })
            .collect()
    }

    fn state_record(id: &str, name: &str, support: &[&str]) -> ProtocolStateRecord {
        ProtocolStateRecord {
            state_id: id.to_string(),
            machine_name: None,
            state_name: name.to_string(),
            action: None,
            supporting_statement_ids: support.iter().map(|s| (*s).to_string()).collect(),
        }
    }

    fn captioned_table(caption: &str, header: &[&str], rows: &[&[&str]]) -> StructuredTableRecord {
        StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: Some(caption.to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(header)],
            body_rows: rows.iter().map(|r| row(r)).collect(),
            row_count: rows.len() as u32 + 1,
            col_count: header.len() as u32,
        }
    }

    #[test]
    fn a_property_table_is_not_a_signal_inventory() {
        // WIRE-BASED-100.10e — the caption's last word is the document's own word for what the table
        // is, and the first header names the table's SUBJECT rather than a column role.
        let table = captioned_table(
            "Table A1.1: Zeta_Alpha_Signals property",
            &["Zeta_Alpha_Signals", "Default", "Description"],
            &[
                &["True", "", "Zeta alpha signals are included."],
                &["False", "Y", "Zeta alpha signals are not present."],
            ],
        );
        assert!(table_states_a_property_rather_than_a_signal_inventory(
            &table
        ));
    }

    #[test]
    fn a_role_phrase_that_repeats_in_its_caption_is_still_a_role_phrase() {
        // The shape test alone refuses real tables: APB heads its check-signal table `Check signal`
        // under the caption `Check signal descriptions`, and it declares real wires.
        let table = captioned_table(
            "Table 5-1 Check signal descriptions",
            &["Check signal", "Description"],
            &[&["ZETA_ALPHACHK", "Parity over the zeta alpha bus."]],
        );
        assert!(!table_states_a_property_rather_than_a_signal_inventory(
            &table
        ));
    }

    #[test]
    fn a_property_caption_alone_does_not_refuse_a_column_role_header() {
        // Condition 1 without condition 2: the header is a column role, so the table still counts.
        let table = captioned_table(
            "Table A1.2: Zeta_Alpha_Signals property",
            &["Name", "Width", "Description"],
            &[&["ZETA_ALPHA", "1", "A real wire."]],
        );
        assert!(!table_states_a_property_rather_than_a_signal_inventory(
            &table
        ));
        // And condition 2 without condition 1: an encoding table headed by its own signal stays.
        let encoding = captioned_table(
            "Table C5-5 Authentication signal restrictions for ZETA_ALPHA",
            &["ZETA_ALPHA", "Meaning"],
            &[&["0", "Disabled."]],
        );
        assert!(!table_states_a_property_rather_than_a_signal_inventory(
            &encoding
        ));
    }

    #[test]
    fn a_state_binds_to_the_machine_its_own_statement_names() {
        // WIRE-BASED-100.8g — the document introduces the machine with its own role phrase and then
        // names it beside the state. Alpha-renamed: no protocol vocabulary is involved.
        let statements = state_statements(&[
            "The Zeta Alpha State Machine (ZETA_ALPHASM) controls the omega interface.",
            "- When the ZETA_ALPHASM goes through the Capture-Omega state, data is latched.",
        ]);
        let mut states = vec![state_record("s1", "Capture-Omega", &["statement_0001"])];
        bind_protocol_state_machines(&mut states, &statements);
        assert_eq!(states[0].machine_name.as_deref(), Some("ZETA_ALPHASM"));
    }

    #[test]
    fn two_machines_in_one_statement_leave_the_state_unbound() {
        // An ambiguous binding is worse than an absent one — WIRE-BASED-100.8d's own conclusion about
        // minting a wrong phase, applied to machines.
        let statements = state_statements(&[
            "The Zeta State Machine (ZETASM) and the Omega State Machine (OMEGASM) are independent.",
            "- The ZETASM and the OMEGASM both enter the Idle-Alpha state after reset.",
        ]);
        let mut states = vec![state_record("s1", "Idle-Alpha", &["statement_0001"])];
        bind_protocol_state_machines(&mut states, &statements);
        assert!(states[0].machine_name.is_none());
    }

    #[test]
    fn a_state_whose_statement_names_no_machine_stays_unbound() {
        let statements = state_statements(&[
            "The Zeta State Machine (ZETASM) controls the link.",
            "- The receiver enters the Idle-Alpha state after reset.",
        ]);
        let mut states = vec![state_record("s1", "Idle-Alpha", &["statement_0001"])];
        bind_protocol_state_machines(&mut states, &statements);
        assert!(states[0].machine_name.is_none());
    }

    #[test]
    fn a_machine_introduction_must_be_closed_and_whole() {
        // An unclosed parenthetical introduces nothing, and `state machine` must be the whole phrase.
        assert_eq!(
            state_machine_introductions("The Zeta State Machine (ZETASM) controls the link."),
            vec!["ZETASM".to_string()]
        );
        assert_eq!(
            state_machine_introductions("The Zeta state machine, ZETASM, controls the link."),
            vec!["ZETASM".to_string()]
        );
        assert!(
            state_machine_introductions("The state machine (see Figure 2 for details) is shown.")
                .is_empty(),
            "an unclosed or non-identifier parenthetical introduces nothing"
        );
        assert!(
            state_machine_introductions(
                "A substate machine (ZETASM) is not a state machine intro."
            )
            .is_empty(),
            "`state machine` must be a whole phrase, not the tail of a longer word"
        );
    }

    #[test]
    fn a_prose_name_cell_is_never_split_into_a_family() {
        // Every comma-separated element is a single well-formed word, so a shape check alone would
        // admit this. The members share no affix, which is what says it is a sentence.
        let table = StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&["Name", "Width", "Description"])],
            body_rows: vec![
                row(&["Channel, bidirectional", "1", "An item"]),
                // A comma list whose elements are not single identifiers is not a list either.
                row(&["ZETA_ALPHA, active LOW", "1", "Another item"]),
            ],
            row_count: 3,
            col_count: 3,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let stmts = synthesize_signal_declarations(
            &table,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut Vec::new(),
        );
        let names: Vec<&str> = stmts
            .iter()
            .filter_map(|s| s.text.strip_prefix("Signal "))
            .filter_map(|s| s.split_whitespace().next())
            .collect();
        assert!(
            !names
                .iter()
                .any(|n| n.eq_ignore_ascii_case("bidirectional")),
            "a prose cell must not become a family, got {names:?}"
        );
        assert!(
            !names.iter().any(|n| n.eq_ignore_ascii_case("active")),
            "a multi-word element must not become a name, got {names:?}"
        );
        // The cells still declare their first token, exactly as before.
        assert!(names.contains(&"Channel") && names.contains(&"ZETA_ALPHA"));
    }

    fn prov(entries: &[(&str, &str)]) -> Vec<TableSignalDeclarationProvenanceRecord> {
        entries
            .iter()
            .enumerate()
            .map(
                |(index, (table_id, signal_name))| TableSignalDeclarationProvenanceRecord {
                    statement_id: format!("statement_{index:04}"),
                    signal_name: (*signal_name).to_string(),
                    table_id: (*table_id).to_string(),
                },
            )
            .collect()
    }

    #[test]
    fn a_base_name_table_the_document_instantiates_is_a_template() {
        // `t_pattern` names three base members; two prefixes instantiate every one of them, and
        // the instantiations live inside larger heterogeneous inventories. That is a naming
        // pattern, not three wires.
        let provenance = prov(&[
            ("t_pattern", "ZETA"),
            ("t_pattern", "OMEGA"),
            ("t_pattern", "KAPPA"),
            ("t_first", "AAZETA"),
            ("t_first", "AAOMEGA"),
            ("t_first", "AAKAPPA"),
            ("t_first", "AAIOTA"),
            ("t_second", "ABZETA"),
            ("t_second", "ABOMEGA"),
            ("t_second", "ABKAPPA"),
            ("t_second", "ABIOTA"),
        ]);
        let templates = base_name_template_tables(&provenance);
        assert_eq!(
            templates.iter().map(String::as_str).collect::<Vec<_>>(),
            vec!["t_pattern"],
            "only the base-name table is a template, got {templates:?}"
        );
    }

    #[test]
    fn a_mirrored_port_list_is_two_real_levels_not_a_template() {
        // The same shape as above EXCEPT that `t_first` declares exactly the prefixed copy of
        // `t_base`. That mirror is hierarchical qualification — a component's own ports beside the
        // wrapper's — and both levels are real, so nothing may be withheld.
        let provenance = prov(&[
            ("t_base", "ZETA"),
            ("t_base", "OMEGA"),
            ("t_base", "KAPPA"),
            ("t_first", "AAZETA"),
            ("t_first", "AAOMEGA"),
            ("t_first", "AAKAPPA"),
            ("t_second", "ABZETA"),
            ("t_second", "ABOMEGA"),
            ("t_second", "ABKAPPA"),
        ]);
        assert!(
            base_name_template_tables(&provenance).is_empty(),
            "a mirrored port list must keep its declarations"
        );
    }

    #[test]
    fn one_instantiation_or_no_shared_family_is_not_a_template() {
        // A single instantiating prefix is an accident, not a pattern.
        let single = prov(&[
            ("t_base", "ZETA"),
            ("t_base", "OMEGA"),
            ("t_base", "KAPPA"),
            ("t_first", "AAZETA"),
            ("t_first", "AAOMEGA"),
            ("t_first", "AAKAPPA"),
            ("t_first", "AAIOTA"),
        ]);
        assert!(base_name_template_tables(&single).is_empty());
        // Two prefixes, but no ONE prefix reaches every member — unrelated affix overlap.
        let unshared = prov(&[
            ("t_base", "ZETA"),
            ("t_base", "OMEGA"),
            ("t_base", "KAPPA"),
            ("t_first", "AAZETA"),
            ("t_first", "ABZETA"),
            ("t_first", "AAIOTA"),
            ("t_second", "BAOMEGA"),
            ("t_second", "BBOMEGA"),
            ("t_second", "BAKAPPA"),
            ("t_second", "BBKAPPA"),
            ("t_second", "BAIOTA"),
        ]);
        assert!(base_name_template_tables(&unshared).is_empty());
    }

    #[test]
    fn withholding_a_template_keeps_a_name_a_concrete_table_also_declares() {
        let mut provenance = prov(&[
            ("t_pattern", "ZETA"),
            ("t_pattern", "OMEGA"),
            ("t_pattern", "KAPPA"),
            ("t_first", "AAZETA"),
            ("t_first", "AAOMEGA"),
            ("t_first", "AAKAPPA"),
            ("t_first", "AAIOTA"),
            ("t_second", "ABZETA"),
            ("t_second", "ABOMEGA"),
            ("t_second", "ABKAPPA"),
            ("t_second", "ABIOTA"),
            // A concrete table declares ZETA in its own right.
            ("t_second", "ZETA"),
        ]);
        let mut synthesized: Vec<ExtractedStatement> = provenance
            .iter()
            .map(|record| ExtractedStatement {
                statement_id: record.statement_id.clone(),
                class: StatementClass::SourceFact,
                modality: EvidenceModality::Text,
                text: format!("Signal {} is width 1.", record.signal_name),
                evidence_span_ids: vec![],
                related_visual_evidence_ids: vec![],
            })
            .collect();
        let catalog = withhold_base_name_template_declarations(&mut synthesized, &mut provenance);
        assert_eq!(
            catalog
                .withheld_names
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            vec!["KAPPA", "OMEGA"],
            "ZETA is declared by a concrete table and must survive"
        );
        assert!(catalog.declared_names.contains("ZETA"));
        assert!(
            provenance
                .iter()
                .all(|record| record.table_id != "t_pattern"),
            "the template table contributes no provenance"
        );
        assert_eq!(synthesized.len(), provenance.len());
    }

    #[test]
    fn an_alpha_variant_placeholder_is_not_a_wire() {
        let declared: std::collections::HashSet<String> = ["ZAOMEGA", "ZBOMEGA", "ZETA"]
            .into_iter()
            .map(str::to_string)
            .collect();
        // One lower-case position, and wildcarding it matches two declared names.
        assert!(is_alpha_variant_placeholder("ZxOMEGA", &declared));
        // An all-upper-case identifier is never a placeholder, however unfamiliar.
        assert!(!is_alpha_variant_placeholder("ZCOMEGA", &declared));
        // A name the tables declare is a wire whatever its spelling.
        assert!(!is_alpha_variant_placeholder("ZETA", &declared));
        // One sibling is not a family.
        let one: std::collections::HashSet<String> =
            ["ZAOMEGA"].into_iter().map(str::to_string).collect();
        assert!(!is_alpha_variant_placeholder("ZxOMEGA", &one));
        // A LEADING lower-case letter is the active-LOW convention, never a metavariable, even
        // when the document happens to declare two same-length siblings.
        let polarity: std::collections::HashSet<String> = ["NRESET", "PRESET"]
            .into_iter()
            .map(str::to_string)
            .collect();
        assert!(!is_alpha_variant_placeholder("nRESET", &polarity));
        // A TRAILING one is the indexed-family convention, whose recovery another leaf owns.
        let indexed: std::collections::HashSet<String> =
            ["ZETAA", "ZETAB"].into_iter().map(str::to_string).collect();
        assert!(!is_alpha_variant_placeholder("ZETAx", &indexed));
    }

    #[test]
    fn paired_name_cells_keep_the_header_designated_column() {
        // The name cell lists a signal PAIR, so its first whitespace token carries a trailing
        // separator. Scoring that column without the row loop's own strip counted ZERO signal
        // tokens in it, and the override handed the table to the Description column — whose
        // sentences begin with capitalised words that read as identifiers. The declarations
        // then WERE those words (AXI `table_0187`: `Secure`, `Stream`, `Asserted`).
        let table = StructuredTableRecord {
            table_id: "t".to_string(),
            asset_id: "a".to_string(),
            page_id: None,
            caption_text: None,
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&["Name", "Width", "Default", "Description"])],
            body_rows: vec![
                row(&[
                    "ZETA_ALPHA, OMEGA_ALPHA",
                    "4",
                    "0b0",
                    "Secure identifier for a thing",
                ]),
                row(&[
                    "ZETA_BETA, OMEGA_BETA",
                    "1",
                    "0b0",
                    "Stream identifier for a thing",
                ]),
                row(&[
                    "ZETA_GAMMA, OMEGA_GAMMA",
                    "2",
                    "0b0",
                    "Asserted HIGH to indicate a thing",
                ]),
            ],
            row_count: 3,
            col_count: 4,
        };
        let mut counter = 0usize;
        let mut prov = Vec::new();
        let stmts = synthesize_signal_declarations(
            &table,
            SectionKind::Unknown,
            "",
            &mut counter,
            None,
            &mut prov,
            &mut Vec::new(),
        );
        let names: Vec<&str> = stmts
            .iter()
            .filter_map(|s| s.text.strip_prefix("Signal "))
            .filter_map(|s| s.split_whitespace().next())
            .collect();
        assert!(
            names.contains(&"ZETA_ALPHA") && names.contains(&"ZETA_BETA"),
            "the paired name column must still be the name column, got {names:?}"
        );
        for prose in ["SECURE", "STREAM", "ASSERTED"] {
            assert!(
                !names.iter().any(|n| n.eq_ignore_ascii_case(prose)),
                "a description word must never become a declaration, got {names:?}"
            );
        }
    }

