#[cfg(test)]
mod swd_serial_extraction_4e {
    //! SWD-SERIAL-EXTRACTION.4e — explicit actor/data/clock interface-edge timing.
    use super::*;

    fn stmt(id: &str, class: StatementClass, text: &str) -> ExtractedStatement {
        ExtractedStatement {
            statement_id: id.to_string(),
            class,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        }
    }

    fn declarations() -> Vec<ExtractedStatement> {
        vec![
            stmt(
                "data",
                StatementClass::SourceFact,
                "Signal DATA_IO is inout width 1.",
            ),
            stmt(
                "clock",
                StatementClass::SourceFact,
                "Signal SERIAL_CLK is input width 1.",
            ),
        ]
    }

    #[test]
    fn coupled_sample_and_drive_change_timing_is_one_complete_record() {
        let mut statements = declarations();
        statements.push(stmt(
            "timing",
            StatementClass::TimingConstraint,
            "When the endpoint samples DATA_IO, sampling is performed on the rising edge of SERIAL_CLK. When the endpoint drives DATA_IO, or stops driving it, signal changes are performed on the rising edge of SERIAL_CLK.",
        ));

        let records = extract_interface_edge_timings(&statements);
        assert_eq!(records.len(), 1, "coupled clauses merge: {records:?}");
        let timing = &records[0];
        assert_eq!(timing.timing_id, "interface_edge_timing_0001");
        assert_eq!(timing.actor_name, "endpoint");
        assert_eq!(timing.signal_name, "DATA_IO");
        assert_eq!(timing.clock_signal, "SERIAL_CLK");
        assert_eq!(timing.edge, InterfaceClockEdge::Rising);
        assert!(timing.samples_on_edge);
        assert!(timing.drive_changes_on_edge);
        assert_eq!(timing.supporting_statement_ids, ["timing"]);
    }

    #[test]
    fn incomplete_or_unclassified_prose_fails_closed() {
        let exact = "When the endpoint samples DATA_IO, sampling is performed on the rising edge of SERIAL_CLK.";
        let mut wrong_class = declarations();
        wrong_class.push(stmt("source", StatementClass::SourceFact, exact));
        assert!(extract_interface_edge_timings(&wrong_class).is_empty());

        let mut undeclared_clock = vec![stmt(
            "data",
            StatementClass::SourceFact,
            "Signal DATA_IO is inout width 1.",
        )];
        undeclared_clock.push(stmt("timing", StatementClass::TimingConstraint, exact));
        assert!(extract_interface_edge_timings(&undeclared_clock).is_empty());

        let mut no_edge = declarations();
        no_edge.push(stmt(
            "timing",
            StatementClass::TimingConstraint,
            "When the endpoint samples DATA_IO, sampling is performed using SERIAL_CLK.",
        ));
        assert!(extract_interface_edge_timings(&no_edge).is_empty());
    }

    #[test]
    fn falling_edge_and_manifest_are_derived_without_named_protocol_vocabulary() {
        let mut statements = declarations();
        statements.push(stmt(
            "timing",
            StatementClass::TimingConstraint,
            "When a receiver samples DATA_IO, sampling is performed on the falling edge of SERIAL_CLK.",
        ));
        let mut manifest = ExtractionManifest::default();
        let records = interface_edge_timing_surface(&statements, &mut manifest);
        assert_eq!(records[0].actor_name, "receiver");
        assert_eq!(records[0].edge, InterfaceClockEdge::Falling);
        assert!(records[0].samples_on_edge);
        assert!(!records[0].drive_changes_on_edge);
        let surface = manifest
            .surfaces
            .iter()
            .find(|surface| surface.surface == "interface_edge_timings")
            .expect("registered timing surface");
        assert_eq!(surface.eligible, 1);
        assert_eq!(surface.entries[0].name, "timing.interface_edge_prose");
        assert_eq!(surface.entries[0].produced, 1);
        assert_eq!(surface.entries[0].kept, 1);
    }
}

#[cfg(test)]
mod wire_based_100_8a {
    //! WIRE-BASED-100.8a — proof-carrying relocation of a verified EvidenceIR.
    use std::fs;
    use std::path::PathBuf;

    use tempfile::tempdir;

    use super::{EvidenceArtifactLayout, EvidenceIr};
    use crate::error::Result;
    use crate::ir::source::SourceIr;

    #[test]
    fn relocation_through_the_seam_preserves_verification() -> Result<()> {
        // An EvidenceIR's proof is taken over its public fields, and those include
        // `artifact_layout`, so the proof binds where the artifact is stored. A consumer that must
        // score the extraction commands without mutating the corpus therefore cannot simply rewrite
        // the layout of a copy. Both halves of that contract are pinned here.
        let tempdir = tempdir()?;
        let source = tempdir.path().join("relocatable.md");
        let source_artifact_base = tempdir.path().join("generated").join("source_ir");
        let evidence_artifact_base = tempdir.path().join("generated").join("evidence_ir");
        fs::write(
            &source,
            "# Protocol\nSignal XREQV is output width 1.\nXREQV must be HIGH when the transfer is accepted.\n",
        )?;
        let source_ir = SourceIr::build(&source, &source_artifact_base)?;
        source_ir.write_test_fixture_to_disk()?;
        let evidence_ir = EvidenceIr::build(
            &source_ir.artifact_layout.source_ir_path,
            &evidence_artifact_base,
        )?;
        evidence_ir.write_test_fixture_to_disk()?;
        let original_path = evidence_ir.artifact_layout.evidence_ir_path.clone();
        let document_key = evidence_ir.document_identity.document_key.clone();

        // Both artifacts below are persisted with a plain `fs::write` rather than `write_to_disk`,
        // because `write_to_disk`'s test-fixture re-seal would repair precisely the failure under
        // test and turn either assertion into a false green.
        let persist = |artifact: &EvidenceIr| -> Result<PathBuf> {
            let path = artifact.artifact_layout.evidence_ir_path.clone();
            fs::create_dir_all(&artifact.artifact_layout.artifact_root)?;
            fs::write(
                &path,
                serde_json::to_string_pretty(&artifact.persisted_clone()?)?,
            )?;
            Ok(path)
        };

        // Control — the unsupported move: rewrite `artifact_layout` and leave every other byte
        // identical. The production read path must still refuse it.
        let mut unsealed = EvidenceIr::load_from_path(&original_path)?;
        let unsealed_root = tempdir.path().join("unsealed").join(&document_key);
        unsealed.artifact_layout = EvidenceArtifactLayout {
            artifact_root: unsealed_root.clone(),
            evidence_ir_path: unsealed_root.join("evidence_ir.json"),
        };
        let refusal = EvidenceIr::load_from_path(&persist(&unsealed)?)
            .expect_err("an unsealed artifact_layout rewrite must stay refused");
        assert!(
            refusal.to_string().contains("topology is stale"),
            "unexpected refusal: {refusal}"
        );

        // The supported seam: relocate and re-prove, then read it back through that same path.
        let relocated_base = tempdir.path().join("relocated");
        let relocated =
            EvidenceIr::load_relocated_to_artifact_base_root(&original_path, &relocated_base)?;
        assert_eq!(
            relocated.artifact_layout.evidence_ir_path,
            relocated_base.join(&document_key).join("evidence_ir.json"),
            "relocation must keep the <base>/<document_key> layout the rebuild replays"
        );
        let reloaded = EvidenceIr::load_from_path(&persist(&relocated)?)?;

        // Only the storage location — and the proof that binds it — may differ.
        let mut expected = EvidenceIr::load_from_path(&original_path)?;
        assert_ne!(expected.proof_ledger, reloaded.proof_ledger);
        expected.artifact_layout = reloaded.artifact_layout.clone();
        expected.proof_ledger = reloaded.proof_ledger.clone();
        assert_eq!(expected, reloaded);
        Ok(())
    }
}

#[cfg(test)]
mod invariant_shape_admission_3 {
    //! `INVARIANT-SHAPE-ADMISSION.3` — a signal-description row's description cell may state an
    //! obligation, and the obligation is only about that row's signal when the clause's own
    //! grammar binds it there. `.2` measured 20 such clauses across the 27-document
    //! proof-carrying corpus; 12 bind (1 with no subject at all, 11 naming the row's signal), 5
    //! head with a pronoun and 3 with a different nominal.
    use super::*;
    use crate::error::Result;
    use crate::ir::source::StructuredTableRecord;
    use std::fs;
    use tempfile::tempdir;

    fn cell(text: &str, is_header: bool) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header,
        }
    }

    fn row(cells: &[&str], is_header: bool) -> Vec<StructuredTableCellRecord> {
        cells.iter().map(|text| cell(text, is_header)).collect()
    }

    /// The grammar, pinned over the census's own four shapes and over the near-misses that would
    /// widen it. Nothing here names a signal: the rule is which token precedes the modal.
    #[test]
    fn an_obligation_binds_to_the_nominal_immediately_before_its_modal() {
        // ABSENT — the modal opens the clause, so the clause has no subject of its own. This is
        // the shape only the row's header can complete.
        assert_eq!(
            obligation_subject(" Must be valid when RVALID is asserted"),
            ObligationSubject::Absent
        );
        assert_eq!(
            obligation_subject("Shall be stable"),
            ObligationSubject::Absent
        );
        // HEAD — the nominal the obligation binds to, helper words skipped.
        assert_eq!(
            obligation_subject(" PSTRB must not be active during a read transfer"),
            ObligationSubject::Head("PSTRB")
        );
        assert_eq!(
            obligation_subject(
                " When a Subordinate is selected for a non-IDLE transfer, HSELx must be asserted"
            ),
            ObligationSubject::Head("HSELx")
        );
        // A width PARAMETER is a different nominal from the signal whose row states it.
        assert_eq!(
            obligation_subject(" HBURST_WIDTH must be 0 or 3"),
            ObligationSubject::Head("HBURST_WIDTH")
        );
        // A common noun heads just as a signal name does — the rule reads position, not vocabulary.
        assert_eq!(
            obligation_subject(" Indicates which tags must be written to memory"),
            ObligationSubject::Head("tags")
        );
        // A pronoun IS a head and is reported as one, which is what lets the reader refuse it.
        assert_eq!(
            obligation_subject(" It must be the same for every response of the transaction"),
            ObligationSubject::Head("It")
        );
        assert_eq!(
            obligation_subject(
                " It has the same timing as the address signals, however, it must remain constant"
            ),
            ObligationSubject::Head("it")
        );
        assert_eq!(
            obligation_subject(" A user-defined value that must be reflected from a write request"),
            ObligationSubject::Head("that")
        );
        // NOT AN OBLIGATION — a descriptive cell, including one carrying a weaker modal word that
        // the `is_invariant_like` admission list would accept but an obligation is not built from.
        assert_eq!(
            obligation_subject(" Asserted high to indicate that an exclusive access is required"),
            ObligationSubject::NotAnObligation
        );
        assert_eq!(
            obligation_subject("Response for transactions on the read channels"),
            ObligationSubject::NotAnObligation
        );
        // Whole-identifier matching: a longer word merely containing a modal is not one.
        assert_eq!(
            obligation_subject("The mustard-coloured marshalling buffer"),
            ObligationSubject::NotAnObligation
        );
        assert_eq!(obligation_subject(""), ObligationSubject::NotAnObligation);
    }

    fn read_rows(
        body_rows: Vec<Vec<StructuredTableCellRecord>>,
    ) -> Result<Vec<SignalConstraintRecord>> {
        let tempdir = tempdir()?;
        let source = tempdir.path().join("spec.md");
        let base = tempdir.path().join("generated").join("source_ir");
        fs::write(&source, "# Signal descriptions\n")?;
        let mut source_ir = SourceIr::build(&source, &base)?;
        let col_count = body_rows.first().map(Vec::len).unwrap_or(0) as u32;
        let row_count = body_rows.len() as u32 + 1;
        source_ir.structured_tables.push(StructuredTableRecord {
            table_id: "table_0001".to_string(),
            asset_id: "asset_0001".to_string(),
            page_id: None,
            caption_text: Some("Signal descriptions".to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![row(&["Signal", "Width", "Source", "Description"], true)],
            body_rows,
            row_count,
            col_count,
        });
        let known: HashSet<String> = ["ZETAREADY", "OMEGABURST", "ALPHACHUNK", "SIGMASTRB"]
            .into_iter()
            .map(String::from)
            .collect();
        let mut counter = 0usize;
        Ok(extract_signal_description_row_constraints(
            &source_ir,
            &[],
            &known,
            &mut counter,
            None,
        ))
    }

    fn subjects(records: &[SignalConstraintRecord]) -> Vec<&str> {
        records
            .iter()
            .map(|record| record.subject_signal.as_str())
            .collect()
    }

    /// The reader, over one table carrying every shape the census found. The two admissions are
    /// the leaf's recall; the three refusals are its precision, and the `_WIDTH` row is the one
    /// the serialized-statement path currently mis-attributes to the signal.
    #[test]
    fn a_row_states_a_constraint_only_when_its_clause_binds_to_that_row_signal() -> Result<()> {
        let records = read_rows(vec![
            // ABSENT: the header is the only place the subject exists.
            row(
                &[
                    "ZETAREADY",
                    "1",
                    "Requester",
                    "Response for transactions on the read channels. Must be valid when ALPHACHUNK is asserted.",
                ],
                false,
            ),
            // HEAD == the row's own signal.
            row(
                &[
                    "SIGMASTRB",
                    "8",
                    "Requester",
                    "Write strobe. SIGMASTRB must not be active during a read transfer.",
                ],
                false,
            ),
            // HEAD == a width parameter: the obligation is about the parameter, not the signal.
            row(
                &[
                    "OMEGABURST",
                    "OMEGABURST_WIDTH",
                    "Completer",
                    "Indicates how many transfers are in the burst. OMEGABURST_WIDTH must be 0 or 3.",
                ],
                false,
            ),
            // HEAD == a pronoun: the referent is unresolved, so the row stays residual.
            row(
                &[
                    "ALPHACHUNK",
                    "1",
                    "Completer",
                    "Asserted high to indicate validity. It must be the same for every response.",
                ],
                false,
            ),
            // No obligation at all: a descriptive cell states nothing to promote.
            row(
                &[
                    "ZETAREADY",
                    "1",
                    "Requester",
                    "Asserted high to indicate that an exclusive access is required.",
                ],
                false,
            ),
        ])?;

        assert_eq!(
            subjects(&records),
            vec!["ZETAREADY", "SIGMASTRB"],
            "only the subjectless and self-named clauses bind: {records:?}"
        );
        assert!(
            !records
                .iter()
                .any(|record| record.subject_signal == "OMEGABURST"),
            "a width parameter's obligation must not be attributed to the signal: {records:?}"
        );

        // The subjectless clause keeps the document's own words and its condition, and the row
        // supplies the subject the clause never states.
        let absent = &records[0];
        assert_eq!(
            absent.source_text,
            "Must be valid when ALPHACHUNK is asserted"
        );
        assert_eq!(
            absent.condition_text.as_deref(),
            Some("ALPHACHUNK is asserted")
        );
        // The self-named clause is one clause, not one cell, and its obligation is TYPED rather than
        // defaulted: `EXTRACTION-QUALITY-GAUGE.3i` taught the classifier the negative spelling of
        // `deasserted`, so this reads `must_be_deasserted` instead of the untyped `must_be_stable`
        // that `.3` shipped and recorded as imprecise. `negated` is then false by the
        // `WIRE-BASED-100.5b` guard, because the kind already encodes the negation.
        let named = &records[1];
        assert_eq!(named.constraint_kind.as_str(), "must_be_deasserted");
        assert!(
            !named.negated,
            "must_be_deasserted encodes its own negation: {named:?}"
        );
        assert_eq!(
            named.source_text,
            "SIGMASTRB must not be active during a read transfer"
        );
        Ok(())
    }

    /// A cell stating several obligations yields several records. The serialized statement the
    /// other paths read collapses them into one and keeps only the first, which is why APB's
    /// three-bullet USER-signal rows publish a single constraint today.
    #[test]
    fn each_obligation_clause_in_a_cell_becomes_its_own_record() -> Result<()> {
        let records = read_rows(vec![row(
            &[
                "SIGMASTRB",
                "8",
                "Requester",
                "User-defined request attribute. • SIGMASTRB must be valid when ZETAREADY is asserted. \
                 • SIGMASTRB must have the same value in every cycle during the Access phase.",
            ],
            false,
        )])?;
        assert_eq!(records.len(), 2, "one record per obligation: {records:?}");
        assert!(
            records
                .iter()
                .all(|record| record.subject_signal == "SIGMASTRB")
        );
        assert_eq!(
            records[0].condition_text.as_deref(),
            Some("ZETAREADY is asserted")
        );
        // `during` is one of the condition markers the shared clause reader already recognizes,
        // so the second obligation's scope lands in `condition_text` rather than in its text.
        assert_eq!(
            records[1].condition_text.as_deref(),
            Some("the Access phase")
        );
        assert_eq!(
            records[1].source_text,
            "SIGMASTRB must have the same value in every cycle during the Access phase"
        );
        Ok(())
    }

    /// The name cell is never authority on its own: a row naming something this document has not
    /// declared states no signal constraint, however well-formed its cell reads.
    #[test]
    fn an_undeclared_name_cell_yields_no_constraint() -> Result<()> {
        let records = read_rows(vec![row(
            &[
                "KAPPAUNDECLARED",
                "1",
                "Requester",
                "KAPPAUNDECLARED must be valid when ZETAREADY is asserted.",
            ],
            false,
        )])?;
        assert!(records.is_empty(), "undeclared subject: {records:?}");
        Ok(())
    }
}

#[cfg(test)]
mod invariant_shape_admission_5 {
    //! `INVARIANT-SHAPE-ADMISSION.5` — `is_post_passive_binding_only_subject` exempts a table row
    //! because "a table row supplies subject context from its other cells". True when the obligation
    //! clause has no subject of its own; false when it has a DIFFERENT one, and there the exemption
    //! hands `HBURST_WIDTH must be 0 or 3` to `HBURST`. The narrowing is one condition: the clause is
    //! headed by an uppercase-run identifier that is not the subject.
    use super::*;

    /// The refusal. Both are real persisted records (`dyn_sigcon_0013`, `dyn_sigcon_0014`), reproduced
    /// here on invented names so a control cannot become a name list.
    #[test]
    fn a_row_whose_obligation_names_a_width_parameter_does_not_constrain_the_signal() {
        for (row, subject) in [
            (
                "| OMEGABURST | Subordinate | OMEGABURST_WIDTH | Indicates how many transfers are in \
                 the burst. OMEGABURST_WIDTH must be 0 or 3. |",
                "OMEGABURST",
            ),
            (
                "| ZETAPROT | Subordinate | ZETAPROT_WIDTH | Protection control signal. \
                 ZETAPROT_WIDTH must be 0, 4, or 7. |",
                "ZETAPROT",
            ),
            // The same shape without an underscore: the scan lifts a SHORTER declared name out of a
            // longer identifier (`WTAG` from `WTAGUPDATE`), which the head test catches identically.
            (
                "| Update | 0b10 | Tag values have been updated. SIGMATAGUPDATE must be deasserted. |",
                "SIGMATAG",
            ),
        ] {
            assert!(
                is_post_passive_binding_only_subject(row, subject),
                "{subject} does not head this row's obligation: {row:?}"
            );
        }
    }

    /// The four shapes the exemption exists for, each of which a coarser rule destroys. Every one is
    /// taken from the persisted corpus census.
    #[test]
    fn a_row_keeps_its_subject_context_for_every_shape_the_exemption_was_written_for() {
        for (row, subject, why) in [
            // SUBJECTLESS — the clause opens with the modal, so only the row's header can supply a
            // subject. This is gate 2's whole purpose (AXI-H `RLAST`, Intel VT-d `HAW`).
            (
                "| ZETALAST | Manager | 1 | Indicates the last transfer in a burst. Must be HIGH. |",
                "ZETALAST",
                "subjectless clause",
            ),
            // COMMON-NOUN HEAD — a descriptor standing in for the identifier beside it (SMMU
            // `LASECSID`). `signal` is not an identifier, so the head test declines.
            (
                "| ZETASECSID | Context | StreamID security level. When ZETAFLOW is ATST, the \
                 ZETASECSID signal must be 0. |",
                "ZETASECSID",
                "descriptor head",
            ),
            // FIELD-CELL HEAD — the `.3e` register class (NVMe `ELEN`).
            (
                "| 31:16 | Element Length (ZETALEN): This field shall be 0h when deleting an entry. |",
                "ZETALEN",
                "field-cell head",
            ),
            // ACTIVE OBLIGATION — the head is the AGENT and the signal is the object; gate 3 already
            // declines because there is no passive binding lead (LPI `PREQ`).
            (
                "| P_ACCEPT | Device has accepted the request. Controller must set ZETAREQ LOW. |",
                "ZETAREQ",
                "active obligation",
            ),
        ] {
            assert!(
                !is_post_passive_binding_only_subject(row, subject),
                "{why}: {subject} must keep its row context: {row:?}"
            );
        }
    }

    /// The narrowing must not reach PROSE, which gate 2 never exempted: a prose obligation headed by a
    /// foreign identifier was already refused, and one naming its subject was already kept.
    #[test]
    fn prose_behaviour_is_unchanged_by_the_row_narrowing() {
        assert!(
            !is_post_passive_binding_only_subject("ZETASEL must be HIGH.", "ZETASEL"),
            "a prose subject named before the lead is real"
        );
        assert!(
            is_post_passive_binding_only_subject(
                "Lane reversal shall be compatible with all supported lane widths. Link devices \
                 (ZETAPORT) negotiate it.",
                "ZETAPORT"
            ),
            "a prose subject reachable only after the lead was already refused"
        );
    }

    /// The head reading itself, over the shapes the census found — one definition shared with the
    /// table reader's `obligation_subject`.
    #[test]
    fn the_obligation_head_is_the_last_content_token_before_the_modal() {
        assert_eq!(content_head(" OMEGABURST_WIDTH "), Some("OMEGABURST_WIDTH"));
        assert_eq!(content_head(" the ZETASECSID signal "), Some("signal"));
        assert_eq!(content_head(" This field "), Some("field"));
        // helper words are skipped so the head is the one closest to the verb
        assert_eq!(content_head(" ZETAREADY is "), Some("ZETAREADY"));
        assert_eq!(content_head("   "), None);
        assert_eq!(content_head(" and to be "), None);
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3i {
    //! `EXTRACTION-QUALITY-GAUGE.3i` — a flag that MODIFIES an obligation must be read from that
    //! obligation. `negated` was computed over the whole statement while the subject and the
    //! condition came from the obligation clause, so a `must not` in one sentence flipped a
    //! constraint minted from another. Measured: 4 of 20 negated records corpus-wide carry a
    //! negation that is not in their own clause.
    use super::*;

    fn constraint(text: &str, declared: &[&str]) -> Vec<SignalConstraintRecord> {
        let declarations = ExtractedStatement {
            statement_id: "declarations".into(),
            class: StatementClass::SourceFact,
            modality: EvidenceModality::Text,
            text: declared
                .iter()
                .map(|name| format!("Signal {name} is input width 1."))
                .collect::<Vec<_>>()
                .join(" "),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        };
        let statement = ExtractedStatement {
            statement_id: "obligation".into(),
            class: StatementClass::SignalValueConstraint,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        };
        let mut counter = 0usize;
        extract_signal_constraints(&[declarations, statement], &mut counter)
    }

    /// The defect: a negation in a DIFFERENT sentence of the same statement flipped the record.
    /// Reproduces RISC-V IOMMU `dyn_sigcon_0008`/`0009` on invented names.
    #[test]
    fn a_negation_in_another_sentence_does_not_negate_this_obligation() {
        let records = constraint(
            "The ZETADV operand must be 1 for ZETADIR. A command must not be issued while the queue \
             is full.",
            &["ZETADV", "ZETADIR"],
        );
        assert!(!records.is_empty(), "the obligation still extracts");
        for record in &records {
            assert!(
                !record.negated,
                "the `must not` belongs to the second sentence: {record:?}"
            );
        }
    }

    /// The control that keeps the narrowing honest: the SAME negation, moved INTO the obligation
    /// clause, is read from that clause. The pair is the property — the flag follows the clause, not
    /// the statement.
    ///
    /// **Amended by `EXTRACTION-QUALITY-GAUGE.3k.2a`/`.3k.2b`.** This used to assert on a published
    /// record, and the record it was reading had a fabricated kind: the classifier could not type
    /// `must not be 1` (no affirmative phrase matches a negated obligation — `.3i`'s own finding), so
    /// the value came from the OTHER sentence's `a command must be issued` and the record was
    /// `must_be_value ISSUED`. `.3k.2b` refuses that participle and `.3k.2a` then refuses the untyped
    /// remainder, so the statement now publishes nothing at all — which is correct, and which makes
    /// the real gap visible: **`extract_protocol_state_value` has no negated form, so
    /// `must not be 1` is unreadable** (`.3k.2d`). The property this control exists for is asserted
    /// where it actually lives, on the span the flag is read from.
    #[test]
    fn a_negation_in_this_obligation_still_negates_it() {
        let statement = "The ZETADV operand must not be 1 for ZETADIR. A command must be issued \
                         while the queue is empty.";
        assert!(obligation_is_negated(
            &constraint_bearing_sentence(statement).to_ascii_lowercase()
        ));
        // And the whole statement is NOT the span: its second sentence is affirmative, so reading
        // the flag from there would answer differently.
        assert!(!obligation_is_negated(
            &constraint_bearing_sentence("A command must be issued while the queue is empty.")
                .to_ascii_lowercase()
        ));
        // Today the clause types nothing, so no record is published — the honest residual `.3k.2d`
        // owns, never a constraint carrying a value lifted out of the next sentence.
        assert!(constraint(statement, &["ZETADV", "ZETADIR"]).is_empty());
    }

    /// The passive and negative spellings of two obligations the phrase table only carried in the
    /// active/affirmative form, so they fell to the untyped default and then took a negation on top
    /// of it — AHB `sigcon_0003`/`0005`, APB `row_sigcon_0017`.
    #[test]
    fn the_passive_and_negative_spellings_reach_their_own_kinds() {
        for (text, signal, kind) in [
            (
                "The size of the transfer, as indicated by ZETASIZE, must not be changed.",
                "ZETASIZE",
                "must_not_change",
            ),
            (
                "ZETAOKAY must not be asserted in the same cycle as ZETARESP is asserted.",
                "ZETAOKAY",
                "must_be_deasserted",
            ),
            (
                "ZETASTRB must not be active during a read transfer.",
                "ZETASTRB",
                "must_be_deasserted",
            ),
        ] {
            let records = constraint(text, &[signal, "ZETARESP"]);
            let record = records
                .iter()
                .find(|r| r.subject_signal == signal)
                .unwrap_or_else(|| panic!("no record for {signal} from {text:?}"));
            assert_eq!(record.constraint_kind.as_str(), kind, "{text:?}");
            // WIRE-BASED-100.5b: a kind that encodes its own negation must not also carry the flag,
            // or the pair reads as a double negative.
            assert!(
                !record.negated,
                "{kind} already encodes the negation: {record:?}"
            );
        }
    }

    /// Guard: the affirmative forms are untouched — the new strings are reached only after the
    /// `must be asserted` arm and do not contain it.
    #[test]
    fn the_affirmative_forms_are_unchanged() {
        let asserted = constraint("ZETASEL must be asserted.", &["ZETASEL"]);
        assert_eq!(
            asserted.first().expect("record").constraint_kind.as_str(),
            "must_be_asserted"
        );
        let changed = constraint("ZETAADDR must remain stable.", &["ZETAADDR"]);
        assert_eq!(
            changed.first().expect("record").constraint_kind.as_str(),
            "must_not_change"
        );
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_1 {
    //! `EXTRACTION-QUALITY-GAUGE.3k.1` — a comparative MAGNITUDE whose right operand is a REFERENCE
    //! states a relation the constraint vocabulary cannot hold, so the deterministic paths fabricate
    //! one. AMBA DTI published `OAS must_be_stable, negated` and `DTI must_be_stable, negated` —
    //! *"OAS must not be stable"* — from a sentence about a range comparison. Measured population:
    //! 4 records, all in the pattern path, all in that one document; 0 in the dynamic, row and LLM
    //! paths. The controls below are the line the rule must not cross: a magnitude against a
    //! LITERAL is a value binding and still extracts.
    use super::*;

    fn declarations(names: &[&str]) -> Vec<ExtractedStatement> {
        names
            .iter()
            .map(|name| ExtractedStatement {
                statement_id: format!("declare_{name}"),
                class: StatementClass::SourceFact,
                modality: EvidenceModality::Text,
                text: format!("Signal {name} is input width 1."),
                evidence_span_ids: vec![],
                related_visual_evidence_ids: vec![],
            })
            .collect()
    }

    fn pattern_records(text: &str, declared: &[&str]) -> Vec<SignalConstraintRecord> {
        let mut statements = declarations(declared);
        statements.push(ExtractedStatement {
            statement_id: "obligation".into(),
            class: StatementClass::SignalValueConstraint,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        });
        let mut counter = 0usize;
        extract_signal_constraints(&statements, &mut counter)
    }

    fn dynamic_records(text: &str, declared: &[&str]) -> Vec<SignalConstraintRecord> {
        let mut statements = declarations(declared);
        statements.push(ExtractedStatement {
            statement_id: "narration".into(),
            class: StatementClass::NormativeStatement,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        });
        let mut counter = 0usize;
        extract_dynamic_signal_constraints(&statements, &mut counter, &HashSet::new())
    }

    /// The defect as the CURRENT extractor still reaches it: a bound stated against another
    /// operand, with the constrained signal named before the obligation's lead. No phrase in the
    /// kind table matches, so the classifier falls to its untyped default and the `must not` is
    /// stacked on top — the record asserts *"ZETARANGE must not be stable"*, which is not what the
    /// sentence says and not a thing any sentence of this shape says.
    ///
    /// Reverting either call site makes this emit `MustBeStable`/`negated: true`, which is exactly
    /// the pair AMBA DTI published.
    #[test]
    fn a_magnitude_against_a_referenced_operand_yields_no_constraint() {
        let records = pattern_records(
            "ZETARANGE must not be greater than the size indicated by the ZETAOAS field.",
            &["ZETARANGE", "ZETAOAS"],
        );
        assert!(
            records.is_empty(),
            "a bound stated against another operand has no typed slot: {records:?}"
        );
    }

    /// The PUBLISHED shape, and the honest reason it is not this leaf's reproducer: AMBA DTI's own
    /// sentence puts every candidate subject AFTER the obligation's lead (`OAS` and `DTI` are named
    /// only in *"must not be greater than the size indicated by the OAS field of the
    /// DTI\_TBU\_CONDIS\_ACK message"*), so `CORPUS-COVERAGE.2.50a`'s pre-lead subject authority
    /// reaches it first and today's extractor already yields nothing. The four records the persisted
    /// artifact still carries predate that gate; the artifact is frozen because the document has no
    /// normalized bundle to rebuild from.
    ///
    /// This test therefore passes with or without this leaf's gate, and says so. It is here to pin
    /// the claim — it fails the day the upstream gate stops covering the published shape, which is
    /// the day this leaf's gate becomes the only thing standing between that sentence and a
    /// fabricated record.
    #[test]
    fn the_published_shape_is_already_refused_by_the_pre_lead_subject_authority() {
        // The escaped underscores are the document's own: the normalizer emits
        // `ZETADTI\_TBU\_CONDIS\_ACK` and the subject tokenizer splits on the backslash, which is how
        // a message-name PREFIX became a constraint subject in the first place.
        let text = "The range given by this field must not be greater than the size indicated by \
                    the ZETAOAS field of the ZETADTI\\_TBU\\_CONDIS\\_ACK message. For example, if \
                    the ZETAOAS is 4GB, this field must indicate a range of 1GB or less.";
        assert!(is_post_passive_binding_only_subject(text, "ZETAOAS"));
        assert!(is_post_passive_binding_only_subject(text, "ZETADTI"));
        assert!(pattern_records(text, &["ZETAOAS", "ZETADTI"]).is_empty());
    }

    /// The control that keeps the refusal from becoming a comparative ban: the SAME grammar with a
    /// LITERAL right operand is an ordinary value binding and still extracts.
    #[test]
    fn a_magnitude_against_a_literal_still_yields_its_constraint() {
        let records = pattern_records(
            "The value of ZETARANGE must be greater than 0.",
            &["ZETARANGE"],
        );
        assert!(
            !records.is_empty(),
            "a magnitude against a literal is a value binding, not a relation"
        );
    }

    /// The dynamic path carries the same gate even though its measured population is zero, so the
    /// class cannot re-enter through the producer this one did not reach.
    #[test]
    fn a_magnitude_against_a_referenced_operand_yields_no_dynamic_constraint() {
        let records = dynamic_records(
            "The controller drives ZETARANGE LOW whenever the requested span is larger than the \
             number of entries the ZETAOAS field reports.",
            &["ZETARANGE", "ZETAOAS"],
        );
        assert!(
            records.is_empty(),
            "the dynamic value-binding path refuses the same relation: {records:?}"
        );
    }

    /// The dynamic path's own literal control — the shape the corpus actually contains (HBM2 sets a
    /// signal HIGH when a COUNT exceeds a number). The binding survives the gate.
    #[test]
    fn a_logic_level_binding_past_a_literal_magnitude_still_extracts() {
        let records = dynamic_records(
            "The device inverts read data and sets ZETADBI HIGH when the number of transitioning \
             data bits within a byte is greater than 4.",
            &["ZETADBI"],
        );
        assert_eq!(
            records
                .iter()
                .map(|record| record.constraint_kind.as_str())
                .collect::<Vec<_>>(),
            vec!["must_be_high"],
            "a count compared against a literal is not a relational magnitude"
        );
    }

    /// The reference lead must follow the comparative IMMEDIATELY. A sentence that merely mentions
    /// "the value of X" somewhere and separately compares against a literal is not this class —
    /// otherwise the gate would refuse by co-occurrence, which is how `.3g` over-killed.
    #[test]
    fn the_reference_lead_must_immediately_follow_the_comparative() {
        assert!(is_reference_magnitude_constraint(
            "must not be greater than the size indicated by the ZETAOAS field"
        ));
        assert!(!is_reference_magnitude_constraint(
            "the value of ZETAOAS must be greater than 4"
        ));
        assert!(!is_reference_magnitude_constraint(
            "speeds greater than 1 MHz drive the controller"
        ));
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_6 {
    //! `EXTRACTION-QUALITY-GAUGE.3k.6` — the replay that separates what SpecForge PUBLISHED from what
    //! its current producer would mint. `.3k.1` sized itself on four published records and found the
    //! current extractor reproduces none of them; only 24 of 78 documents can be rebuilt, so that is
    //! a standing property of the corpus rather than one document's accident.
    use super::*;

    fn statement(id: &str, class: StatementClass, text: &str) -> ExtractedStatement {
        ExtractedStatement {
            statement_id: id.to_string(),
            class,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        }
    }

    fn published(
        id: &str,
        subject: &str,
        kind: SignalConstraintKind,
        text: &str,
    ) -> SignalConstraintRecord {
        SignalConstraintRecord {
            constraint_id: id.to_string(),
            subject_signal: subject.to_string(),
            constraint_kind: kind,
            target_value: None,
            condition_text: None,
            negated: false,
            source_text: text.to_string(),
            supporting_statement_ids: vec!["obligation".to_string()],
            automation_confidence: AutomationConfidence::Medium,
        }
    }

    /// A record the current producer still mints comes back `reproduced`, and the identity compared
    /// is the merge key — the published id never has to match the replay's.
    #[test]
    fn a_record_the_current_producer_still_mints_is_reproduced() {
        let text = "ZETASTRB must be stable.";
        let statements = vec![
            statement(
                "declare",
                StatementClass::SourceFact,
                "Signal ZETASTRB is input width 1.",
            ),
            statement("obligation", StatementClass::SignalValueConstraint, text),
        ];
        let persisted = vec![published(
            "sigcon_0001",
            "ZETASTRB",
            SignalConstraintKind::MustBeStable,
            text,
        )];
        let report = replay_persisted_signal_constraints(&statements, &persisted, &[], None);
        assert_eq!(report.persisted_total, 1);
        assert!(report.verdicts[0].reproduced, "{:?}", report.verdicts);
        assert!(report.verdicts[0].refused_by.is_empty());
    }

    /// The published-but-frozen shape, and the whole point of the instrument: AMBA DTI's record
    /// survives in its artifact and no longer comes out, and the report names BOTH gates that stand
    /// between that sentence and the record — the one this family added and the one that was already
    /// there, which is what `.3k.1` had to discover by hand.
    #[test]
    fn a_published_record_the_current_producer_refuses_is_named_with_its_gates() {
        let text = "The range given by this field must not be greater than the size indicated by \
                    the ZETAOAS field of the ZETADTI\\_TBU\\_CONDIS\\_ACK message.";
        let statements = vec![
            statement(
                "declare",
                StatementClass::SourceFact,
                "Signal ZETAOAS is input width 1.",
            ),
            statement("obligation", StatementClass::SignalValueConstraint, text),
        ];
        let persisted = vec![published(
            "sigcon_0002",
            "ZETAOAS",
            SignalConstraintKind::MustBeStable,
            text,
        )];
        let report = replay_persisted_signal_constraints(&statements, &persisted, &[], None);
        let verdict = &report.verdicts[0];
        assert!(!verdict.reproduced);
        assert!(
            verdict
                .refused_by
                .contains(&"EXTRACTION-QUALITY-GAUGE.3k.1 reference-magnitude"),
            "{:?}",
            verdict.refused_by
        );
        assert!(
            verdict
                .refused_by
                .contains(&"CORPUS-COVERAGE.2.50a post-passive-binding-only"),
            "{:?}",
            verdict.refused_by
        );
    }

    /// The property that makes a NOT-REPRODUCED verdict worth acting on: the replay runs a catalog
    /// WIDENED by every published subject, so a record whose subject no statement declares any more
    /// still gets a fair trial. Without that, "not reproduced" would frequently mean "the catalog
    /// shrank", which is a different finding entirely.
    #[test]
    fn a_subject_no_statement_declares_is_still_granted_its_trial() {
        let text = "ZETAKEEP must be stable.";
        // No `Signal ZETAKEEP is ...` statement: the document's catalog no longer declares it.
        let statements = vec![statement(
            "obligation",
            StatementClass::SignalValueConstraint,
            text,
        )];
        let persisted = vec![published(
            "sigcon_0003",
            "ZETAKEEP",
            SignalConstraintKind::MustBeStable,
            text,
        )];
        let report = replay_persisted_signal_constraints(&statements, &persisted, &[], None);
        assert!(
            report.verdicts[0].reproduced,
            "the published subject is admitted to the replay catalog: {:?}",
            report.verdicts
        );
    }

    /// Only the two deterministic strata are in scope. `row_sigcon_*` and `llm_sigcon_*` come from
    /// producers this replay does not run, and reporting them as "not reproduced" would be the
    /// producer-stratum error `[[constraint-record-producer-strata]]` records.
    #[test]
    fn only_the_deterministic_strata_are_judged() {
        let text = "ZETASTRB must be stable.";
        let statements = vec![
            statement(
                "declare",
                StatementClass::SourceFact,
                "Signal ZETASTRB is input width 1.",
            ),
            statement("obligation", StatementClass::SignalValueConstraint, text),
        ];
        let persisted = vec![
            published(
                "sigcon_0001",
                "ZETASTRB",
                SignalConstraintKind::MustBeStable,
                text,
            ),
            published(
                "row_sigcon_0001",
                "ZETASTRB",
                SignalConstraintKind::MustBeStable,
                text,
            ),
            published(
                "llm_sigcon_0001",
                "ZETASTRB",
                SignalConstraintKind::MustBeStable,
                text,
            ),
        ];
        let report = replay_persisted_signal_constraints(&statements, &persisted, &[], None);
        assert_eq!(report.persisted_total, 1);
        assert_eq!(report.verdicts.len(), 1);
        assert_eq!(report.verdicts[0].constraint_id, "sigcon_0001");
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2e {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2e` — the table-row reader's untyped fallback.
    //!
    //! `.3k.2a` refused the terminal `MustBeStable` in the statement path and kept it here, because
    //! this reader has already proved via `obligation_subject` that its clause binds to its row's own
    //! signal — so an untyped obligation looked like a real obligation with a spelling the table
    //! lacks. That was true of the population it was reasoning about: four APB `must have the same
    //! value` clauses, which `.3k.2c` then typed. What reaches the fallback now is a clause whose
    //! obligation the vocabulary cannot express at all. Proving the SUBJECT does not make the KIND
    //! readable.
    use super::*;
    use tempfile::tempdir;

    fn header(text: &str) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header: true,
        }
    }

    fn cell(text: &str) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header: false,
        }
    }

    fn read_rows(rows: Vec<Vec<StructuredTableCellRecord>>) -> Result<Vec<SignalConstraintRecord>> {
        let tempdir = tempdir()?;
        let source = tempdir.path().join("spec.md");
        let base = tempdir.path().join("generated").join("source_ir");
        fs::write(&source, "# Signal descriptions\n")?;
        let mut source_ir = SourceIr::build(&source, &base)?;
        let row_count = rows.len() as u32 + 1;
        source_ir.structured_tables.push(StructuredTableRecord {
            table_id: "table_0001".to_string(),
            asset_id: "asset_0001".to_string(),
            page_id: None,
            caption_text: Some("Signal descriptions".to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![vec![
                header("Signal"),
                header("Width"),
                header("Source"),
                header("Description"),
            ]],
            body_rows: rows,
            row_count,
            col_count: 4,
        });
        let known: HashSet<String> = ["ZETAREADY", "OMEGABURST", "ALPHACHUNK", "SIGMASTRB"]
            .into_iter()
            .map(String::from)
            .collect();
        let mut counter = 0usize;
        Ok(extract_signal_description_row_constraints(
            &source_ir,
            &[],
            &known,
            &mut counter,
            None,
        ))
    }

    /// The population the fallback actually holds, read from the corpus and reproduced here on
    /// invented names: a MATCH against another operand, an ALIGNMENT, and a PRESENCE claim. Each
    /// clause binds to its own row's signal, so the reader admits it — and then the vocabulary has no
    /// kind for it, and the fallback answers `must_be_stable` for all three.
    #[test]
    fn a_clause_the_vocabulary_cannot_type_publishes_nothing() -> Result<()> {
        let records = read_rows(vec![
            vec![
                cell("ZETAREADY"),
                cell("1"),
                cell("Requester"),
                cell("ZETAREADY must match OMEGABURST."),
            ],
            vec![
                cell("OMEGABURST"),
                cell("2"),
                cell("Completer"),
                cell("Must be aligned to a burst size."),
            ],
            vec![
                cell("SIGMASTRB"),
                cell("8"),
                cell("Requester"),
                cell("Must not be present."),
            ],
        ])?;
        assert!(
            records.is_empty(),
            "none of these states a kind the vocabulary has; an honest residual keeps the statement \
             counted as uncaptured, a fabricated stability claim does not: {records:?}"
        );
        Ok(())
    }

    /// The over-kill guard, and it is the half that decides whether this refusal is safe: every arm
    /// the DOCUMENT states still publishes from a row. These are the four shapes the 12 live
    /// `row_sigcon_*` records are made of — validity with the subject in the header, `.3k.2c`'s
    /// no-change spelling, a negative polarity form, and a plain value binding.
    #[test]
    fn every_obligation_the_document_types_still_publishes() -> Result<()> {
        let records = read_rows(vec![
            vec![
                cell("ZETAREADY"),
                cell("1"),
                cell("Requester"),
                cell("Response for the read channels. Must be valid when ALPHACHUNK is asserted."),
            ],
            vec![
                cell("ALPHACHUNK"),
                cell("4"),
                cell("Requester"),
                cell("ALPHACHUNK must have the same value in the Setup and Access phase."),
            ],
            vec![
                cell("SIGMASTRB"),
                cell("8"),
                cell("Requester"),
                cell("SIGMASTRB must not be active during a read transfer."),
            ],
            vec![
                cell("OMEGABURST"),
                cell("2"),
                cell("Completer"),
                cell("OMEGABURST must be 0 for a fixed burst."),
            ],
        ])?;
        let kinds: Vec<(&str, &str)> = records
            .iter()
            .map(|record| {
                (
                    record.subject_signal.as_str(),
                    record.constraint_kind.as_str(),
                )
            })
            .collect();
        assert_eq!(
            kinds,
            vec![
                ("ZETAREADY", "must_be_value"),
                ("ALPHACHUNK", "must_not_change"),
                ("SIGMASTRB", "must_be_deasserted"),
                ("OMEGABURST", "must_be_value"),
            ],
            "the refusal must cost nothing the document states: {records:?}"
        );
        Ok(())
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2f {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2f` — a refusal that says the constraint VOCABULARY has no slot
    //! for what a clause states belongs to the rule, not to one caller.
    //!
    //! `.3d` refuses an inter-operand EQUALITY and `.3k.1` a comparative MAGNITUDE against a
    //! reference operand, and both were evaluated only inside `extract_signal_constraints`. The
    //! table-row reader called neither, so the same sentence was refused as a statement and published
    //! as a row — with a kind nothing in it states.
    use super::*;
    use tempfile::tempdir;

    fn header(text: &str) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header: true,
        }
    }

    fn cell(text: &str) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header: false,
        }
    }

    /// One signal-description table carrying `rows`, read by the REAL row producer.
    fn read_rows(rows: Vec<Vec<StructuredTableCellRecord>>) -> Result<Vec<SignalConstraintRecord>> {
        let tempdir = tempdir()?;
        let source = tempdir.path().join("spec.md");
        let base = tempdir.path().join("generated").join("source_ir");
        fs::write(&source, "# Signal descriptions\n")?;
        let mut source_ir = SourceIr::build(&source, &base)?;
        let row_count = rows.len() as u32 + 1;
        source_ir.structured_tables.push(StructuredTableRecord {
            table_id: "table_0001".to_string(),
            asset_id: "asset_0001".to_string(),
            page_id: None,
            caption_text: Some("Signal descriptions".to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![vec![
                header("Signal"),
                header("Width"),
                header("Source"),
                header("Description"),
            ]],
            body_rows: rows,
            row_count,
            col_count: 4,
        });
        let known: HashSet<String> = ["ZETARANGE", "ZETAOAS", "OMEGABURST", "ZETAREADY"]
            .into_iter()
            .map(String::from)
            .collect();
        let mut counter = 0usize;
        Ok(extract_signal_description_row_constraints(
            &source_ir,
            &[],
            &known,
            &mut counter,
            None,
        ))
    }

    /// The defect, in both of its shapes. Each clause binds to its own row's signal, so the row
    /// reader admits it and then has to name a kind — and the vocabulary has none, so it invents one:
    /// a comparative magnitude becomes `must not be stable`, an equality becomes a value lifted out
    /// of the phrase `the value of`.
    #[test]
    fn a_clause_with_no_vocabulary_slot_is_refused_in_the_row_path_too() -> Result<()> {
        let records = read_rows(vec![
            vec![
                cell("ZETARANGE"),
                cell("6"),
                cell("Requester"),
                cell("ZETARANGE must not be greater than the size indicated by the ZETAOAS field."),
            ],
            vec![
                cell("OMEGABURST"),
                cell("2"),
                cell("Completer"),
                cell("OMEGABURST must be equal to the value of ZETAREADY."),
            ],
        ])?;
        assert!(
            records.is_empty(),
            "neither relation has a typed slot; an honest residual is correct where a fabricated \
             fact is not: {records:?}"
        );
        Ok(())
    }

    /// The line both refusals are keyed on, asserted from the row path so the gate cannot quietly
    /// widen into ordinary value bindings. A magnitude against a LITERAL carries no reference lead
    /// and is a real constraint; the refusals must keep not firing on it.
    #[test]
    fn a_bound_against_a_literal_is_still_a_constraint() -> Result<()> {
        let records = read_rows(vec![vec![
            cell("ZETARANGE"),
            cell("6"),
            cell("Requester"),
            cell("ZETARANGE must be stable when ZETAREADY is asserted."),
        ]])?;
        assert_eq!(
            records.len(),
            1,
            "an ordinary row obligation is untouched: {records:?}"
        );
        assert_eq!(records[0].subject_signal, "ZETARANGE");
        assert_eq!(records[0].constraint_kind.as_str(), "must_be_stable");
        assert!(!is_reference_magnitude_constraint(
            "ZETARANGE must be greater than 0"
        ));
        assert!(!is_relational_equality_constraint(
            "ZETARANGE must have the same value in the Setup and Access phase"
        ));
        Ok(())
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2g {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2g` — the replay instrument judged two of the three deterministic
    //! producers and said nothing about the third. `.3k.2c` had to state in prose that its retype
    //! "is inside the row stratum, which the replay does not judge", and `.3k.2d` had to rebuild a
    //! whole document chain to prove that same stratum unmoved. An instrument a family sizes itself
    //! with cannot have a producer-shaped hole in it.
    //!
    //! The second half is the one that had to be measured rather than assumed: a LEGACY `SourceIr`
    //! loads, but every typed classification on it is neutralized to `Unknown`, so the row producer
    //! selects no table and returns an empty result — indistinguishable, to a caller, from "this
    //! document states no row obligation". Judging the stratum on such an artifact would publish a
    //! silent zero, which is the exact failure this instrument exists to retire.
    use super::*;
    use tempfile::tempdir;

    fn statement(id: &str, class: StatementClass, text: &str) -> ExtractedStatement {
        ExtractedStatement {
            statement_id: id.to_string(),
            class,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        }
    }

    fn cell(text: &str) -> StructuredTableCellRecord {
        StructuredTableCellRecord {
            text: text.to_string(),
            row_span: 1,
            col_span: 1,
            is_header: false,
        }
    }

    /// A `SourceIr` carrying one signal-description table, built by the real builder so it is
    /// current-schema and its classifications are canonical.
    fn source_with_signal_table() -> Result<SourceIr> {
        let tempdir = tempdir()?;
        let source = tempdir.path().join("spec.md");
        let base = tempdir.path().join("generated").join("source_ir");
        fs::write(&source, "# Signal descriptions\n")?;
        let mut source_ir = SourceIr::build(&source, &base)?;
        let body = vec![vec![
            cell("ZETAREADY"),
            cell("1"),
            cell("Requester"),
            cell("ZETAREADY must be stable when ZETASELX is asserted."),
        ]];
        source_ir.structured_tables.push(StructuredTableRecord {
            table_id: "table_0001".to_string(),
            asset_id: "asset_0001".to_string(),
            page_id: None,
            caption_text: Some("Signal descriptions".to_string()),
            source_ref: None,
            source_batch: None,
            table_kind: TableKind::SignalDescription,
            header_rows: vec![vec![
                StructuredTableCellRecord {
                    text: "Signal".to_string(),
                    row_span: 1,
                    col_span: 1,
                    is_header: true,
                },
                StructuredTableCellRecord {
                    text: "Width".to_string(),
                    row_span: 1,
                    col_span: 1,
                    is_header: true,
                },
                StructuredTableCellRecord {
                    text: "Source".to_string(),
                    row_span: 1,
                    col_span: 1,
                    is_header: true,
                },
                StructuredTableCellRecord {
                    text: "Description".to_string(),
                    row_span: 1,
                    col_span: 1,
                    is_header: true,
                },
            ]],
            body_rows: body,
            row_count: 2,
            col_count: 4,
        });
        Ok(source_ir)
    }

    fn statements() -> Vec<ExtractedStatement> {
        vec![
            statement(
                "declare",
                StatementClass::SourceFact,
                "Signal ZETAREADY is input width 1. Signal ZETASELX is input width 1.",
            ),
            statement(
                "row",
                StatementClass::SourceFact,
                "| ZETAREADY | 1 | Requester | ZETAREADY must be stable when ZETASELX is asserted. |",
            ),
        ]
    }

    fn published_row() -> SignalConstraintRecord {
        SignalConstraintRecord {
            constraint_id: "row_sigcon_0001".to_string(),
            subject_signal: "ZETAREADY".to_string(),
            constraint_kind: SignalConstraintKind::MustBeStable,
            target_value: None,
            condition_text: Some("ZETASELX is asserted".to_string()),
            negated: false,
            source_text: "ZETAREADY must be stable when ZETASELX is asserted".to_string(),
            supporting_statement_ids: vec!["row".to_string()],
            automation_confidence: AutomationConfidence::Medium,
        }
    }

    /// The gap itself: with the document's own `SourceIr`, a published `row_sigcon_*` record is
    /// judged and reproduces. Without it the record is not counted at all — and the pair is the
    /// property, because the alternative to "not judged" is not "judged fine", it is "reported lost".
    #[test]
    fn the_row_stratum_is_judged_only_when_its_producer_can_run() -> Result<()> {
        let source_ir = source_with_signal_table()?;
        let statements = statements();
        let persisted = vec![published_row()];

        let judged =
            replay_persisted_signal_constraints(&statements, &persisted, &[], Some(&source_ir));
        assert!(judged.row_stratum_judged);
        assert_eq!(judged.persisted_total, 1, "{:?}", judged.verdicts);
        assert!(
            judged.verdicts[0].reproduced,
            "the row producer still mints it: {:?}",
            judged.verdicts
        );

        let unjudged = replay_persisted_signal_constraints(&statements, &persisted, &[], None);
        assert!(!unjudged.row_stratum_judged);
        assert_eq!(
            unjudged.persisted_total, 0,
            "an unreplayed stratum is excluded, never reported as lost: {:?}",
            unjudged.verdicts
        );
        Ok(())
    }

    /// The catalog half, stated with the measurement that bounds it. The row producer resolves its
    /// row's name through the catalog it is HANDED, so the replay unions the signal-description
    /// tables' own names in, exactly as the build's `known_signals` does.
    ///
    /// **This control asserts the composition, not an effect, and the difference is deliberate.**
    /// Measured over the corpus, dropping the union changes nothing in either direction: the totals
    /// stay at 183 persisted / 137 reproduced and `unpersisted_replay_records` stays at 126 with
    /// zero row records in it. It cannot change a VERDICT at all, because the replay already grants
    /// a synthetic declaration to every published subject — so a reproduction test written against
    /// it would pass either way and would be no check
    /// (`CLAIM_VERIFICATION.md` §2). The union is kept for the soundness argument rather than for a
    /// number: the replay's verdict is trustworthy only while it runs the producer on the BUILD's
    /// inputs, and `unpersisted_replay_records` — the direction `.3k.2e` has to read — would silently
    /// under-report on the first document whose row subjects are declared by table alone.
    #[test]
    fn the_replay_catalog_composes_the_same_two_halves_the_build_does() -> Result<()> {
        let source_ir = source_with_signal_table()?;
        let statements = vec![statement(
            "declare",
            StatementClass::SourceFact,
            "Signal ZETASELX is input width 1.",
        )];
        let from_statements = collect_known_signal_names(&statements);
        let from_tables = collect_signal_names_from_tables(&source_ir, None);
        assert!(!from_statements.contains("ZETAREADY"));
        assert!(
            from_tables.contains("ZETAREADY"),
            "the table half is the only source of this row's name: {from_tables:?}"
        );
        Ok(())
    }

    /// The measured reason the stratum is gated on the SCHEMA and not merely on the file existing.
    /// A legacy artifact loads and then reports `Unknown` for every classification, so a pass keyed
    /// on `SignalDescription` sees nothing. AMBA LTI is the corpus instance: its persisted SourceIR
    /// marks 25 tables `signal_description`, and after a legacy load 0 of its 88 tables pass the
    /// producer's gate.
    #[test]
    fn a_legacy_source_ir_is_not_a_classification_authority() -> Result<()> {
        let source_ir = source_with_signal_table()?;
        assert!(source_ir.carries_canonical_source_classifications());

        let mut legacy = source_ir.clone();
        legacy.schema_version -= 1;
        assert!(
            !legacy.carries_canonical_source_classifications(),
            "a legacy artifact's classifications were neutralized on load and cannot authorize a verdict"
        );

        // And the mechanism the gate exists for: neutralization is what a legacy load DOES, and it
        // leaves the row producer selecting no table at all. Same document, same rows, same
        // catalog — only the classification is gone, and the stratum silently empties.
        for table in &mut legacy.structured_tables {
            table.table_kind = TableKind::Unknown;
        }
        let mut counter = 0usize;
        let mut declared = collect_known_signal_names(&statements());
        declared.extend(collect_signal_names_from_tables(&source_ir, None));
        assert_eq!(
            extract_signal_description_row_constraints(
                &source_ir,
                &statements(),
                &declared,
                &mut counter,
                None
            )
            .len(),
            1,
            "the canonical artifact states one row obligation"
        );
        let mut counter = 0usize;
        assert!(
            extract_signal_description_row_constraints(
                &legacy,
                &statements(),
                &declared,
                &mut counter,
                None
            )
            .is_empty(),
            "neutralized classifications make the producer blind, not the document silent"
        );
        Ok(())
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2a {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2a` — the terminal `MustBeStable` was not a default, it was a
    //! fabrication. Every one of the 17 live statement-path records that reached it asserted
    //! stability about a sentence that never mentions stability: a barrier-transaction description,
    //! four `… is not present` table cells, a recommendation explicitly "not required", and six
    //! waveform narrations. The ROW path keeps the fallback on purpose — its four records are
    //! *correct* and merely under-typed (`must have the same value …`), because that path has already
    //! proved its clause binds to its row's signal.
    use super::*;

    fn pattern_records(text: &str, declared: &[&str]) -> Vec<SignalConstraintRecord> {
        let mut statements: Vec<ExtractedStatement> = declared
            .iter()
            .map(|name| ExtractedStatement {
                statement_id: format!("declare_{name}"),
                class: StatementClass::SourceFact,
                modality: EvidenceModality::Text,
                text: format!("Signal {name} is input width 1."),
                evidence_span_ids: vec![],
                related_visual_evidence_ids: vec![],
            })
            .collect();
        statements.push(ExtractedStatement {
            statement_id: "obligation".into(),
            class: StatementClass::SignalValueConstraint,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        });
        let mut counter = 0usize;
        extract_signal_constraints(&statements, &mut counter)
    }

    /// The defect: a sentence that states no kind at all published one. Reproduces the live AXI
    /// `sigcon_0008`–`0011` shape (a presence table cell) on invented names.
    #[test]
    fn a_statement_that_names_no_kind_yields_no_constraint() {
        let records = pattern_records(
            "| Manager: False | ZETACHUNKEN is not present. ZETACHUNKV is not present. |",
            &["ZETACHUNKEN", "ZETACHUNKV"],
        );
        assert!(
            records.is_empty(),
            "a statement naming no kind states no typed constraint: {records:?}"
        );
    }

    /// The same refusal on the other live shape — a recommendation the document explicitly marks as
    /// NOT required (APB `sigcon_0007`).
    #[test]
    fn a_recommendation_that_names_no_kind_yields_no_constraint() {
        let records = pattern_records(
            "It is recommended, but not required, that ZETASLVERR is driven LOW when ZETASEL is LOW.",
            &["ZETASLVERR", "ZETASEL"],
        );
        assert!(records.is_empty(), "{records:?}");
    }

    /// The control that keeps the refusal from swallowing the vocabulary: an obligation that DOES
    /// name its kind is untouched, including the stability kind the default was impersonating.
    #[test]
    fn an_obligation_that_names_its_kind_still_extracts() {
        for (text, expected) in [
            ("ZETAADDR must be stable.", "must_be_stable"),
            ("ZETASEL must be asserted.", "must_be_asserted"),
            ("ZETASTRB must not change.", "must_not_change"),
        ] {
            let records = pattern_records(text, &["ZETAADDR", "ZETASEL", "ZETASTRB"]);
            assert_eq!(
                records
                    .first()
                    .unwrap_or_else(|| panic!("a record for {text}"))
                    .constraint_kind
                    .as_str(),
                expected
            );
        }
    }

    /// The asymmetry itself, pinned where it lives: the row path's classifier still answers
    /// `MustBeStable` for an obligation the phrase table cannot type, while the statement path's
    /// asks a question the row path does not and gets `None`.
    ///
    /// The example moved once, and the move is the family working. This control originally used
    /// `must have the same value …`, the live APB shape; `.3k.2c` gave that obligation its own arm,
    /// so it is no longer untyped. The shape used now is the live AXI one — a presence cell, which
    /// states no obligation at all and which no spelling should ever type.
    #[test]
    fn the_row_path_fallback_is_unchanged_where_the_statement_path_refuses() {
        let lowered = "zetachunken is not present and the manager must ignore it";
        let discovered = HashSet::new();
        assert_eq!(
            classify_signal_constraint_kind(lowered, &discovered),
            SignalConstraintKind::MustBeStable
        );
        assert_eq!(
            classify_signal_constraint_kind_typed(lowered, &discovered),
            None
        );
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2b {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2b` — a passive obligation puts its VERB in the value slot.
    //! *"the entry must be invalidated"* published `GSCID must_be_value INVALIDATED`; *"the tags in
    //! memory must be updated"* published `WTAGUPDATE must_be_value UPDATED`. The same slot in
    //! *"AWTAGOP must be Invalid"* holds an adjective, and that one is a real value — which is why
    //! this is a gate on the participle's shape, overridden by the document's own vocabulary, and
    //! not a refusal of the arm.
    use super::*;

    fn records(
        text: &str,
        declared: &[&str],
        enum_members: &[&str],
    ) -> Vec<SignalConstraintRecord> {
        let mut statements: Vec<ExtractedStatement> = declared
            .iter()
            .map(|name| ExtractedStatement {
                statement_id: format!("declare_{name}"),
                class: StatementClass::SourceFact,
                modality: EvidenceModality::Text,
                text: format!("Signal {name} is input width 1."),
                evidence_span_ids: vec![],
                related_visual_evidence_ids: vec![],
            })
            .collect();
        for (index, member) in enum_members.iter().enumerate() {
            statements.push(ExtractedStatement {
                statement_id: format!("enum_{index}"),
                class: StatementClass::SourceFact,
                modality: EvidenceModality::Text,
                text: format!("Enum ZETASTATES {member} = {index}."),
                evidence_span_ids: vec![],
                related_visual_evidence_ids: vec![],
            });
        }
        statements.push(ExtractedStatement {
            statement_id: "obligation".into(),
            class: StatementClass::SignalValueConstraint,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        });
        let mut counter = 0usize;
        extract_signal_constraints(&statements, &mut counter)
    }

    fn kind_of(records: &[SignalConstraintRecord]) -> Option<String> {
        records.first().map(|record| match &record.constraint_kind {
            SignalConstraintKind::MustBeValue { value } => format!("must_be_value:{value}"),
            other => other.as_str().to_string(),
        })
    }

    /// The defect: the obligation's own verb published as the signal's value. With `.3k.2a` the
    /// clause then types nothing at all, so the statement path refuses it outright.
    #[test]
    fn a_passive_participle_in_the_value_slot_is_not_a_value() {
        assert_eq!(
            kind_of(&records(
                "The ZETAGSCID entry must be invalidated.",
                &["ZETAGSCID"],
                &[]
            )),
            None
        );
    }

    /// The control that keeps the gate from becoming a refusal of the arm: the same slot holding an
    /// ADJECTIVE is a real value and still binds. This is the live AXI `AWTAGOP must be Invalid`.
    #[test]
    fn an_adjective_in_the_value_slot_still_binds() {
        assert_eq!(
            kind_of(&records("ZETATAGOP must be Invalid.", &["ZETATAGOP"], &[])),
            Some("must_be_value:INVALID".to_string())
        );
    }

    /// The document's own vocabulary overrides the shape: a participle-shaped enum member the
    /// specification declares is a value, and stays one.
    #[test]
    fn a_participle_the_document_declares_as_a_value_is_admitted() {
        assert_eq!(
            kind_of(&records(
                "ZETASTATE must be Shared.",
                &["ZETASTATE"],
                &["Shared"]
            )),
            Some("must_be_value:SHARED".to_string())
        );
        // ... and without that declaration the same word is refused, which is the pair that makes
        // the override meaningful rather than decorative.
        assert_eq!(
            kind_of(&records("ZETASTATE must be Shared.", &["ZETASTATE"], &[])),
            None
        );
    }

    /// Logic levels and the `.8` validity convention are values by construction, and neither goes
    /// through this gate. Gating the validity arm was measured and reverted: it retyped 13 correct
    /// APB and 4 correct AHB records.
    #[test]
    fn logic_levels_and_the_validity_convention_are_untouched() {
        assert_eq!(
            kind_of(&records("ZETACKE must be held LOW.", &["ZETACKE"], &[])),
            Some("must_be_value:LOW".to_string())
        );
        assert_eq!(
            kind_of(&records(
                "ZETAUSER must be valid when ZETASEL is asserted.",
                &["ZETAUSER", "ZETASEL"],
                &[]
            )),
            Some("must_be_value:VALID".to_string())
        );
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2c {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2c` — the spelling this corpus uses for a no-change obligation.
    //! AMBA APB writes it as `PAUSER must have the same value in the Setup and Access phase of a
    //! transfer`; the phrase table knew `must be stable`, `must remain stable` and `must hold`, so
    //! four table-row obligations reached the untyped fallback and were published as
    //! `must_be_stable` by accident rather than by reading. They are the reason `.3k.2a` had to
    //! leave the row path's fallback in place.
    use super::*;

    fn kind(text: &str) -> SignalConstraintKind {
        classify_signal_constraint_kind(&text.to_ascii_lowercase(), &HashSet::new())
    }

    /// The defect: a real no-change obligation typed by the fallback.
    #[test]
    fn the_same_value_spelling_types_as_no_change() {
        assert_eq!(
            kind("ZETAUSER must have the same value in the Setup and Access phase of a transfer"),
            SignalConstraintKind::MustNotChange
        );
        assert_eq!(
            kind("ZETAUSER shall have the same value in every cycle during the Access phase"),
            SignalConstraintKind::MustNotChange
        );
    }

    /// The ORDER is the load-bearing part, and this is the pair that pins it. A serialized
    /// signal-description cell carries both obligations; the first arm to match types the whole
    /// record, so this phrase sits BEHIND the validity arm. Ahead of it, APB's
    /// `PAUSER`/`PWUSER must_be_value VALID` records were retyped and a stated fact was lost.
    #[test]
    fn a_cell_stating_both_obligations_keeps_its_validity_kind() {
        assert_eq!(
            kind(
                "User-defined request attribute. • ZETAUSER must be valid when ZETASELX is \
                 asserted. • ZETAUSER must have the same value in the Setup and Access phase of a \
                 transfer."
            ),
            SignalConstraintKind::MustBeValue {
                value: "VALID".to_string()
            }
        );
    }

    /// The phrase is an OBLIGATION's, not a description's. A register field that merely *has* the
    /// same value as another states nothing normative, and `.3d`'s inter-operand equality refusal
    /// must keep not firing on `the same value IN …`, which is a different preposition entirely.
    #[test]
    fn a_descriptive_same_value_sentence_is_not_this_obligation() {
        assert_ne!(
            kind("This register is distinct from ZETAPMCR. It does not have the same value."),
            SignalConstraintKind::MustNotChange
        );
        assert!(!is_relational_equality_constraint(
            "ZETAUSER must have the same value in the Setup and Access phase of a transfer"
        ));
        assert!(is_relational_equality_constraint(
            "ZETAUSER must have the same value as ZETAWUSER"
        ));
    }
}

#[cfg(test)]
mod extraction_quality_gauge_3k_2d {
    //! `EXTRACTION-QUALITY-GAUGE.3k.2d` — one modal vocabulary for the whole record.
    //!
    //! Three functions read a clause for its modal and each carried its own vocabulary:
    //! `obligation_is_negated` accepts `cannot`/`will not`/`must never`/`shall never`,
    //! `constraint_bearing_sentence` looked only for `must`/`shall`, and every phrase in
    //! `classify_signal_constraint_kind` is spelled `must`/`shall`. So an obligation a document
    //! states with `cannot` was flagged NEGATED by the first, given no sentence of its own by the
    //! second, and typed as nothing by the third. The two halves of one record read one clause
    //! against two different vocabularies, which is the same defect `.3i` found for the negation
    //! and `.3k.3` owns for the span.
    use super::*;

    fn constraint(text: &str, declared: &[&str]) -> Vec<SignalConstraintRecord> {
        let declarations = ExtractedStatement {
            statement_id: "declarations".into(),
            class: StatementClass::SourceFact,
            modality: EvidenceModality::Text,
            text: declared
                .iter()
                .map(|name| format!("Signal {name} is input width 1."))
                .collect::<Vec<_>>()
                .join(" "),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        };
        let statement = ExtractedStatement {
            statement_id: "obligation".into(),
            class: StatementClass::SignalValueConstraint,
            modality: EvidenceModality::Text,
            text: text.to_string(),
            evidence_span_ids: vec![],
            related_visual_evidence_ids: vec![],
        };
        let mut counter = 0usize;
        extract_signal_constraints(&[declarations, statement], &mut counter)
    }

    fn kind(text: &str) -> SignalConstraintKind {
        classify_signal_constraint_kind(&text.to_ascii_lowercase(), &HashSet::new())
    }

    /// Half one of the defect: the kind. The same obligation, the same arm, a different modal —
    /// `must not be changed` typed and `cannot be changed` did not. Every kind the table spells
    /// negatively is asserted, so the rule is the modal and not one phrase.
    #[test]
    fn the_equivalent_negative_modals_reach_the_same_kinds() {
        for text in [
            "The ZETALEN parameter cannot be changed once the burst has started",
            "The ZETALEN parameter can not be changed once the burst has started",
            "The ZETALEN parameter will not be changed once the burst has started",
            "The ZETALEN parameter must never be changed once the burst has started",
            "The ZETALEN parameter shall never be changed once the burst has started",
        ] {
            assert_eq!(kind(text), SignalConstraintKind::MustNotChange, "{text:?}");
        }
        for text in [
            "ZETAOKAY cannot be asserted in the same cycle as ZETARESP is asserted",
            "ZETAOKAY will not be active during a read transfer",
        ] {
            assert_eq!(
                kind(text),
                SignalConstraintKind::MustBeDeasserted,
                "{text:?}"
            );
        }
    }

    /// The kinds that already matched keep matching: normalization rewrites the MODAL only, so an
    /// affirmative clause is not touched and a negation stays exactly where the document put it.
    #[test]
    fn the_affirmative_and_canonical_spellings_are_untouched() {
        assert_eq!(
            normalize_obligation_modal("zetasel must be asserted"),
            "zetasel must be asserted"
        );
        assert!(matches!(
            normalize_obligation_modal("zetasel must be asserted"),
            std::borrow::Cow::Borrowed(_)
        ));
        assert_eq!(
            kind("ZETASEL must be asserted"),
            SignalConstraintKind::MustBeAsserted
        );
        assert_eq!(
            kind("ZETADATA must not be changed"),
            SignalConstraintKind::MustNotChange
        );
        assert_eq!(
            normalize_obligation_modal("zetalen cannot be changed"),
            "zetalen must not be changed"
        );
    }

    /// `WIRE-BASED-100.5b` still decides the flag, and it decides it the same way for every modal:
    /// a kind that encodes its own negation does not also carry `negated`, or the pair reads as a
    /// double negative.
    #[test]
    fn a_self_negating_kind_still_refuses_the_flag_under_any_modal() {
        for text in [
            "ZETALEN cannot be changed once the burst has started",
            "ZETALEN must not be changed once the burst has started",
        ] {
            let records = constraint(text, &["ZETALEN"]);
            let record = records
                .iter()
                .find(|record| record.subject_signal == "ZETALEN")
                .unwrap_or_else(|| panic!("no record for {text:?}"));
            assert_eq!(
                record.constraint_kind.as_str(),
                "must_not_change",
                "{text:?}"
            );
            assert!(!record.negated, "{text:?}: {record:?}");
        }
    }

    /// Half two of the defect, and the reason the two halves ship together. A statement whose
    /// obligation is stated with `cannot`/`will not` had no obligation SENTENCE, so
    /// `constraint_bearing_sentence` fell back to the whole text and the subject scan swept the
    /// serialized row's other cells. eMMC's `| NOTE 1 | … A Device that treats … as an illegal
    /// command will not change its state to the rcv state. … |` is the measured shape: teaching the
    /// classifier the modal WITHOUT teaching the sentence scan the same modal published two records
    /// whose subject is the row's `NOTE` marker. Narrowed, the row marker is not in the obligation's
    /// own sentence and no record is minted from it.
    #[test]
    fn the_obligation_sentence_is_found_by_the_same_modal_the_kind_is() {
        let row = "| ZETANOTE 1 | Due to legacy considerations, a device may treat a write during \
                   a programming state as a legal or an illegal command. A device that treats it \
                   as an illegal command will not change its state to the receive state. |";
        assert_eq!(
            constraint_bearing_sentence(row).trim(),
            "A device that treats it as an illegal command will not change its state to the \
             receive state"
        );
        assert!(
            constraint(row, &["ZETANOTE"]).is_empty(),
            "the row marker is not in the obligation's own sentence"
        );
    }

    /// The scan's vocabulary is exactly the negation detector's plus the two affirmative modals,
    /// asserted as a property rather than as a list of examples: every modal that can make a record
    /// NEGATED must also be able to give that record a sentence.
    #[test]
    fn every_negating_modal_can_locate_its_own_obligation_sentence() {
        for modal in [
            "must not",
            "shall not",
            "must never",
            "shall never",
            "cannot",
            "will not",
        ] {
            let text = format!("The bus is idle. ZETASTRB {modal} be driven during this phase.");
            let sentence = constraint_bearing_sentence(&text);
            assert!(
                sentence.contains("ZETASTRB"),
                "{modal}: narrowed to {sentence:?}"
            );
            assert!(
                obligation_is_negated(&sentence.to_ascii_lowercase()),
                "{modal}: not read as negated"
            );
        }
    }
}
